-- Corrections of the Synodal translation made by a friend of the church (module sp_rst.spb, 2026-10-14):
-- typos and wording fixed against the printed Synodal text in 588 verses, double spaces removed,
-- a second copy of Psalm 146:6 removed (it showed as an extra verse 6 at the end of the psalm),
-- title "Синодальный", book names "Песнь Песней" and "Иуды" (also in the New Russian Translation,
-- which uses the Synodal book names).
-- A verse is changed only if its text is still the original one, so corrections made in the church stay.
-- SoftProjector applies this file once when it starts (see applyDataFixes in source/main.cpp).

CREATE TEMP TABLE fix_synodal AS
SELECT CAST((SELECT id FROM BibleVersions WHERE abbreviation = 'RST') AS TEXT) AS rst,
       CAST((SELECT id FROM BibleVersions WHERE abbreviation = 'НРП') AS TEXT) AS nrt;

UPDATE BibleVersions SET bible_name = 'Русский Синодальный Перевод'
WHERE id = (SELECT rst FROM fix_synodal) AND bible_name = 'Русский Синодальний Перевод';
UPDATE BibleBooks SET book_name = 'Песнь Песней'
WHERE bible_id IN ((SELECT rst FROM fix_synodal), (SELECT nrt FROM fix_synodal)) AND id = 22 AND book_name = 'Песни Песней';
UPDATE BibleBooks SET book_name = 'Иуды'
WHERE bible_id IN ((SELECT rst FROM fix_synodal), (SELECT nrt FROM fix_synodal)) AND id = 65 AND book_name = 'Иуда';

-- Verses to change: the old text must still be in the database.
-- Verse 2 of the titles of psalms 50, 51, 53 and 59 got ids ending with "b" in 2026-10-14-bible-translations.sql.
CREATE TEMP TABLE fix_verses (verse_id TEXT, book TEXT, chapter INTEGER, verse INTEGER, old_text TEXT, new_text TEXT);

CREATE INDEX temp.fix_verses_id ON fix_verses (verse_id);

-- One pass over the verses instead of one per change, so starting the program stays quick
UPDATE BibleVerse SET verse_text = (
    SELECT f.new_text FROM fix_verses f
    WHERE f.verse_id = BibleVerse.verse_id AND f.book = BibleVerse.book
      AND f.chapter = BibleVerse.chapter AND f.verse = BibleVerse.verse) || char(10)
WHERE bible_id = (SELECT rst FROM fix_synodal)
  AND verse_id IN (SELECT verse_id FROM fix_verses)
  AND EXISTS (SELECT 1 FROM fix_verses f
              WHERE f.verse_id = BibleVerse.verse_id AND f.book = BibleVerse.book
                AND f.chapter = BibleVerse.chapter AND f.verse = BibleVerse.verse
                AND f.old_text = trim(BibleVerse.verse_text, char(10)));

DELETE FROM BibleVerse WHERE bible_id = (SELECT rst FROM fix_synodal) AND verse_id = 'B019C147V096' AND book = '19' AND chapter = 146 AND verse = 6 AND trim(verse_text, char(10)) = 'Смиренных возвышает Господь, а нечестивых унижает до земли.';

DROP TABLE fix_verses;
DROP TABLE fix_synodal;
