INSERT INTO fix_verses VALUES ('B001C001V011', '1', 1, 11, 'И сказал Бог: да произрастит земля зелень, траву, сеющую семя дерево плодовитое, приносящее по роду своему плод, в котором семя его на земле. И стало так.', 'И сказал Бог: да произрастит земля зелень, траву, сеющую семя, дерево плодовитое, приносящее по роду своему плод, в котором семя его на земле. И стало так.');
INSERT INTO fix_verses VALUES ('B001C001V029', '1', 1, 29, 'И сказал Бог: вот, Я дал вам всякую траву, сеющую семя, какая есть на всей земле, и всякое дерево, у которого плод древесный, сеющий семя;  — вам [сие] будет в пищу;', 'И сказал Бог: вот, Я дал вам всякую траву, сеющую семя, какая есть на всей земле, и всякое дерево, у которого плод древесный, сеющий семя; — вам [сие] будет в пищу;');
INSERT INTO fix_verses VALUES ('B001C007V023', '1', 7, 23, 'Истребилось всякое существо, которое было на поверхности земли; от человека до скота, и гадов, и птиц небесных,  — все истребилось с земли, остался только Ной и что [было] с ним в ковчеге.', 'Истребилось всякое существо, которое было на поверхности земли; от человека до скота, и гадов, и птиц небесных, — все истребилось с земли, остался только Ной и что [было] с ним в ковчеге.');
INSERT INTO fix_verses VALUES ('B001C010V007', '1', 10, 7, 'Сыны Хуша: Сева, Хавила, Савта, Раама и Савтеха. Сыны Раамы: Шева и дедан.', 'Сыны Хуша: Сева, Хавила, Савта, Раама и Савтеха. Сыны Раамы: Шева и Дедан.');
INSERT INTO fix_verses VALUES ('B001C010V009', '1', 10, 9, 'Он был сильный зверолов пред Господом; потому и говориться: сильный зверолов, как Нимрод, пред Господом.', 'Он был сильный зверолов пред Господом; потому и говорится: сильный зверолов, как Нимрод, пред Господом.');
INSERT INTO fix_verses VALUES ('B001C010V010', '1', 10, 10, 'Царство его вначале сщставляли: Вавилон, Эрех, аккад и Халне, в земле Сеннаар.', 'Царство его вначале составляли: Вавилон, Эрех, Аккад и Халне в земле Сеннаар.');
INSERT INTO fix_verses VALUES ('B001C010V011', '1', 10, 11, 'Из сей земли вышел Ассур, и построил Ниневию, Реховофир, Калах.', 'Из сей земли вышел Ассур и построил Ниневию, Реховоф-ир, Калах');
INSERT INTO fix_verses VALUES ('B001C010V012', '1', 10, 12, 'И ресен между Ниневию и между Калахом; это город великий.', 'И Ресен между Ниневиею и между Калахом; это город великий.');
INSERT INTO fix_verses VALUES ('B001C010V013', '1', 10, 13, 'От Мицраима произщшли Лудим, Анамим, Легавим, Нафтухим,', 'От Мицраима произошли Лудим, Анамим, Легавим, Нафтухим,');
INSERT INTO fix_verses VALUES ('B001C010V016', '1', 10, 16, 'Иевусей, Аморей, Гергесей,', 'Иевусей, Аморрей, Гергесей,');
INSERT INTO fix_verses VALUES ('B001C010V018', '1', 10, 18, 'Арвадей, Цемарей и Химарей. В последствии племена Ханаанские рассеялись.', 'Арвадей, Цемарей и Химафей. Впоследствии племена Ханаанские рассеялись,');
INSERT INTO fix_verses VALUES ('B001C010V019', '1', 10, 19, 'И были пределы Хананеев от Сидона к Герару до Газы, Отсюда к Садому, Гаморре, Адме и Цевоиму до Лаши.', 'И были пределы Хананеев от Сидона к Герару до Газы, отсюда к Содому, Гоморре, Адме и Цевоиму до Лаши.');
INSERT INTO fix_verses VALUES ('B001C010V022', '1', 10, 22, 'Сыны Сима: Елам, Асур, Арфаксад, Луд, Арам.', 'Сыны Сима: Елам, Ассур, Арфаксад, Луд, Арам.');
INSERT INTO fix_verses VALUES ('B001C010V025', '1', 10, 25, 'У Евера родились два сына; имя одному: Фалек, потому что во дни его земля разделена; имя брата его: Иоктан.', 'У Евера родились два сына; имя одному: Фалек, потому что во дни его земля разделена; имя брату его: Иоктан.');
INSERT INTO fix_verses VALUES ('B001C010V032', '1', 10, 32, 'Вот племена сынов Ноевых, по Родословию их, в народах их. От них распространились народы по земле после потопа.', 'Вот племена сынов Ноевых, по родословию их, в народах их. От них распространились народы по земле после потопа.');
INSERT INTO fix_verses VALUES ('B001C014V009', '1', 14, 9, 'С Кедорлаомером, царем Еламским, Фидалом, царем Гоимским, Амрафелом, царем Сеннаарским, Ариохом, царем Елласарским,  — четыре царя против пяти.', 'С Кедорлаомером, царем Еламским, Фидалом, царем Гоимским, Амрафелом, царем Сеннаарским, Ариохом, царем Елласарским, — четыре царя против пяти.');
INSERT INTO fix_verses VALUES ('B001C014V018', '1', 14, 18, 'И Мелхиседек, царь Салимский, вынес хлеб и вино,  — он был священник Бога Всевышнего,  —', 'И Мелхиседек, царь Салимский, вынес хлеб и вино, — он был священник Бога Всевышнего, —');
INSERT INTO fix_verses VALUES ('B001C019V020', '1', 19, 20, 'Вот, ближе бежать в сей город, он же мал; побегу я туда,  — он же мал; и сохранится жизнь моя.', 'Вот, ближе бежать в сей город, он же мал; побегу я туда, — он же мал; и сохранится жизнь моя.');
INSERT INTO fix_verses VALUES ('B001C024V007', '1', 24, 7, 'Господь, Бог неба, Который взял меня из дома отца моего и из земли рождения моего, Который говорил мне и Который клялся мне, говоря: «потомству твоему дам сию землю»,  — Он пошлет Ангела Своего пред тобою, и ты возьмешь жену сыну моему оттуда;', 'Господь, Бог неба, Который взял меня из дома отца моего и из земли рождения моего, Который говорил мне и Который клялся мне, говоря: «потомству твоему дам сию землю», — Он пошлет Ангела Своего пред тобою, и ты возьмешь жену сыну моему оттуда;');
INSERT INTO fix_verses VALUES ('B001C024V014', '1', 24, 14, 'И девица, которой я скажу: «наклони кувшин твой, я напьюсь», и которая скажет: «пей, я и верблюдам твоим дам пить»,  — вот та, которую Ты назначил рабу Твоему Исааку; и по сему узнаю я, что Ты творишь милость с господином моим.', 'И девица, которой я скажу: «наклони кувшин твой, я напьюсь», и которая скажет: «пей, я и верблюдам твоим дам пить», — вот та, которую Ты назначил рабу Твоему Исааку; и по сему узнаю я, что Ты творишь милость с господином моим.');
INSERT INTO fix_verses VALUES ('B001C024V030', '1', 24, 30, 'И когда он увидел серьгу и запястья на руках у сестры своей и услышал слова Ревекки, сестры своей, которая говорила: так говорил со мною этот человек,  — то пришел к человеку, и вот, он стоит при верблюдах у источника;', 'И когда он увидел серьгу и запястья на руках у сестры своей и услышал слова Ревекки, сестры своей, которая говорила: так говорил со мною этот человек, — то пришел к человеку, и вот, он стоит при верблюдах у источника;');
INSERT INTO fix_verses VALUES ('B001C024V044', '1', 24, 44, 'И которая скажет мне: «и ты пей, и верблюдам твоим я начерпаю»  — вот жена, которую Господь назначил сыну господина моего.', 'И которая скажет мне: «и ты пей, и верблюдам твоим я начерпаю» — вот жена, которую Господь назначил сыну господина моего.');
INSERT INTO fix_verses VALUES ('B001C028V021', '1', 28, 21, 'И я в мире возвращусь в дом отца моего, и будет Господь моим Богом,  —', 'И я в мире возвращусь в дом отца моего, и будет Господь моим Богом, —');
INSERT INTO fix_verses VALUES ('B001C031V030', '1', 31, 30, 'Но пусть бы ты ушел, потому что ты нетерпеливо захотел быть в доме отца твоего,  — зачем ты украл богов моих?', 'Но пусть бы ты ушел, потому что ты нетерпеливо захотел быть в доме отца твоего, — зачем ты украл богов моих?');
INSERT INTO fix_verses VALUES ('B001C034V003', '1', 34, 3, 'И прилепилась душа его в Дине, дочери Иакова, и он полюбил девицу и говорил по сердцу девицы.', 'И прилепилась душа его к Дине, дочери Иакова, и он полюбил девицу и говорил по сердцу девицы.');
INSERT INTO fix_verses VALUES ('B001C034V024', '1', 34, 24, 'И послушались Еммора и Сихема, сына его, все выходящие из ворот города его: и обрезан был весь мужеский пол,  — все выходящие из ворот города его.', 'И послушались Еммора и Сихема, сына его, все выходящие из ворот города его: и обрезан был весь мужеский пол, — все выходящие из ворот города его.');
INSERT INTO fix_verses VALUES ('B001C037V003', '1', 37, 3, 'Израиль любил Иосифа более всех сыновей своих, потому что он был сын старости его,  — и сделал ему разноцветную одежду.', 'Израиль любил Иосифа более всех сыновей своих, потому что он был сын старости его, — и сделал ему разноцветную одежду.');
INSERT INTO fix_verses VALUES ('B001C042V036', '1', 42, 36, 'И сказал им Иаков, отец их: вы лишили меня детей: Иосифа нет, и Симеона нет, и Вениамина взять хотите,  — все это на меня!', 'И сказал им Иаков, отец их: вы лишили меня детей: Иосифа нет, и Симеона нет, и Вениамина взять хотите, — все это на меня!');
INSERT INTO fix_verses VALUES ('B001C043V021', '1', 43, 21, 'И случилось, что, когда пришли мы на ночлег и открыли мешки наши,  — вот серебро каждого в отверстии мешка его, серебро наше по весу его, и мы возвращаем его своими руками;', 'И случилось, что, когда пришли мы на ночлег и открыли мешки наши, — вот серебро каждого в отверстии мешка его, серебро наше по весу его, и мы возвращаем его своими руками;');
INSERT INTO fix_verses VALUES ('B001C046V006', '1', 46, 6, 'И взяли они скот свой и имущество свое, которое приобрели в земле Ханаанской, и пришли в Египет,  — Иаков и весь род его с ним.', 'И взяли они скот свой и имущество свое, которое приобрели в земле Ханаанской, и пришли в Египет, — Иаков и весь род его с ним.');
INSERT INTO fix_verses VALUES ('B001C049V004', '1', 49, 4, 'Но ты бушевал, как вода,  — не будешь преимуществовать, ибо ты взошел на ложе отца твоего, ты осквернил постель мою, взошел.', 'Но ты бушевал, как вода, — не будешь преимуществовать, ибо ты взошел на ложе отца твоего, ты осквернил постель мою, взошел.');
INSERT INTO fix_verses VALUES ('B001C049V019', '1', 49, 19, 'Гад,  — толпа будет теснить его, но он оттеснит ее по пятам.', 'Гад, — толпа будет теснить его, но он оттеснит ее по пятам.');
INSERT INTO fix_verses VALUES ('B002C005V023', '2', 5, 23, 'Ибо с того времени, как я пришел к фараону и стал говорить именем Твоим, он начал хуже поступать с народом сим; избавить же,  — Ты не избавил народа Твоего.', 'Ибо с того времени, как я пришел к фараону и стал говорить именем Твоим, он начал хуже поступать с народом сим; избавить же, — Ты не избавил народа Твоего.');
INSERT INTO fix_verses VALUES ('B002C007V019', '2', 7, 19, 'И сказал Господь Моисею: скажи Аарону: возьми жезл твой, и простри руку твою на воды Египтян: на реки их, на потоки их, на озера их и на всякое вместилище вод их,  — и превратятся в кровь, и будет кровь по всей земле Египетской и в деревянных и в каменных сосудах.', 'И сказал Господь Моисею: скажи Аарону: возьми жезл твой, и простри руку твою на воды Египтян: на реки их, на потоки их, на озера их и на всякое вместилище вод их, — и превратятся в кровь, и будет кровь по всей земле Египетской и в деревянных и в каменных сосудах.');
INSERT INTO fix_verses VALUES ('B002C008V016', '2', 8, 16, 'И сказал Господь Моисею: скажи Аарону: простри жезл твой и ударь в персть земную, и сделается [персмь] мошками по всей земле Египетской.', 'И сказал Господь Моисею: скажи Аарону: простри жезл твой и ударь в персть земную, и сделается [персть] мошками по всей земле Египетской.');
INSERT INTO fix_verses VALUES ('B002C009V017', '2', 9, 17, 'Ты еще противостоишь народу Моему, чтобы не отпускать его,  —', 'Ты еще противостоишь народу Моему, чтобы не отпускать его, —');
INSERT INTO fix_verses VALUES ('B002C013V011', '2', 13, 11, 'И когда введет тебя Господь в землю Ханаанскую, как Он клялся тебе и отцам твоим, и даст ее тебе,  —', 'И когда введет тебя Господь в землю Ханаанскую, как Он клялся тебе и отцам твоим, и даст ее тебе, —');
INSERT INTO fix_verses VALUES ('B002C013V012', '2', 13, 12, 'Отделяй Господу все, разверзающее ложесна; и все первородное из скота, какой у тебя будет, мужеского пола,  — Господу,', 'Отделяй Господу все, разверзающее ложесна; и все первородное из скота, какой у тебя будет, мужеского пола, — Господу,');
INSERT INTO fix_verses VALUES ('B002C013V015', '2', 13, 15, 'Ибо когда фараон упорствовал отпустить нас, Господь умертвил всех первенцев в земле Египетской, от первенца человеческого до первенца из скота,  — посему я приношу в жертву Господу все, разверзающее ложесна, мужеского пола, а всякого первенца [из] сынов моих выкупаю;', 'Ибо когда фараон упорствовал отпустить нас, Господь умертвил всех первенцев в земле Египетской, от первенца человеческого до первенца из скота, — посему я приношу в жертву Господу все, разверзающее ложесна, мужеского пола, а всякого первенца [из] сынов моих выкупаю;');
INSERT INTO fix_verses VALUES ('B002C014V027', '2', 14, 27, 'И простер Моисей руку свою на море, и к утру вода возвратилась в свое место; а Египтяне бежали на встречу [воде]. Так потопил Господь Египтян среди моря.', 'И простер Моисей руку свою на море, и к утру вода возвратилась в свое место; а Египтяне бежали навстречу [воде]. Так потопил Господь Египтян среди моря.');
INSERT INTO fix_verses VALUES ('B002C015V013', '2', 15, 13, 'Ты ведешь милостью Твоею народ сей, который Ты избавил,  — сопровождаешь силою Твоею в жилище святыни Твоей.', 'Ты ведешь милостью Твоею народ сей, который Ты избавил, — сопровождаешь силою Твоею в жилище святыни Твоей.');
INSERT INTO fix_verses VALUES ('B002C016V020', '2', 16, 20, 'Но не послушали они Моисея, и оставили от сего некоторые до утра,  — и завелись черви, и оно воссмердело. И разгневался на них Моисей.', 'Но не послушали они Моисея, и оставили от сего некоторые до утра, — и завелись черви, и оно воссмердело. И разгневался на них Моисей.');
INSERT INTO fix_verses VALUES ('B002C021V005', '2', 21, 5, 'Но если раб скажет: люблю господина моего, жену мою и детей моих, не пойду на волю,  —', 'Но если раб скажет: люблю господина моего, жену мою и детей моих, не пойду на волю, —');
INSERT INTO fix_verses VALUES ('B002C021V031', '2', 21, 31, 'Сына ли забодает, дочь ли забодает,  — по сему же закону поступать с ним.', 'Сына ли забодает, дочь ли забодает, — по сему же закону поступать с ним.');
INSERT INTO fix_verses VALUES ('B002C022V010', '2', 22, 10, 'Если кто отдаст ближнему своему осла, или вола, или овцу, или какой другой скот на сбережение, а он умрет, или будет поврежден, или уведен, так что никто сего не увидит,  —', 'Если кто отдаст ближнему своему осла, или вола, или овцу, или какой другой скот на сбережение, а он умрет, или будет поврежден, или уведен, так что никто сего не увидит, —');
INSERT INTO fix_verses VALUES ('B002C022V030', '2', 22, 30, 'То же делай с волом твоим и с овцою твоею. семь дней пусть они будут при матери своей, а в восьмой день отдавай их Мне.', 'То же делай с волом твоим и с овцою твоею: семь дней пусть они будут при матери своей, а в восьмой день отдавай их Мне.');
INSERT INTO fix_verses VALUES ('B002C026V012', '2', 26, 12, 'А излишек, остающийся от покрывал скиний,  — половина излишнего покрывала пусть будет свешена на задней стороне скинии;', 'А излишек, остающийся от покрывал скиний, — половина излишнего покрывала пусть будет свешена на задней стороне скинии;');
INSERT INTO fix_verses VALUES ('B002C028V017', '2', 28, 17, 'И вставь в него оправленные камни в четыре ряда; рядом: рубин, топаз, изумруд,  — это один ряд;', 'И вставь в него оправленные камни в четыре ряда; рядом: рубин, топаз, изумруд, — это один ряд;');
INSERT INTO fix_verses VALUES ('B002C029V021', '2', 29, 21, 'И возьми крови, которая на жертвеннике, и елея помазания, и покропи на Аарона и на одежды его, и на сынов его, и на одежды сынов его с ним,  — и будут освящены, он и одежды его, и сыны его и одежды их с ним.', 'И возьми крови, которая на жертвеннике, и елея помазания, и покропи на Аарона и на одежды его, и на сынов его, и на одежды сынов его с ним, — и будут освящены, он и одежды его, и сыны его и одежды их с ним.');
INSERT INTO fix_verses VALUES ('B002C029V026', '2', 29, 26, 'И возьми грудь от овна вручения, который для Аарона, и принеси ее, потрясая пред лицем Господним,  — и это будет твоя доля;', 'И возьми грудь от овна вручения, который для Аарона, и принеси ее, потрясая пред лицем Господним, — и это будет твоя доля;');
INSERT INTO fix_verses VALUES ('B002C029V027', '2', 29, 27, 'И освяти грудь приношения, которая потрясаема была и плечо возношения, которое было возносимо, от овна вручения, который для Аарона и для сынов его,  —', 'И освяти грудь приношения, которая потрясаема была и плечо возношения, которое было возносимо, от овна вручения, который для Аарона и для сынов его, —');
INSERT INTO fix_verses VALUES ('B002C030V008', '2', 30, 8, 'И когда Аарон зажигает лампады вечером, он будет курить им: [это]  — всегдашнее курение пред Господом в роды ваши.', 'И когда Аарон зажигает лампады вечером, он будет курить им: [это] — всегдашнее курение пред Господом в роды ваши.');
INSERT INTO fix_verses VALUES ('B002C032V024', '2', 32, 24, 'И я сказал им: у кого есть золото, снимите с себя. и отдали мне; я бросил его в огонь, и вышел этот телец.', 'И я сказал им: у кого есть золото, снимите с себя. И отдали мне; я бросил его в огонь, и вышел этот телец.');
INSERT INTO fix_verses VALUES ('B002C032V026', '2', 32, 26, 'И стал Моисей в воротах стана и сказал: кто Господень,  — ко мне! И собрались к нему все сыны Левиины.', 'И стал Моисей в воротах стана и сказал: кто Господень, — ко мне! И собрались к нему все сыны Левиины.');
INSERT INTO fix_verses VALUES ('B002C038V014', '2', 38, 14, 'Для одной стороны [ворот двора]  — завесы в пятнадцать локтей, столбов для них три и подножий к ним три;', 'Для одной стороны [ворот двора] — завесы в пятнадцать локтей, столбов для них три и подножий к ним три;');
INSERT INTO fix_verses VALUES ('B002C039V010', '2', 39, 10, 'И вставили в него в четыре ряда камни. Рядом: рубин, топаз, изумруд,  — это первый ряд;', 'И вставили в него в четыре ряда камни. Рядом: рубин, топаз, изумруд, — это первый ряд;');
INSERT INTO fix_verses VALUES ('B003C004V003', '3', 4, 3, 'Если священник помазанный согрешит и сделает виновным народ,  — то за грех свой, которым согрешил, пусть представит из крупного скота тельца, без порока, Господу в жертву о грехе,', 'Если священник помазанный согрешит и сделает виновным народ, — то за грех свой, которым согрешил, пусть представит из крупного скота тельца, без порока, Господу в жертву о грехе,');
INSERT INTO fix_verses VALUES ('B003C006V003', '3', 6, 3, 'Или найдет потерянное и запрется в том, и поклянется ложно в чем-нибудь, что люди делают и тем грешат,  —', 'Или найдет потерянное и запрется в том, и поклянется ложно в чем-нибудь, что люди делают и тем грешат, —');
INSERT INTO fix_verses VALUES ('B003C007V036', '3', 7, 36, 'Который повелел Господь давать им со дня помазания их от сынов Израилевых. [Это] вечное постановление в роды их.  —', 'Который повелел Господь давать им со дня помазания их от сынов Израилевых. [Это] вечное постановление в роды их. —');
INSERT INTO fix_verses VALUES ('B003C011V030', '3', 11, 30, 'Анака, хамелеон, летаа, хомет и тиншемет,  —', 'Анака, хамелеон, летаа, хомет и тиншемет, —');
INSERT INTO fix_verses VALUES ('B003C011V038', '3', 11, 38, 'Если же тогда, как вода налита на семя, упадет на него что — нибудь от трупа их, то оно нечисто для вас.', 'Если же тогда, как вода налита на семя, упадет на него что-нибудь от трупа их, то оно нечисто для вас.');
INSERT INTO fix_verses VALUES ('B003C013V049', '3', 13, 49, 'И пятно будет зеленоватое или красноватое на одежде, или на коже, или на основе, или на утоке, или на какой-нибудь кожаной вещи,  — то это язва проказы: должно показать ее священнику;', 'И пятно будет зеленоватое или красноватое на одежде, или на коже, или на основе, или на утоке, или на какой-нибудь кожаной вещи, — то это язва проказы: должно показать ее священнику;');
INSERT INTO fix_verses VALUES ('B003C014V056', '3', 14, 55, 'И об опухоли, и о лишаях, и о пятнах,  —', 'И об опухоли, и о лишаях, и о пятнах, —');
INSERT INTO fix_verses VALUES ('B003C016V015', '3', 16, 15, 'И заколет козла в жертву за грех за народ, и внесет кровь его за завесу, и сделает с кровью его то же, что делал с кровью тельца и покропит ею на крышку и пред крышкою,  —', 'И заколет козла в жертву за грех за народ, и внесет кровь его за завесу, и сделает с кровью его то же, что делал с кровью тельца и покропит ею на крышку и пред крышкою, —');
INSERT INTO fix_verses VALUES ('B003C020V010', '3', 20, 10, 'Если кто будет прелюбодействовать с женой замужнею, если кто будет прелюбодействовать с женою ближнего своего,  — да будут преданы смерти и прелюбодей и прелюбодейка.', 'Если кто будет прелюбодействовать с женой замужнею, если кто будет прелюбодействовать с женою ближнего своего, — да будут преданы смерти и прелюбодей и прелюбодейка.');
INSERT INTO fix_verses VALUES ('B003C020V022', '3', 20, 22, 'Соблюдайте все уставы Мои и все законы Мои и исполняйте их,  — и не свергнет вас с себя земля, в которую Я веду вас жить.', 'Соблюдайте все уставы Мои и все законы Мои и исполняйте их, — и не свергнет вас с себя земля, в которую Я веду вас жить.');
INSERT INTO fix_verses VALUES ('B003C022V004', '3', 22, 4, 'Кто из семени Ааронова прокажен, или имеет истечение, тот не должен есть святынь, пока не очистится; и кто прикоснется к чему — нибудь нечистому от мертвого, или у кого случится излияние семени,', 'Кто из семени Ааронова прокажен, или имеет истечение, тот не должен есть святынь, пока не очистится; и кто прикоснется к чему-нибудь нечистому от мертвого, или у кого случится излияние семени,');
INSERT INTO fix_verses VALUES ('B003C022V005', '3', 22, 5, 'Или кто прикоснется к какому-нибудь гаду, от которого он сделается нечист, или к человеку, от которого он сделается нечист какою бы то ни было нечистотою,  —', 'Или кто прикоснется к какому-нибудь гаду, от которого он сделается нечист, или к человеку, от которого он сделается нечист какою бы то ни было нечистотою, —');
INSERT INTO fix_verses VALUES ('B003C025V049', '3', 25, 49, 'Или дядя его, или сын дяди его должен выкупить его, или кто — нибудь из родства его, из племени его, должен выкупить его; или если будет иметь достаток, сам выкупится.', 'Или дядя его, или сын дяди его должен выкупить его, или кто-нибудь из родства его, из племени его, должен выкупить его; или если будет иметь достаток, сам выкупится.');
INSERT INTO fix_verses VALUES ('B003C026V015', '3', 26, 15, 'И если презрите Мои постановления, и если душа ваша возгнушается Моими законами, так что вы не будете исполнять всех заповедей Моих, нарушив завет Мой,  —', 'И если презрите Мои постановления, и если душа ваша возгнушается Моими законами, так что вы не будете исполнять всех заповедей Моих, нарушив завет Мой, —');
INSERT INTO fix_verses VALUES ('B003C026V044', '3', 26, 44, 'И тогда как они будут в земле врагов их,  — Я не презрю их и не возгнушаюсь ими до того, чтоб истребить их, чтоб разрушить завет Мой с ними, ибо Я Господь, Бог их;', 'И тогда как они будут в земле врагов их, — Я не презрю их и не возгнушаюсь ими до того, чтоб истребить их, чтоб разрушить завет Мой с ними, ибо Я Господь, Бог их;');
INSERT INTO fix_verses VALUES ('B003C027V017', '3', 27, 17, 'Если от юбилейного года посвящает кто поле свое,  — должно состояться по оценке твоей;', 'Если от юбилейного года посвящает кто поле свое, — должно состояться по оценке твоей;');
INSERT INTO fix_verses VALUES ('B003C027V026', '3', 27, 26, 'Только первенцев из скота, которые по первенству принадлежат Господу, не должен никто посвящать: вол ли то, или мелкий скот,  — Господни они.', 'Только первенцев из скота, которые по первенству принадлежат Господу, не должен никто посвящать: вол ли то, или мелкий скот, — Господни они.');
INSERT INTO fix_verses VALUES ('B003C027V028', '3', 27, 28, 'Только все заклятое, что под заклятием отдает человек Господу из своей собственности,  — человека ли, скотину ли, поле ли своего владения,  — не продается и не выкупается: все заклятое есть великая святыня Господня;', 'Только все заклятое, что под заклятием отдает человек Господу из своей собственности, — человека ли, скотину ли, поле ли своего владения, — не продается и не выкупается: все заклятое есть великая святыня Господня;');
INSERT INTO fix_verses VALUES ('B004C003V041', '4', 3, 41, 'И возьми левитов для Меня,  — Я Господь,  — вместо всех первенцев из сынов Израиля, а скот левитов вместо всего первородного скота сынов Израилевых.', 'И возьми левитов для Меня, — Я Господь, — вместо всех первенцев из сынов Израиля, а скот левитов вместо всего первородного скота сынов Израилевых.');
INSERT INTO fix_verses VALUES ('B004C004V016', '4', 4, 16, 'Елеазару, сыну Аарона священника, поручается елей для светильника и благовонное курение, и всегдашнее хлебное приношение и елей помазания,  — поручается вся скиния и все, что в ней, святилище и принадлежности его.', 'Елеазару, сыну Аарона священника, поручается елей для светильника и благовонное курение, и всегдашнее хлебное приношение и елей помазания, — поручается вся скиния и все, что в ней, святилище и принадлежности его.');
INSERT INTO fix_verses VALUES ('B004C005V014', '4', 5, 14, 'И найдет на него дух ревности, и будет ревновать жену свою, когда она осквернена, или найдет на него дух ревности, и он будет ревновать жену свою, когда она не осквернена,  —', 'И найдет на него дух ревности, и будет ревновать жену свою, когда она осквернена, или найдет на него дух ревности, и он будет ревновать жену свою, когда она не осквернена, —');
INSERT INTO fix_verses VALUES ('B004C005V018', '4', 5, 18, 'И поставит священник жену пред лице Господне, и обнажит голову жены, и даст ей в руки приношение воспоминания,  — это приношение ревнования, в руке же у священника будет горькая вода, наводящая проклятие.', 'И поставит священник жену пред лице Господне, и обнажит голову жены, и даст ей в руки приношение воспоминания, — это приношение ревнования, в руке же у священника будет горькая вода, наводящая проклятие.');
INSERT INTO fix_verses VALUES ('B004C005V020', '4', 5, 20, 'Но если ты изменила мужу твоему и осквернилась, и если кто переспал с тобою кроме мужа твоего,  —', 'Но если ты изменила мужу твоему и осквернилась, и если кто переспал с тобою кроме мужа твоего, —');
INSERT INTO fix_verses VALUES ('B004C005V030', '4', 5, 30, 'Или когда на мужа найдет дух ревности, и он будет ревновать жену свою, тогда пусть он поставит жену пред лицем Господа, и сделает с нею священник все по сему закону,  —', 'Или когда на мужа найдет дух ревности, и он будет ревновать жену свою, тогда пусть он поставит жену пред лицем Господа, и сделает с нею священник все по сему закону, —');
INSERT INTO fix_verses VALUES ('B004C007V002', '4', 7, 2, 'Тогда пришли начальников Израилевых, главы семейств их, начальники колен, заведывавшие исчислением,', 'Тогда пришли начальники Израилевы, главы семейств их, начальники колен, заведывавшие исчислением,');
INSERT INTO fix_verses VALUES ('B004C007V088', '4', 7, 88, 'И в жертву мирную всего из крупного скота двадцать четыре тельца, шестьдесят овнов, шестьдесят козлов, шестьдесят однолетних агнцев. вот приношения при освящении жертвенника после помазания его.', 'И в жертву мирную всего из крупного скота двадцать четыре тельца, шестьдесят овнов, шестьдесят козлов, шестьдесят однолетних агнцев; вот приношения при освящении жертвенника после помазания его.');
INSERT INTO fix_verses VALUES ('B004C009V013', '4', 9, 13, 'А кто чист и не находится в дороге и не совершит Пасхи,  — истребится душа та из народа своего, ибо он не принес приношения Господу в свое время: понесет на себе грех человек тот;', 'А кто чист и не находится в дороге и не совершит Пасхи, — истребится душа та из народа своего, ибо он не принес приношения Господу в свое время: понесет на себе грех человек тот;');
INSERT INTO fix_verses VALUES ('B004C010V009', '4', 10, 9, 'И когда пойдете на войну в земле вашей против врага, наступающего на вас, трубите тревогу трубами,  — и будете воспомянуты пред Господом, Богом вашим, и спасены будете от врагов ваших;', 'И когда пойдете на войну в земле вашей против врага, наступающего на вас, трубите тревогу трубами, — и будете воспомянуты пред Господом, Богом вашим, и спасены будете от врагов ваших;');
INSERT INTO fix_verses VALUES ('B004C010V010', '4', 10, 10, 'И в день веселия вашего, и в праздники ваши, и в новомесячия ваши трубите трубами при всесожжениях ваших и при мирных жертвах ваших,  — и это будет напоминанием о вас пред Богом вашим. Я Господь, Бог ваш.', 'И в день веселия вашего, и в праздники ваши, и в новомесячия ваши трубите трубами при всесожжениях ваших и при мирных жертвах ваших, — и это будет напоминанием о вас пред Богом вашим. Я Господь, Бог ваш.');
INSERT INTO fix_verses VALUES ('B004C011V018', '4', 11, 18, 'Народу же скажи: очиститесь к завтрашнему дню, и будете есть мясо; так как вы плакали вслух Господа и говорили: кто накормит нас мясом? хорошо нам было в Египте,  — то и даст вам Господь мясо, и будете есть.', 'Народу же скажи: очиститесь к завтрашнему дню, и будете есть мясо; так как вы плакали вслух Господа и говорили: кто накормит нас мясом? хорошо нам было в Египте, — то и даст вам Господь мясо, и будете есть.');
INSERT INTO fix_verses VALUES ('B004C012V001', '4', 12, 1, 'И упрекали Мариам и Аарон Моисея за жену Ефиоплянку, которую он взял,  — ибо он взял [за себя] Ефиоплянку,  —', 'И упрекали Мариам и Аарон Моисея за жену Ефиоплянку, которую он взял, — ибо он взял [за себя] Ефиоплянку, —');
INSERT INTO fix_verses VALUES ('B004C012V007', '4', 12, 7, 'Но не так с рабом Моим Моисеем,  — он верен во всем дому Моем:', 'Но не так с рабом Моим Моисеем, — он верен во всем дому Моем:');
INSERT INTO fix_verses VALUES ('B004C015V003', '4', 15, 3, 'И будете приносить жертву Господу, всесожжение, или жертву заколаемую, от волов и овец, во исполнение обета, или по усердию, или в праздники ваши, дабы сделать приятное благоухание Господу,  —', 'И будете приносить жертву Господу, всесожжение, или жертву заколаемую, от волов и овец, во исполнение обета, или по усердию, или в праздники ваши, дабы сделать приятное благоухание Господу, —');
INSERT INTO fix_verses VALUES ('B004C015V023', '4', 15, 23, 'Всего, что заповедал вам Господь чрез Моисея, от того дня, в который Господь заповедал вам, и впредь в роды ваши,  —', 'Всего, что заповедал вам Господь чрез Моисея, от того дня, в который Господь заповедал вам, и впредь в роды ваши, —');
INSERT INTO fix_verses VALUES ('B004C018V010', '4', 18, 10, 'На святейшем месте ешьте это; все мужеского пола могут есть. это святынею да будет для тебя.', 'На святейшем месте ешьте это; все мужеского пола могут есть; это святынею да будет для тебя.');
INSERT INTO fix_verses VALUES ('B004C018V026', '4', 18, 26, 'Объяви левитам и скажи им: когда вы будете брать от сынов Израилевых десятину, которую Я дал вам от них в удел, то возносите из нее возношение Господу, десятину из десятины,  —', 'Объяви левитам и скажи им: когда вы будете брать от сынов Израилевых десятину, которую Я дал вам от них в удел, то возносите из нее возношение Господу, десятину из десятины, —');
INSERT INTO fix_verses VALUES ('B004C020V014', '4', 20, 14, 'И послал Моисей из Кадеса послов к Царю Едомскому [сказать]: так говорит брат твой Израиль: ты знаешь все трудности, которые постигли нас;', 'И послал Моисей из Кадеса послов к царю Едомскому [сказать]: так говорит брат твой Израиль: ты знаешь все трудности, которые постигли нас;');
INSERT INTO fix_verses VALUES ('B004C022V022', '4', 22, 22, 'И воспылал гнев Божий за то, что он пошел, и стал Ангел Господень на дороге, чтобы воспрепятствовать ему. Он ехал на ослице своей и с ними двое слуг его.', 'И воспылал гнев Божий за то, что он пошел, и стал Ангел Господень на дороге, чтобы воспрепятствовать ему. Он ехал на ослице своей и с ним двое слуг его.');
INSERT INTO fix_verses VALUES ('B004C026V065', '4', 26, 65, 'Ибо Господь сказал им, что умрут они в пустыне,  — и не осталось из них никого, кроме Халева, сына Иефонниина, и Иисуса, сына Навина.', 'Ибо Господь сказал им, что умрут они в пустыне, — и не осталось из них никого, кроме Халева, сына Иефонниина, и Иисуса, сына Навина.');
INSERT INTO fix_verses VALUES ('B004C028V013', '4', 28, 13, 'И по десятой части [ефы] пшеничной муки, смешанной с елеем, в приношение хлебное на каждого агнца; [это]  — всесожжение, приятное благоухание, жертва Господу;', 'И по десятой части [ефы] пшеничной муки, смешанной с елеем, в приношение хлебное на каждого агнца; [это] — всесожжение, приятное благоухание, жертва Господу;');
INSERT INTO fix_verses VALUES ('B004C032V033', '4', 32, 33, 'И отдал Моисей им, сынам Гадовым и сынам Рувимовым, и половине колена Манассии, сына Иосифова, царство Сигона, царя Аморрейского, и царство Ога, царя Васанского, землю с городами ее и окрестностями,  — города земли во все стороны.', 'И отдал Моисей им, сынам Гадовым и сынам Рувимовым, и половине колена Манассии, сына Иосифова, царство Сигона, царя Аморрейского, и царство Ога, царя Васанского, землю с городами ее и окрестностями, — города земли во все стороны.');
INSERT INTO fix_verses VALUES ('B004C033V019', '4', 33, 19, 'И отправились из Рифмы и расположились станом в Римнон — Фареце.', 'И отправились из Рифмы и расположились станом в Римнон-Фареце.');
INSERT INTO fix_verses VALUES ('B004C033V032', '4', 33, 32, 'И отправились из Бене-Яакана и расположились станом в Хор — Агидгаде.', 'И отправились из Бене-Яакана и расположились станом в Хор-Агидгаде.');
INSERT INTO fix_verses VALUES ('B004C033V035', '4', 33, 35, 'И отправились из Аврона и расположились станом в Ецион — Гавере.', 'И отправились из Аврона и расположились станом в Ецион-Гавере.');
INSERT INTO fix_verses VALUES ('B004C033V036', '4', 33, 36, 'И отправились из Ецион-Гавера и расположились станом в пустыне Син. она же Кадес.', 'И отправились из Ецион-Гавера и расположились станом в пустыне Син, она же Кадес.');
INSERT INTO fix_verses VALUES ('B004C033V046', '4', 33, 46, 'И отправились из Дивон-Гада и расположились станом в Алмон — Дивлафаиме.', 'И отправились из Дивон-Гада и расположились станом в Алмон-Дивлафаиме.');
INSERT INTO fix_verses VALUES ('B004C033V049', '4', 33, 49, 'Они расположились станом у Иордана от Беф-Иешимофа до Аве — Ситтима на равнинах Моавитских.', 'Они расположились станом у Иордана от Беф-Иешимофа до Аве-Ситтима на равнинах Моавитских.');
INSERT INTO fix_verses VALUES ('B004C034V009', '4', 34, 9, 'Оттуда пойдет граница к Цифрону, и выступы ее будут к Гацар — Енану: это будет у вас граница северная;', 'Оттуда пойдет граница к Цифрону, и выступы ее будут к Гацар-Енану: это будет у вас граница северная;');
INSERT INTO fix_verses VALUES ('B005C003V008', '5', 3, 8, 'И взяли мы в то время из руки двух царей Аморрейских землю сию, которая по эту сторону Иордана, от потока Арнона до горы Ермона,  —', 'И взяли мы в то время из руки двух царей Аморрейских землю сию, которая по эту сторону Иордана, от потока Арнона до горы Ермона, —');
INSERT INTO fix_verses VALUES ('B005C003V009', '5', 3, 9, 'Сидоняне Ермон называют Сирионом, а Аморреи называют его Сениром,  —', 'Сидоняне Ермон называют Сирионом, а Аморреи называют его Сениром, —');
INSERT INTO fix_verses VALUES ('B005C004V003', '5', 4, 3, 'Глаза ваши видели [все], что сделал Господь с Ваал — Фегором: всякого человека, последовавшего Ваал-Фегору, истребил Господь, Бог твой, из среды тебя;', 'Глаза ваши видели [все], что сделал Господь с Ваал-Фегором: всякого человека, последовавшего Ваал-Фегору, истребил Господь, Бог твой, из среды тебя;');
INSERT INTO fix_verses VALUES ('B005C004V009', '5', 4, 9, 'Только берегись и тщательно храни душу твою, чтобы тебе не забыть тех дел, которые видели глаза твои, и чтобы они не выходили из сердца твоего во все дни жизни твоей; и поведай о них сынам твоим и сынам сынов твоих,  —', 'Только берегись и тщательно храни душу твою, чтобы тебе не забыть тех дел, которые видели глаза твои, и чтобы они не выходили из сердца твоего во все дни жизни твоей; и поведай о них сынам твоим и сынам сынов твоих, —');
INSERT INTO fix_verses VALUES ('B005C007V007', '5', 7, 7, 'Не потому, чтобы вы были многочисленнее всех народов, принял вас Господь и избрал вас,  — ибо вы малочисленнее всех народов,  —', 'Не потому, чтобы вы были многочисленнее всех народов, принял вас Господь и избрал вас, — ибо вы малочисленнее всех народов, —');
INSERT INTO fix_verses VALUES ('B005C008V013', '5', 8, 13, 'И когда будет у тебя много крупного и мелкого скота, и будет много серебра и золота, и всего у тебя будет много,  —', 'И когда будет у тебя много крупного и мелкого скота, и будет много серебра и золота, и всего у тебя будет много, —');
INSERT INTO fix_verses VALUES ('B005C009V021', '5', 9, 21, 'Грех же ваш, который вы сделали,  — тельца я взял, сожег его в огне, разбил его и всего истер до того, что он стал мелок, как прах, и я бросил прах сей в поток, текущий с горы.', 'Грех же ваш, который вы сделали, — тельца я взял, сожег его в огне, разбил его и всего истер до того, что он стал мелок, как прах, и я бросил прах сей в поток, текущий с горы.');
INSERT INTO fix_verses VALUES ('B005C009V023', '5', 9, 23, 'И когда посылал вас Господь из Кадес-Варни, говоря: пойдите, овладейте землею, которую Я даю вам,  — то вы воспротивились повелению Господа Бога вашего, и не поверили Ему, и не послушали гласа Его.', 'И когда посылал вас Господь из Кадес-Варни, говоря: пойдите, овладейте землею, которую Я даю вам, — то вы воспротивились повелению Господа Бога вашего, и не поверили Ему, и не послушали гласа Его.');
INSERT INTO fix_verses VALUES ('B005C011V002', '5', 11, 2, 'И вспомните ныне,  — ибо [я говорю] не с сынами вашими, которые не знают и не видели наказания Господа Бога вашего,  — Его величие Его крепкую руку и высокую мышцу его,', 'И вспомните ныне, — ибо [я говорю] не с сынами вашими, которые не знают и не видели наказания Господа Бога вашего, — Его величие Его крепкую руку и высокую мышцу его,');
INSERT INTO fix_verses VALUES ('B005C011V004', '5', 11, 4, 'И что Он сделал с войском Египетским, с конями его и колесницами его, которых Он потопил в водах Чермного моря, когда они гнались за вами,  — и погубил их Господь даже до сего дня;', 'И что Он сделал с войском Египетским, с конями его и колесницами его, которых Он потопил в водах Чермного моря, когда они гнались за вами, — и погубил их Господь даже до сего дня;');
INSERT INTO fix_verses VALUES ('B005C011V011', '5', 11, 11, 'Но земля, в которую вы переходите, чтоб овладеть ею, есть земля с горами и долинами, и от дождя небесного напояется водою,  —', 'Но земля, в которую вы переходите, чтоб овладеть ею, есть земля с горами и долинами, и от дождя небесного напояется водою, —');
INSERT INTO fix_verses VALUES ('B005C012V018', '5', 12, 18, 'Но ешь сие пред Господом, Богом твоим, на том месте, которое изберет Господь, Бог твой,  — ты и сын твой, и дочь твоя, и раб твой, и раба твоя, и левит, [и пришелец], который в жилищах твоих, и веселись пред Господом, Богом твоим, о всем, что делалось руками твоими.', 'Но ешь сие пред Господом, Богом твоим, на том месте, которое изберет Господь, Бог твой, — ты и сын твой, и дочь твоя, и раб твой, и раба твоя, и левит, [и пришелец], который в жилищах твоих, и веселись пред Господом, Богом твоим, о всем, что делалось руками твоими.');
INSERT INTO fix_verses VALUES ('B005C012V020', '5', 12, 20, 'Когда распространит Господь, Бог твой, пределы твои, как Он говорил тебе, и ты скажешь: «поем я мяса», потому что душа твоя пожелает есть мяса,  — тогда, по желанию души твоей, ешь мясо.', 'Когда распространит Господь, Бог твой, пределы твои, как Он говорил тебе, и ты скажешь: «поем я мяса», потому что душа твоя пожелает есть мяса, — тогда, по желанию души твоей, ешь мясо.');
INSERT INTO fix_verses VALUES ('B005C013V002', '5', 13, 2, 'И сбудется то знамение или чудо, о котором он говорил тебе, и скажет притом: «пойдем вслед богов иных, которых ты не знаешь, и будем служить им»,  —', 'И сбудется то знамение или чудо, о котором он говорил тебе, и скажет притом: «пойдем вслед богов иных, которых ты не знаешь, и будем служить им», —');
INSERT INTO fix_verses VALUES ('B005C013V007', '5', 13, 7, 'Богам тех народов, которые вокруг тебя, близких к тебе или отдаленных от тебя, от одного края земли до другого,  —', 'Богам тех народов, которые вокруг тебя, близких к тебе или отдаленных от тебя, от одного края земли до другого, —');
INSERT INTO fix_verses VALUES ('B005C013V013', '5', 13, 13, 'Что появились в нем нечестивые люди из среды тебя и соблазнили жителей города их, говоря: «пойдем и будем служить богам иным, которых вы не знали»,  —', 'Что появились в нем нечестивые люди из среды тебя и соблазнили жителей города их, говоря: «пойдем и будем служить богам иным, которых вы не знали», —');
INSERT INTO fix_verses VALUES ('B005C017V012', '5', 17, 12, 'А кто поступит так дерзко, что не послушает священника, стоящего там на служении пред Господом, Богом твоим, или судьи, тот должен умереть,  — и [так] истреби зло от Израиля;', 'А кто поступит так дерзко, что не послушает священника, стоящего там на служении пред Господом, Богом твоим, или судьи, тот должен умереть, — и [так] истреби зло от Израиля;');
INSERT INTO fix_verses VALUES ('B005C018V007', '5', 18, 7, 'И будет служить во имя Господа Бога своего, как и все братья его левиты, предстоящие там пред Господом,  —', 'И будет служить во имя Господа Бога своего, как и все братья его левиты, предстоящие там пред Господом, —');
INSERT INTO fix_verses VALUES ('B005C018V015', '5', 18, 15, 'Пророка из среды тебя, из братьев твоих, как меня, воздвигнет тебе Господь Бог твой,  — Его слушайте,  —', 'Пророка из среды тебя, из братьев твоих, как меня, воздвигнет тебе Господь Бог твой, — Его слушайте, —');
INSERT INTO fix_verses VALUES ('B005C018V022', '5', 18, 22, 'Если пророк скажет именем Господа, но слово то не сбудется и не исполнится, то не Господь говорил сие слово, но говорил сие пророк по дерзости своей,  — не бойся его.', 'Если пророк скажет именем Господа, но слово то не сбудется и не исполнится, то не Господь говорил сие слово, но говорил сие пророк по дерзости своей, — не бойся его.');
INSERT INTO fix_verses VALUES ('B005C019V005', '5', 19, 5, 'Кто пойдет с ближним своим в лес рубить дрова, и размахнется рука его с топором, чтобы срубить дерево, и соскочит железо с топорища и попадет в ближнего, и он умрет,  — такой пусть убежит в один из городов тех, чтоб остаться живым,', 'Кто пойдет с ближним своим в лес рубить дрова, и размахнется рука его с топором, чтобы срубить дерево, и соскочит железо с топорища и попадет в ближнего, и он умрет, — такой пусть убежит в один из городов тех, чтоб остаться живым,');
INSERT INTO fix_verses VALUES ('B005C019V009', '5', 19, 9, 'Если ты будешь стараться исполнять все сии заповеди, которые я заповедую тебе сегодня, любить Господа Бога твоего и ходить путями Его во все дни,  — тогда к сим трем городам прибавь еще три города,', 'Если ты будешь стараться исполнять все сии заповеди, которые я заповедую тебе сегодня, любить Господа Бога твоего и ходить путями Его во все дни, — тогда к сим трем городам прибавь еще три города,');
INSERT INTO fix_verses VALUES ('B005C019V015', '5', 19, 15, 'Недостаточно одного свидетеля против кого-либо в какой — нибудь вине и в каком-нибудь преступлении и в каком-нибудь грехе, которым он согрешит: при словах двух свидетелей, или при словах трех свидетелей состоится дело.', 'Недостаточно одного свидетеля против кого-либо в какой-нибудь вине и в каком-нибудь преступлении и в каком-нибудь грехе, которым он согрешит: при словах двух свидетелей, или при словах трех свидетелей состоится дело.');
INSERT INTO fix_verses VALUES ('B005C021V015', '5', 21, 15, 'Если у кого будут две жены — одна любимая, а другая нелюбимая, и как любимая, [так] и нелюбимая родят ему сыновей, и первенцем будет сын нелюбимой,  —', 'Если у кого будут две жены — одна любимая, а другая нелюбимая, и как любимая, [так] и нелюбимая родят ему сыновей, и первенцем будет сын нелюбимой, —');
INSERT INTO fix_verses VALUES ('B005C021V018', '5', 21, 18, 'Если у кого будет сын буйный и непокорный, неповинующийся голосу отца своего и голосу матери своей, и они наказывали его, но он не слушает их,  —', 'Если у кого будет сын буйный и непокорный, неповинующийся голосу отца своего и голосу матери своей, и они наказывали его, но он не слушает их, —');
INSERT INTO fix_verses VALUES ('B005C022V008', '5', 22, 8, 'Если будешь строить новый дом, то сделай перила около кровли твоей, чтобы не навести тебе крови на дом твой, когда кто — нибудь упадет с него.', 'Если будешь строить новый дом, то сделай перила около кровли твоей, чтобы не навести тебе крови на дом твой, когда кто-нибудь упадет с него.');
INSERT INTO fix_verses VALUES ('B005C024V003', '5', 24, 3, 'Но и сей последний муж возненавидит ее и напишет ей разводное письмо, и даст ей в руки, и отпустит ее из дома своего, или умрет сей последний муж ее, взявший ее себе в жену,  —', 'Но и сей последний муж возненавидит ее и напишет ей разводное письмо, и даст ей в руки, и отпустит ее из дома своего, или умрет сей последний муж ее, взявший ее себе в жену, —');
INSERT INTO fix_verses VALUES ('B005C024V013', '5', 24, 13, 'Возврати ему залог при захождении солнца, чтоб он лег спать в одежде своей и благословил тебя,  — и тебе поставится [сие] в праведность пред Господом Богом твоим.', 'Возврати ему залог при захождении солнца, чтоб он лег спать в одежде своей и благословил тебя, — и тебе поставится [сие] в праведность пред Господом Богом твоим.');
INSERT INTO fix_verses VALUES ('B005C025V005', '5', 25, 5, 'Если братья живут вместе и один из них умрет, не имея у себя сына, то жена умершего не должна выходить на сторону за человека чужого, но деверь ее должен войти к ней и взять ее себе в жену, и жить с нею,  —', 'Если братья живут вместе и один из них умрет, не имея у себя сына, то жена умершего не должна выходить на сторону за человека чужого, но деверь ее должен войти к ней и взять ее себе в жену, и жить с нею, —');
INSERT INTO fix_verses VALUES ('B005C028V020', '5', 28, 20, 'Пошлет Господь на тебя проклятие, смятение и несчастье во всяком деле рук твоих, какое ни станешь ты делать, доколе не будешь истреблен,  — и ты скоро погибнешь за злые дела твои, за то, что ты оставил Меня.', 'Пошлет Господь на тебя проклятие, смятение и несчастье во всяком деле рук твоих, какое ни станешь ты делать, доколе не будешь истреблен, — и ты скоро погибнешь за злые дела твои, за то, что ты оставил Меня.');
INSERT INTO fix_verses VALUES ('B005C030V002', '5', 30, 2, 'И обратишься к Господу Богу твоему и послушаешь гласа Его, как я заповедую тебе сегодня, ты и сыны твои от всего сердца твоего и от всей души твоей,  —', 'И обратишься к Господу Богу твоему и послушаешь гласа Его, как я заповедую тебе сегодня, ты и сыны твои от всего сердца твоего и от всей души твоей, —');
INSERT INTO fix_verses VALUES ('B005C030V016', '5', 30, 16, '[Я] которые заповедую тебе сегодня, любить Господа Бога твоего, ходить по путям Его и исполнять заповеди Его и постановления Его и законы Его, то будешь жить и размножишься, и благословит тебя Господь Бог твой на земле, в которую ты идешь, чтоб овладеть ею;', '[Я] заповедую тебе сегодня любить Господа Бога твоего, ходить по путям Его и исполнять заповеди Его и постановления Его и законы Его, то будешь жить и размножишься, и благословит тебя Господь Бог твой на земле, в которую ты идешь, чтоб овладеть ею;');
INSERT INTO fix_verses VALUES ('B005C032V040', '5', 32, 40, 'Я подъемлю к небесам руку Мою и говорю: живу Я во век!', 'Я подъемлю к небесам руку Мою и говорю: живу Я вовек!');
INSERT INTO fix_verses VALUES ('B006C003V015', '6', 3, 15, 'То, лишь только несущие ковчег вошли в Иордан, и ноги священников, несших ковчег, погрузились в воду Иордана — Иордан же выступает из всех берегов своих во все дни жатвы пшеницы,  —', 'То, лишь только несущие ковчег вошли в Иордан, и ноги священников, несших ковчег, погрузились в воду Иордана — Иордан же выступает из всех берегов своих во все дни жатвы пшеницы, —');
INSERT INTO fix_verses VALUES ('B006C004V003', '6', 4, 3, 'И дайте им повеление и скажите: возьмите себе отсюда, из средины Иордана, где стояли ноги священников неподвижно, двенадцать камней, и перенесите их с собою, и положите их наночлеге, где будете ночевать в эту ночь.', 'И дайте им повеление и скажите: возьмите себе отсюда, из средины Иордана, где стояли ноги священников неподвижно, двенадцать камней, и перенесите их с собою, и положите их на ночлеге, где будете ночевать в эту ночь.');
INSERT INTO fix_verses VALUES ('B006C004V005', '6', 4, 5, 'И сказал им Иисус: пойдите пред ковчегом Господа Бога вашегов средину Иордана и [возьмите оттуда] и положите на плечо свое каждый по одному камню, по числу колен сынов Израилевых,', 'И сказал им Иисус: пойдите пред ковчегом Господа Бога вашего в средину Иордана и [возьмите оттуда] и положите на плечо свое каждый по одному камню, по числу колен сынов Израилевых,');
INSERT INTO fix_verses VALUES ('B006C004V006', '6', 4, 6, 'Чтобы они были у вас знамением; когда спросят вас в последующее время сыны ваши и скажут: «к чему у васэти камни?»,', 'Чтобы они были у вас знамением; когда спросят вас в последующее время сыны ваши и скажут: «к чему у вас эти камни?»,');
INSERT INTO fix_verses VALUES ('B006C004V008', '6', 4, 8, 'И сделали сыны Израилевы так, как приказал Иисус: взяли двенадцать камней из Иордана, как говорил Господь Иисусу, почислу колен сынов Израилевых, и перенесли их с собою на ночлег, и положили их там.', 'И сделали сыны Израилевы так, как приказал Иисус: взяли двенадцать камней из Иордана, как говорил Господь Иисусу, по числу колен сынов Израилевых, и перенесли их с собою на ночлег, и положили их там.');
INSERT INTO fix_verses VALUES ('B006C004V009', '6', 4, 9, 'И [другие] двенадцать камней поставил Иисус среди Иордана наместе, где стояли ноги священников, несших ковчег завета. Они там и до сего дня.', 'И [другие] двенадцать камней поставил Иисус среди Иордана на месте, где стояли ноги священников, несших ковчег завета. Они там и до сего дня.');
INSERT INTO fix_verses VALUES ('B006C004V010', '6', 4, 10, 'Священники, несшие ковчег, стояли среди Иордана, доколе не окончено было все, что Господь повелел Иисусу сказать народу так, как завещал Моисей Иисусу; а народ между тем поспешно переходил.', 'Священники, несшие ковчег, стояли среди Иордана, доколе не окончено было все, что Господь повелел Иисусу сказать народу — так, как завещал Моисей Иисусу; а народ между тем поспешно переходил.');
INSERT INTO fix_verses VALUES ('B006C004V012', '6', 4, 12, 'И сыны Рувима и сыны Гада и половина колена Манассиина перешли вооруженные впереди сынов Израилевых, как говорил Иммоисей.', 'И сыны Рувима и сыны Гада и половина колена Манассиина перешли вооруженные впереди сынов Израилевых, как говорил им Моисей.');
INSERT INTO fix_verses VALUES ('B006C004V014', '6', 4, 14, 'В тот день прославил Господь Иисуса пред очами всего Израиля и стали бояться его, как боялись Моисея, во все дни жизниего.', 'В тот день прославил Господь Иисуса пред очами всего Израиля и стали бояться его, как боялись Моисея, во все дни жизни его.');
INSERT INTO fix_verses VALUES ('B006C004V022', '6', 4, 22, 'Скажите сынам вашим: «Израиль перешел чрез Иордан сей посуше»,', 'Скажите сынам вашим: «Израиль перешел чрез Иордан сей по суше»,');
INSERT INTO fix_verses VALUES ('B006C004V023', '6', 4, 23, 'Ибо Господь Бог ваш иссушил воды Иордана для вас, доколе вы не перешли его, так же, как Господь Бог ваш сделал с Чермным морем, которое иссушил пред нами, доколе мыне перешли его,', 'Ибо Господь Бог ваш иссушил воды Иордана для вас, доколе вы не перешли его, так же, как Господь Бог ваш сделал с Чермным морем, которое иссушил пред нами, доколе мы не перешли его,');
INSERT INTO fix_verses VALUES ('B006C004V024', '6', 4, 24, 'Дабы все народы земли познали, что рука Господня сильна, идабы вы боялись Господа Бога вашего во все дни.', 'Дабы все народы земли познали, что рука Господня сильна, и дабы вы боялись Господа Бога вашего во все дни.');
INSERT INTO fix_verses VALUES ('B006C007V013', '6', 7, 13, 'Встань, освяти народ и скажи: освятитесь к утру, ибо так говорит Господь Бог Израилев: «заклятое среди тебя, Израиль; посему ты не можешь устоять пред врагами твоим, доколе не отдалишь от себя заклятого»;', 'Встань, освяти народ и скажи: освятитесь к утру, ибо так говорит Господь Бог Израилев: «заклятое среди тебя, Израиль; посему ты не можешь устоять пред врагами твоими, доколе не отдалишь от себя заклятого»;');
INSERT INTO fix_verses VALUES ('B006C008V031', '6', 8, 31, 'Как заповедал Моисей, раб Господень, сынам Израилевым, о чем написано в книге закона Моисеева,  — жертвенник из камней цельных, на которые не поднимали железа; и принесли на нем всесожжение Господу и совершили жертвы мирные.', 'Как заповедал Моисей, раб Господень, сынам Израилевым, о чем написано в книге закона Моисеева, — жертвенник из камней цельных, на которые не поднимали железа; и принесли на нем всесожжение Господу и совершили жертвы мирные.');
INSERT INTO fix_verses VALUES ('B006C009V027', '6', 9, 27, 'И определил в тот день Иисус, чтобы они рубили дрова и черпали воду для общества и для жертвенника Господня;  — посему жители Гаваона сделались дровосеками и водоносами для жертвенника Божия,  — даже до сего дня, на месте, какое ни избрал бы [Господь].', 'И определил в тот день Иисус, чтобы они рубили дрова и черпали воду для общества и для жертвенника Господня; — посему жители Гаваона сделались дровосеками и водоносами для жертвенника Божия, — даже до сего дня, на месте, какое ни избрал бы [Господь].');
INSERT INTO fix_verses VALUES ('B006C013V017', '6', 13, 17, 'Есевон и все города его, которые на равнине, и Дивон, Вамоф-Ваали Беф-Ваал-Меон,', 'Есевон и все города его, которые на равнине, и Дивон, Вамоф-Ваал и Беф-Ваал-Меон,');
INSERT INTO fix_verses VALUES ('B006C024V010', '6', 24, 10, 'Но Я не хотел послушать Валаама,  — и он благословил вас, и Я избавил вас из рук его.', 'Но Я не хотел послушать Валаама, — и он благословил вас, и Я избавил вас из рук его.');
INSERT INTO fix_verses VALUES ('B007C002V010', '7', 2, 10, 'И когда весь народ оный отошел к отцам своим, и восстал после них другой род, который не знал Господа и дел Его, какие Он делал Израилю,  —', 'И когда весь народ оный отошел к отцам своим, и восстал после них другой род, который не знал Господа и дел Его, какие Он делал Израилю, —');
INSERT INTO fix_verses VALUES ('B007C002V021', '7', 2, 21, 'И Я не стану уже изгонять от них ни одного из тех народов, которых оставил Иисус, когда умирал,  —', 'И Я не стану уже изгонять от них ни одного из тех народов, которых оставил Иисус, когда умирал, —');
INSERT INTO fix_verses VALUES ('B007C003V001', '7', 3, 1, 'Вот те народы, которых оставил Господь, чтобы искушать ими Израильтян, всех, которые не знали о всех войнах Ханаанских,  —', 'Вот те народы, которых оставил Господь, чтобы искушать ими Израильтян, всех, которые не знали о всех войнах Ханаанских, —');
INSERT INTO fix_verses VALUES ('B007C004V016', '7', 4, 16, 'Варак преследовал колесницы [его] и ополчение до Харошеф — Гоима, и пало все ополчение Сисарино от меча, не осталось никого.', 'Варак преследовал колесницы [его] и ополчение до Харошеф-Гоима, и пало все ополчение Сисарино от меча, не осталось никого.');
INSERT INTO fix_verses VALUES ('B007C005V031', '7', 5, 31, 'Так да погибнут все враги Твои, Господи! Любящие же Его [да] [будут] как солнце, восходящее во всей силе своей!  — И покоилась земля сорок лет.', 'Так да погибнут все враги Твои, Господи! Любящие же Его [да] [будут] как солнце, восходящее во всей силе своей! — И покоилась земля сорок лет.');
INSERT INTO fix_verses VALUES ('B007C018V012', '7', 18, 12, 'Они пошли и стали станом в Кириаф-Иариме, в Иудее. Посему и называют то место станом Дановым до сего дня. Он позади Кириаф — Иарима.', 'Они пошли и стали станом в Кириаф-Иариме, в Иудее. Посему и называют то место станом Дановым до сего дня. Он позади Кириаф-Иарима.');
INSERT INTO fix_verses VALUES ('B007C018V029', '7', 18, 29, 'И нарекли имя городу: Дан, по имени отца своего Дана, сына Израилева; а прежде имя города тому было: Лаис.', 'И нарекли имя городу: Дан, по имени отца своего Дана, сына Израилева; а прежде имя городу тому было: Лаис.');
INSERT INTO fix_verses VALUES ('B008C001V012', '8', 1, 12, 'Возвратитесь, дочери мои, пойдите, ибо я уже стара, чтоб быть замужем. Да если б я и сказала: «есть мне еще надежда», и даже если бы я сию же ночь была с мужем и потом родила сыновей,  —', 'Возвратитесь, дочери мои, пойдите, ибо я уже стара, чтоб быть замужем. Да если б я и сказала: «есть мне еще надежда», и даже если бы я сию же ночь была с мужем и потом родила сыновей, —');
INSERT INTO fix_verses VALUES ('B009C001V001', '9', 1, 1, 'Был один человек из Рамафаим-Цофима, с горы Ефремовой, имя ему Елкана, сын Иерохама, сына Илия, сына Тоху, сына Цуфа,  — Ефрафянин;', 'Был один человек из Рамафаим-Цофима, с горы Ефремовой, имя ему Елкана, сын Иерохама, сына Илия, сына Тоху, сына Цуфа, — Ефрафянин;');
INSERT INTO fix_verses VALUES ('B009C003V002', '9', 3, 2, 'И было в то время, когда Илий лежал на своем месте,  — глаза же его начали смежаться, и он не мог видеть,  —', 'И было в то время, когда Илий лежал на своем месте, — глаза же его начали смежаться, и он не мог видеть, —');
INSERT INTO fix_verses VALUES ('B009C004V021', '9', 4, 21, 'И назвала младенца: Ихавод, сказав: «отошла слава от Израиля»  — со взятием ковчега Божия и [со смертью] свекра ее и мужа ее.', 'И назвала младенца: Ихавод, сказав: «отошла слава от Израиля» — со взятием ковчега Божия и [со смертью] свекра ее и мужа ее.');
INSERT INTO fix_verses VALUES ('B009C005V001', '9', 5, 1, 'Филистимляне же взяли ковчег Божий и принесли его из Авен — Езера в Азот.', 'Филистимляне же взяли ковчег Божий и принесли его из Авен-Езера в Азот.');
INSERT INTO fix_verses VALUES ('B009C009V027', '9', 9, 27, 'Когда подходили они к концу города, Самуил сказал Саулу: скажи слуге, чтобы он пошел впереди нас,  — и он пошел вперед;  — а ты остановись теперь, и я открою тебе, что сказал Бог.', 'Когда подходили они к концу города, Самуил сказал Саулу: скажи слуге, чтобы он пошел впереди нас, — и он пошел вперед; — а ты остановись теперь, и я открою тебе, что сказал Бог.');
INSERT INTO fix_verses VALUES ('B009C012V003', '9', 12, 3, 'Вот я; свидетельствуйте на меня пред Господом и пред помазанником Его, у кого взял я вола, у кого взял осла, кого обидел и кого притеснил, у кого взял дар и закрыл в [деле] его глаза мои,  — и я возвращу вам.', 'Вот я; свидетельствуйте на меня пред Господом и пред помазанником Его, у кого взял я вола, у кого взял осла, кого обидел и кого притеснил, у кого взял дар и закрыл в [деле] его глаза мои, — и я возвращу вам.');
INSERT INTO fix_verses VALUES ('B009C014V039', '9', 14, 39, 'Ибо,  — жив Господь, спасший Израиля,  — если окажется и на Ионафане, сыне моем, то и он умрет непременно. Но никто не отвечал ему из всего народа.', 'Ибо, — жив Господь, спасший Израиля, — если окажется и на Ионафане, сыне моем, то и он умрет непременно. Но никто не отвечал ему из всего народа.');
INSERT INTO fix_verses VALUES ('B009C014V042', '9', 14, 42, 'Тогда сказал Саул: бросьте жребий между мною и между Ионафаном, сыном моим. и пал жребий на Ионафана.', 'Тогда сказал Саул: бросьте жребий между мною и между Ионафаном, сыном моим. И пал жребий на Ионафана.');
INSERT INTO fix_verses VALUES ('B009C016V023', '9', 16, 23, 'И когда дух от Бога бывал на Сауле, то Давид, взяв гусли, играл,  — и отраднее и лучше становилось Саулу, и дух злой отступал от него.', 'И когда дух от Бога бывал на Сауле, то Давид, взяв гусли, играл, — и отраднее и лучше становилось Саулу, и дух злой отступал от него.');
INSERT INTO fix_verses VALUES ('B009C020V008', '9', 20, 8, 'Ты же сделай милость рабу твоему,  — ибо ты принял раба твоего в завет Господень с тобою,  — и если есть какая вина на мне, то умертви ты меня; зачем тебе вести меня к отцу твоему?', 'Ты же сделай милость рабу твоему, — ибо ты принял раба твоего в завет Господень с тобою, — и если есть какая вина на мне, то умертви ты меня; зачем тебе вести меня к отцу твоему?');
INSERT INTO fix_verses VALUES ('B009C025V034', '9', 25, 34, 'Но,  — жив Господь Бог Израилев, удержавший меня от нанесения зла тебе,  — если бы ты не поспешила и не пришла навстречу мне, то до рассвета утреннего я не оставил бы Навалу мочащегося к стене.', 'Но, — жив Господь Бог Израилев, удержавший меня от нанесения зла тебе, — если бы ты не поспешила и не пришла навстречу мне, то до рассвета утреннего я не оставил бы Навалу мочащегося к стене.');
INSERT INTO fix_verses VALUES ('B009C028V014', '9', 28, 14, 'Какой он видом?  — спросил у нее [Саул]. Она сказала: выходит из земли муж престарелый, одетый в длинную одежду. Тогда узнал Саул, что это Самуил, и пал лицем на землю и поклонился.', 'Какой он видом? — спросил у нее [Саул]. Она сказала: выходит из земли муж престарелый, одетый в длинную одежду. Тогда узнал Саул, что это Самуил, и пал лицем на землю и поклонился.');
INSERT INTO fix_verses VALUES ('B009C030V026', '9', 30, 26, 'И пришел Давид в Секелаг и послал из добычи к старейшинам Иудиным, друзьям своим, говоря: «вот вам подарок из добычи, [взятой] у врагов Господних»,  —', 'И пришел Давид в Секелаг и послал из добычи к старейшинам Иудиным, друзьям своим, говоря: «вот вам подарок из добычи, [взятой] у врагов Господних», —');
INSERT INTO fix_verses VALUES ('B010C005V006', '10', 5, 6, 'И пошел царь и люди его на Иерусалим против Иевусеев, жителей той страны; но они говорили Давиду: «ты не войдешь сюда; тебя отгонят слепые и хромые»,  — это значило: «не войдет сюда Давид».', 'И пошел царь и люди его на Иерусалим против Иевусеев, жителей той страны; но они говорили Давиду: «ты не войдешь сюда; тебя отгонят слепые и хромые», — это значило: «не войдет сюда Давид».');
INSERT INTO fix_verses VALUES ('B010C006V020', '10', 6, 20, 'Когда Давид возвратился, чтобы благословить дом свой, то Мелхола, дочь Саула, вышла к нему на встречу и сказала: как отличился сегодня царь Израилев, обнажившись сегодня пред глазами рабынь рабов своих, как обнажается какой — нибудь пустой человек!', 'Когда Давид возвратился, чтобы благословить дом свой, то Мелхола, дочь Саула, вышла к нему навстречу и сказала: как отличился сегодня царь Израилев, обнажившись сегодня пред глазами рабынь рабов своих, как обнажается какой-нибудь пустой человек!');
INSERT INTO fix_verses VALUES ('B010C008V016', '10', 8, 16, 'Иоав же, сын Саруи, [был начальником] войска; и Иосафат, сын Ахилуда,  — дееписателем;', 'Иоав же, сын Саруи, [был начальником] войска; и Иосафат, сын Ахилуда, — дееписателем;');
INSERT INTO fix_verses VALUES ('B010C008V017', '10', 8, 17, 'Садок, сын Ахитува, и Ахимелех, сын Авиафара,  — священниками, Сераия — писцом;', 'Садок, сын Ахитува, и Ахимелех, сын Авиафара, — священниками, Сераия — писцом;');
INSERT INTO fix_verses VALUES ('B010C010V013', '10', 10, 13, 'И вступил Иоав в народ, который [был] у него, в сражение с Сирийцами, и они побежали от него.', 'И вступил Иоав и народ, который [был] у него, в сражение с Сирийцами, и они побежали от него.');
INSERT INTO fix_verses VALUES ('B010C012V018', '10', 12, 18, 'На седьмой день дитя умерло, и слуги Давидовы боялись донести ему, что умер младенец; ибо, говорили они, когда дитя было еще живо, и мы уговаривали его, и он не слушал голоса нашего, как же мы скажем ему: «умерло дитя»? Он сделает что — нибудь худое.', 'На седьмой день дитя умерло, и слуги Давидовы боялись донести ему, что умер младенец; ибо, говорили они, когда дитя было еще живо, и мы уговаривали его, и он не слушал голоса нашего, как же мы скажем ему: «умерло дитя»? Он сделает что-нибудь худое.');
INSERT INTO fix_verses VALUES ('B010C012V030', '10', 12, 30, 'И взял Давид венец царя их с головы его,  — а в нем было золота талант и драгоценный камень,  — и возложил его Давид на свою голову, и добычи из города вынес очень много.', 'И взял Давид венец царя их с головы его, — а в нем было золота талант и драгоценный камень, — и возложил его Давид на свою голову, и добычи из города вынес очень много.');
INSERT INTO fix_verses VALUES ('B010C013V004', '10', 13, 4, 'И он сказал ему: отчего ты так худеешь с каждым днем, сын царев,  — не откроешь ли мне? И сказал ему Амнон: Фамарь, сестру Авессалома, брата моего, люблю я.', 'И он сказал ему: отчего ты так худеешь с каждым днем, сын царев, — не откроешь ли мне? И сказал ему Амнон: Фамарь, сестру Авессалома, брата моего, люблю я.');
INSERT INTO fix_verses VALUES ('B010C013V020', '10', 13, 20, 'И сказал ей Авессалом, брат ее: не Амнон ли, брат твой, был с тобою?  — но теперь молчи, сестра моя; он — брат твой; не сокрушайся сердцем твоим об этом деле. И жила Фамарь в одиночестве в доме Авессалома, брата своего.', 'И сказал ей Авессалом, брат ее: не Амнон ли, брат твой, был с тобою? — но теперь молчи, сестра моя; он — брат твой; не сокрушайся сердцем твоим об этом деле. И жила Фамарь в одиночестве в доме Авессалома, брата своего.');
INSERT INTO fix_verses VALUES ('B010C013V023', '10', 13, 23, 'Чрез два года было стрижение [овец] у Авессалома в Ваал — Гацоре, что у Ефрема, и позвал Авессалом всех сыновей царских.', 'Чрез два года было стрижение [овец] у Авессалома в Ваал-Гацоре, что у Ефрема, и позвал Авессалом всех сыновей царских.');
INSERT INTO fix_verses VALUES ('B010C014V026', '10', 14, 26, 'Когда он стриг голову свою,  — а он стриг ее каждый год, потому что она отягощала его,  — то волоса с головы его весили двести сиклей по весу царскому.', 'Когда он стриг голову свою, — а он стриг ее каждый год, потому что она отягощала его, — то волоса с головы его весили двести сиклей по весу царскому.');
INSERT INTO fix_verses VALUES ('B010C015V027', '10', 15, 27, 'И сказал царь Садоку священнику: видишь ли,  — возвратись в город с миром, и Ахимаас, сын твой, и Ионафан, сын Авиафара, оба сына ваши с вами;', 'И сказал царь Садоку священнику: видишь ли, — возвратись в город с миром, и Ахимаас, сын твой, и Ионафан, сын Авиафара, оба сына ваши с вами;');
INSERT INTO fix_verses VALUES ('B010C015V037', '10', 15, 37, 'И пришел Хусий, друг Давида, в город; Авессалом же вступал тогда в Иерусалим.', 'И пришел Хусий, друг Давидов, в город; Авессалом же вступал тогда в Иерусалим.');
INSERT INTO fix_verses VALUES ('B010C018V007', '10', 18, 7, 'И был поражен народ Израильский рабами Давида; было там поражение великое в тот день,  — поражены двадцать тысяч [человек].', 'И был поражен народ Израильский рабами Давида; было там поражение великое в тот день, — поражены двадцать тысяч [человек].');
INSERT INTO fix_verses VALUES ('B010C019V041', '10', 19, 41, 'И вот, все Израильтяне пришли к царю и сказали царю: зачем братья наши, мужи Иудины, похитили тебя и проводили царя в дом его и всех людей Давида с ним через Иордан?', 'И вот, все Израильтяне пришли к царю и сказали царю: зачем братья наши, мужи Иудины, похитили тебя и проводили царя и дом его и всех людей Давида с ним через Иордан?');
INSERT INTO fix_verses VALUES ('B010C019V042', '10', 19, 42, 'И отвечали все мужи Иудины Израильтянам: затем, что царь ближний нам; и из-за чего сердиться вам на это? Разве мы что — нибудь съели у царя, или получили от него подарки?', 'И отвечали все мужи Иудины Израильтянам: затем, что царь ближний нам; и из-за чего сердиться вам на это? Разве мы что-нибудь съели у царя, или получили от него подарки?');
INSERT INTO fix_verses VALUES ('B010C020V023', '10', 20, 23, 'И был Иоав [поставлен] над всем войском Израильским, а Ванея, сын Иодаев,  — над Хелефеями и над Фелефеями;', 'И был Иоав [поставлен] над всем войском Израильским, а Ванея, сын Иодаев, — над Хелефеями и над Фелефеями;');
INSERT INTO fix_verses VALUES ('B010C021V005', '10', 21, 5, 'И сказали они царю: того человека, который губил нас и хотел истребить нас, чтобы не было нас ни в одном из пределов Израилевых,  —', 'И сказали они царю: того человека, который губил нас и хотел истребить нас, чтобы не было нас ни в одном из пределов Израилевых, —');
INSERT INTO fix_verses VALUES ('B010C022V031', '10', 22, 31, 'Бог!  — непорочен путь Его, чисто слово Господа, щит Он для всех, надеющихся на Него.', 'Бог! — непорочен путь Его, чисто слово Господа, щит Он для всех, надеющихся на Него.');
INSERT INTO fix_verses VALUES ('B010C022V042', '10', 22, 42, 'Они взывают, но нет спасающего,  — ко Господу, но Он не внемлет им.', 'Они взывают, но нет спасающего, — ко Господу, но Он не внемлет им.');
INSERT INTO fix_verses VALUES ('B010C024V006', '10', 24, 6, 'И пришли в Галаад и в землю Тахтим-Ходши; и пришли в Дан — Яан и обошли Сидон;', 'И пришли в Галаад и в землю Тахтим-Ходши; и пришли в Дан-Яан и обошли Сидон;');
INSERT INTO fix_verses VALUES ('B011C001V002', '11', 1, 2, 'И сказали ему слуги его: пусть поищут для господина нашего царя молодую девицу, чтоб она предстояла царю и ходила за ним и лежала с ним,  — и будет тепло господину нашему, царю.', 'И сказали ему слуги его: пусть поищут для господина нашего царя молодую девицу, чтоб она предстояла царю и ходила за ним и лежала с ним, — и будет тепло господину нашему, царю.');
INSERT INTO fix_verses VALUES ('B011C001V020', '11', 1, 20, 'Но ты, господин мой,  — царь, и глаза всех Израильтян [устремлены] на тебя, чтобы ты объявил им, кто сядет на престоле господина моего царя после него;', 'Но ты, господин мой, — царь, и глаза всех Израильтян [устремлены] на тебя, чтобы ты объявил им, кто сядет на престоле господина моего царя после него;');
INSERT INTO fix_verses VALUES ('B011C001V036', '11', 1, 36, 'И отвечал Ванея, сын Иодаев, царю и сказал: аминь,  — да скажет так Господь Бог господина моего царя!', 'И отвечал Ванея, сын Иодаев, царю и сказал: аминь, — да скажет так Господь Бог господина моего царя!');
INSERT INTO fix_verses VALUES ('B011C002V024', '11', 2, 24, 'Ныне же,  — жив Господь, укрепивший меня и посадивший меня на престоле Давида, отца моего, и устроивший мне дом, как говорил Он,  — ныне же Адония должен умереть.', 'Ныне же, — жив Господь, укрепивший меня и посадивший меня на престоле Давида, отца моего, и устроивший мне дом, как говорил Он, — ныне же Адония должен умереть.');
INSERT INTO fix_verses VALUES ('B011C002V028', '11', 2, 28, 'Слух [об этом] дошел до Иоава,  — так как Иоав склонялся на сторону Адонии, а на сторону Соломона не склонялся,  — и убежал Иоав в скинию Господню и ухватился за роги жертвенника.', 'Слух [об этом] дошел до Иоава, — так как Иоав склонялся на сторону Адонии, а на сторону Соломона не склонялся, — и убежал Иоав в скинию Господню и ухватился за роги жертвенника.');
INSERT INTO fix_verses VALUES ('B011C003V011', '11', 3, 11, 'И сказал ему Бог: за то, что ты просил этого и не просил себе долгой жизни, не просил себе богатства, не просил себе душ врагов твоих, но просил себе разума, чтоб уметь судить,  —', 'И сказал ему Бог: за то, что ты просил этого и не просил себе долгой жизни, не просил себе богатства, не просил себе душ врагов твоих, но просил себе разума, чтоб уметь судить, —');
INSERT INTO fix_verses VALUES ('B011C004V006', '11', 4, 6, 'Ахисар — начальник над домом [царским], и Адонирам, сын Авды,  — над податями.', 'Ахисар — начальник над домом [царским], и Адонирам, сын Авды, — над податями.');
INSERT INTO fix_verses VALUES ('B011C006V038', '11', 6, 38, 'А на одиннадцатом году, в месяце Буле,  — это месяц восьмой,  — он окончил храм со всеми принадлежностями его и по всем предначертаниям его; строил его семь лет.', 'А на одиннадцатом году, в месяце Буле, — это месяц восьмой, — он окончил храм со всеми принадлежностями его и по всем предначертаниям его; строил его семь лет.');
INSERT INTO fix_verses VALUES ('B011C007V001', '11', 7, 1, 'А свой дом Соломон строил тринадцать лет и окончил весь домсвой.', 'А свой дом Соломон строил тринадцать лет и окончил весь дом свой.');
INSERT INTO fix_verses VALUES ('B011C007V002', '11', 7, 2, 'И построил он дом из дерева Ливанского, длиною во столоктей, шириною в пятьдесят локтей, а вышиною в тридцать локтей, на четырех рядах кедровых столбов; и кедровые бревна [положены были] на столбах.', 'И построил он дом из дерева Ливанского, длиною во сто локтей, шириною в пятьдесят локтей, а вышиною в тридцать локтей, на четырех рядах кедровых столбов; и кедровые бревна [положены были] на столбах.');
INSERT INTO fix_verses VALUES ('B011C007V003', '11', 7, 3, 'И настлан был помост из кедра над бревнами на сорока пятистолбах, по пятнадцати в ряд.', 'И настлан был помост из кедра над бревнами на сорока пяти столбах, по пятнадцати в ряд.');
INSERT INTO fix_verses VALUES ('B011C007V004', '11', 7, 4, 'Оконных косяков [было] три ряда; и три ряда [окон], окно противокна.', 'Оконных косяков [было] три ряда; и три ряда [окон], окно против окна.');
INSERT INTO fix_verses VALUES ('B011C007V005', '11', 7, 5, 'И все двери и дверные косяки были четырехугольные, и окнопротив окна, в три ряда.', 'И все двери и дверные косяки были четырехугольные, и окно против окна, в три ряда.');
INSERT INTO fix_verses VALUES ('B011C007V006', '11', 7, 6, 'И притвор из столбов сделал он длиною в пятьдесят локтей, шириною в тридцать локтей, и пред ними крыльцо, и столбы, и порогпред ними.', 'И притвор из столбов сделал он длиною в пятьдесят локтей, шириною в тридцать локтей, и пред ними крыльцо, и столбы, и порог пред ними.');
INSERT INTO fix_verses VALUES ('B011C007V007', '11', 7, 7, 'Еще притвор с престолом, с которого он судил, притвор длясудилища сделал он и покрыл все полы кедром.', 'Еще притвор с престолом, с которого он судил, притвор для судилища сделал он и покрыл все полы кедром.');
INSERT INTO fix_verses VALUES ('B011C007V008', '11', 7, 8, 'В доме, где он жил, другой двор позади притвора был такогоже устройства. И в доме дочери фараоновой, которую взял за Себясоломон, он сделал такой же притвор.', 'В доме, где он жил, другой двор позади притвора был такого же устройства. И в доме дочери фараоновой, которую взял за себя Соломон, он сделал такой же притвор.');
INSERT INTO fix_verses VALUES ('B011C007V009', '11', 7, 9, 'Все это сделано было из дорогих камней, обтесанных поразмеру, обрезанных пилою, с внутренней и наружной стороны, отоснования до выступов, и с наружной стороны до большого двора.', 'Все это сделано было из дорогих камней, обтесанных по размеру, обрезанных пилою, с внутренней и наружной стороны, от основания до выступов, и с наружной стороны до большого двора.');
INSERT INTO fix_verses VALUES ('B011C007V012', '11', 7, 12, 'Большой двор огорожен был кругом тремя рядами тесаныхкамней и одним рядом кедровых бревен; также и внутренний дворхрама Господа и притвор храма.', 'Большой двор огорожен был кругом тремя рядами тесаных камней и одним рядом кедровых бревен; также и внутренний двор храма Господа и притвор храма.');
INSERT INTO fix_verses VALUES ('B011C007V014', '11', 7, 14, 'Сына одной вдовы, из колена Неффалимова. Отец его Тирянинбыл медник; он владел способностью, искусством и уменьемвыделывать всякие вещи из меди. И пришел он к царю Соломону ипроизводил у него всякие работы:', 'Сына одной вдовы, из колена Неффалимова. Отец его Тирянин был медник; он владел способностью, искусством и уменьем выделывать всякие вещи из меди. И пришел он к царю Соломону и производил у него всякие работы:');
INSERT INTO fix_verses VALUES ('B011C007V015', '11', 7, 15, 'И сделал он два медных столба, каждый в восемнадцать локтейвышиною, и снурок в двенадцать локтей обнимал [окружность] того идругого столба;', 'И сделал он два медных столба, каждый в восемнадцать локтей вышиною, и снурок в двенадцать локтей обнимал [окружность] того и другого столба;');
INSERT INTO fix_verses VALUES ('B011C007V016', '11', 7, 16, 'И два венца, вылитых из меди, он сделал, чтобы положить наверху столбов: пять локтей вышины в одном венце и пять локтейвышины в другом венце;', 'И два венца, вылитых из меди, он сделал, чтобы положить на верху столбов: пять локтей вышины в одном венце и пять локтей вышины в другом венце;');
INSERT INTO fix_verses VALUES ('B011C007V017', '11', 7, 17, 'Сетки плетеной работы и снурки в виде цепочек для венцов, которые были на верху столбов: семь на одном венце и семь надругом венце.', 'Сетки плетеной работы и снурки в виде цепочек для венцов, которые были на верху столбов: семь на одном венце и семь на другом венце.');
INSERT INTO fix_verses VALUES ('B011C007V018', '11', 7, 18, 'Так сделал он столбы и два ряда гранатовых яблок вокругсетки, чтобы покрыть венцы, которые на верху столбов; то жесделал и для другого венца.', 'Так сделал он столбы и два ряда гранатовых яблок вокруг сетки, чтобы покрыть венцы, которые на верху столбов; то же сделал и для другого венца.');
INSERT INTO fix_verses VALUES ('B011C007V019', '11', 7, 19, 'А в притворе венцы на верху столбов сделаны [наподобиелилии], в четыре локтя,', 'А в притворе венцы на верху столбов сделаны [наподобие лилии], в четыре локтя,');
INSERT INTO fix_verses VALUES ('B011C007V020', '11', 7, 20, 'И венцы на обоих столбах вверху, прямо над выпуклостью, которая подле сетки; и на другом венце, рядами кругом, двестигранатовых яблок.', 'И венцы на обоих столбах вверху, прямо над выпуклостью, которая подле сетки; и на другом венце, рядами кругом, двести гранатовых яблок.');
INSERT INTO fix_verses VALUES ('B011C007V021', '11', 7, 21, 'И поставил столбы к притвору храма; поставил столб направой стороне и дал ему имя Иахин, и поставил столб на левойстороне и дал ему имя Воаз.', 'И поставил столбы к притвору храма; поставил столб на правой стороне и дал ему имя Иахин, и поставил столб на левой стороне и дал ему имя Воаз.');
INSERT INTO fix_verses VALUES ('B011C007V023', '11', 7, 23, 'И сделал литое [из меди] море,  — от края его до края его десять локтей,  — совсем круглое, вышиною в пять локтей, и снурок в тридцать локтей обнимал его кругом.', 'И сделал литое [из меди] море, — от края его до края его десять локтей, — совсем круглое, вышиною в пять локтей, и снурок в тридцать локтей обнимал его кругом.');
INSERT INTO fix_verses VALUES ('B011C007V024', '11', 7, 24, '[Подобия] огурцов под краями его окружали его по десяти налокоть, окружали море со всех сторон в два ряда; [подобия] огурцовбыли вылиты с ним одним литьем.', '[Подобия] огурцов под краями его окружали его по десяти на локоть, окружали море со всех сторон в два ряда; [подобия] огурцов были вылиты с ним одним литьем.');
INSERT INTO fix_verses VALUES ('B011C007V025', '11', 7, 25, 'Оно стояло на двенадцати волах: три глядели к северу, триглядели к западу, три глядели к югу и три глядели к востоку; морележало на них, и зады их [обращены были] внутрь под него.', 'Оно стояло на двенадцати волах: три глядели к северу, три глядели к западу, три глядели к югу и три глядели к востоку; море лежало на них, и зады их [обращены были] внутрь под него.');
INSERT INTO fix_verses VALUES ('B011C007V026', '11', 7, 26, 'Толщиною оно было в ладонь, и края его, сделанные подобнокраям чаши, [походили] на распустившуюся лилию. Оно вмещало дветысячи батов.', 'Толщиною оно было в ладонь, и края его, сделанные подобно краям чаши, [походили] на распустившуюся лилию. Оно вмещало две тысячи батов.');
INSERT INTO fix_verses VALUES ('B011C007V027', '11', 7, 27, 'И сделал он десять медных подстав; длина каждой подставы гчетыре локтя, ширина г четыре локтя и три локтя г вышина.', 'И сделал он десять медных подстав; длина каждой подставы — четыре локтя, ширина — четыре локтя и три локтя — вышина.');
INSERT INTO fix_verses VALUES ('B011C007V028', '11', 7, 28, 'И вот устройство подстав: у них стенки, стенки междунаугольными пластинками;', 'И вот устройство подстав: у них стенки, стенки между наугольными пластинками;');
INSERT INTO fix_verses VALUES ('B011C007V029', '11', 7, 29, 'На стенках, которые между наугольниками, [изображены] былильвы, волы и херувимы; также и на наугольниках, а выше и нижельвов и волов г развесистые венки;', 'На стенках, которые между наугольниками, [изображены] были львы, волы и херувимы; также и на наугольниках, а выше и ниже львов и волов — развесистые венки;');
INSERT INTO fix_verses VALUES ('B011C007V030', '11', 7, 30, 'У каждой подставы по четыре медных колеса и оси медные. Начетырех углах выступы наподобие плеч, выступы литые внизу, подчашею, подле каждого венка.', 'У каждой подставы по четыре медных колеса и оси медные. На четырех углах выступы наподобие плеч, выступы литые внизу, под чашею, подле каждого венка.');
INSERT INTO fix_verses VALUES ('B011C007V032', '11', 7, 32, 'Под стенками было четыре колеса, и оси колес в подставах; вышина каждого колеса г полтора локтя.', 'Под стенками было четыре колеса, и оси колес в подставах; вышина каждого колеса — полтора локтя.');
INSERT INTO fix_verses VALUES ('B011C007V033', '11', 7, 33, 'Устройство колес такое же, как устройство колес вколеснице; оси их, и ободья их, и спицы их, и ступицы их, всебыло литое.', 'Устройство колес такое же, как устройство колес в колеснице; оси их, и ободья их, и спицы их, и ступицы их, все было литое.');
INSERT INTO fix_verses VALUES ('B011C007V034', '11', 7, 34, 'Четыре выступа на четырех углах каждой подставы; изподставы [выходили] выступы ее.', 'Четыре выступа на четырех углах каждой подставы; из подставы [выходили] выступы ее.');
INSERT INTO fix_verses VALUES ('B011C007V035', '11', 7, 35, 'И на верху подставы круглое возвышение на полглоктя вышины; и на верху подставы рукоятки ее и стенки ее из одной с нею массы.', 'И на верху подставы круглое возвышение на пол-локтя вышины; и на верху подставы рукоятки ее и стенки ее из одной с нею массы.');
INSERT INTO fix_verses VALUES ('B011C007V036', '11', 7, 36, 'И изваял он на дощечках ее рукоятки и на стенках еехерувимов, львов и пальмы, сколько где позволяло место, и вокругразвесистые венки.', 'И изваял он на дощечках ее рукоятки и на стенках ее херувимов, львов и пальмы, сколько где позволяло место, и вокруг развесистые венки.');
INSERT INTO fix_verses VALUES ('B011C007V037', '11', 7, 37, 'Так сделал он десять подстав: у всех их одно литье, однамера, один вид.', 'Так сделал он десять подстав: у всех их одно литье, одна мера, один вид.');
INSERT INTO fix_verses VALUES ('B011C007V038', '11', 7, 38, 'И сделал десять медных умывальниц: каждая умывальницавмещала сорок батов, каждая умывальница была в четыре локтя, каждая умывальница стояла на одной из десяти подстав.', 'И сделал десять медных умывальниц: каждая умывальница вмещала сорок батов, каждая умывальница была в четыре локтя, каждая умывальница стояла на одной из десяти подстав.');
INSERT INTO fix_verses VALUES ('B011C007V039', '11', 7, 39, 'И расставил подставы г пять на правой стороне храма и пятьна левой стороне храма, а море поставил на правой стороне храма, на восточногюжной стороне.', 'И расставил подставы — пять на правой стороне храма и пять на левой стороне храма, а море поставил на правой стороне храма, на восточно-южной стороне.');
INSERT INTO fix_verses VALUES ('B011C007V040', '11', 7, 40, 'И сделал Хирам умывальницы и лопатки и чаши. И кончил Хирамвсю работу, которую производил у царя Соломона для Храмагосподня:', 'И сделал Хирам умывальницы и лопатки и чаши. И кончил Хирам всю работу, которую производил у царя Соломона для храма Господня:');
INSERT INTO fix_verses VALUES ('B011C007V041', '11', 7, 41, 'Два столба и две опояски венцов, которые на верху столбов, и две сетки для покрытия двух опоясок венцов, которые на верхустолбов;', 'Два столба и две опояски венцов, которые на верху столбов, и две сетки для покрытия двух опоясок венцов, которые на верху столбов;');
INSERT INTO fix_verses VALUES ('B011C007V042', '11', 7, 42, 'И четыреста гранатовых яблок на двух сетках; два рядагранатовых яблок для каждой сетки, для покрытия двух опоясоквенцов, которые на столбах;', 'И четыреста гранатовых яблок на двух сетках; два ряда гранатовых яблок для каждой сетки, для покрытия двух опоясок венцов, которые на столбах;');
INSERT INTO fix_verses VALUES ('B011C007V045', '11', 7, 45, 'И тазы, и лопатки, и чаши. Все вещи, которые сделал Хирамцарю Соломону для храма Господа, [были] из полированной меди.', 'И тазы, и лопатки, и чаши. Все вещи, которые сделал Хирам царю Соломону для храма Господа, [были] из полированной меди.');
INSERT INTO fix_verses VALUES ('B011C007V047', '11', 7, 47, 'И поставил Соломон все сии вещи [на место]. По причинечрезвычайного их множества, вес меди не определен.', 'И поставил Соломон все сии вещи [на место]. По причине чрезвычайного их множества, вес меди не определен.');
INSERT INTO fix_verses VALUES ('B011C007V048', '11', 7, 48, 'И сделал Соломон все вещи, которые в храме Господа: золотойжертвенник и золотой стол, на котором хлебы предложения;', 'И сделал Соломон все вещи, которые в храме Господа: золотой жертвенник и золотой стол, на котором хлебы предложения;');
INSERT INTO fix_verses VALUES ('B011C007V049', '11', 7, 49, 'И светильники г пять по правую сторону и пять по левуюсторону, пред задним отделением храма, из чистого золота, ицветы, и лампадки, и щипцы из золота;', 'И светильники — пять по правую сторону и пять по левую сторону, пред задним отделением храма, из чистого золота, и цветы, и лампадки, и щипцы из золота;');
INSERT INTO fix_verses VALUES ('B011C007V050', '11', 7, 50, 'И блюда, и ножи, и чаши, и лотки, и кадильницы из чистогозолота, и петли у дверей внутреннего храма во Святом Святых и удверей в храме из золота же.', 'И блюда, и ножи, и чаши, и лотки, и кадильницы из чистого золота, и петли у дверей внутреннего храма во Святом Святых и у дверей в храме из золота же.');
INSERT INTO fix_verses VALUES ('B011C007V051', '11', 7, 51, 'Так совершена вся работа, которую производил царь Соломондля храма Господа. И принес Соломон посвященное Давидом, отцомего; серебро и золото и вещи отдал в сокровищницы храма Господня.', 'Так совершена вся работа, которую производил царь Соломон для храма Господа. И принес Соломон посвященное Давидом, отцом его; серебро и золото и вещи отдал в сокровищницы храма Господня.');
INSERT INTO fix_verses VALUES ('B011C008V014', '11', 8, 14, 'И обратился царь лицем своим, и благословил все собрание Израильтян; все собрание Израильтян стояло,  —', 'И обратился царь лицем своим, и благословил все собрание Израильтян; все собрание Израильтян стояло, —');
INSERT INTO fix_verses VALUES ('B011C008V037', '11', 8, 37, 'Будет ли на земле голод, будет ли моровая язва, будет ли палящий ветер, ржавчина, саранча, червь, неприятель ли будет теснить его в земле его, [будет ли] какое бедствие, какая болезнь,  —', 'Будет ли на земле голод, будет ли моровая язва, будет ли палящий ветер, ржавчина, саранча, червь, неприятель ли будет теснить его в земле его, [будет ли] какое бедствие, какая болезнь, —');
INSERT INTO fix_verses VALUES ('B011C008V041', '11', 8, 41, 'Если и иноплеменник, который не от Твоего народа Израиля, придет из земли далекой ради имени Твоего,  —', 'Если и иноплеменник, который не от Твоего народа Израиля, придет из земли далекой ради имени Твоего, —');
INSERT INTO fix_verses VALUES ('B011C008V042', '11', 8, 42, 'Ибо и они услышат о Твоем имени великом и о Твоей руке сильной и о Твоей мышце простертой,  — и придет он и помолится у храма сего,', 'Ибо и они услышат о Твоем имени великом и о Твоей руке сильной и о Твоей мышце простертой, — и придет он и помолится у храма сего,');
INSERT INTO fix_verses VALUES ('B011C008V046', '11', 8, 46, 'Когда они согрешат пред Тобою,  — ибо нет человека, который не грешил бы,  — и Ты прогневаешься на них и предашь их врагам, и пленившие их отведут их в неприятельскую землю, далекую или близкую;', 'Когда они согрешат пред Тобою, — ибо нет человека, который не грешил бы, — и Ты прогневаешься на них и предашь их врагам, и пленившие их отведут их в неприятельскую землю, далекую или близкую;');
INSERT INTO fix_verses VALUES ('B011C008V065', '11', 8, 65, 'И сделал Соломон в это время праздник, и весь Израиль с ним,  — большое собрание, [сошедшееся] от входа в Емаф до реки Египетской пред Господом Богом нашим;  — семь дней и еще семь дней, четырнадцать дней.', 'И сделал Соломон в это время праздник, и весь Израиль с ним, — большое собрание, [сошедшееся] от входа в Емаф до реки Египетской пред Господом Богом нашим; — семь дней и еще семь дней, четырнадцать дней.');
INSERT INTO fix_verses VALUES ('B011C009V009', '11', 9, 9, 'И скажут: «за то, что они оставили Господа Бога своего, Который вывел отцов их из земли Египетской, и приняли других богов, и поклонялись им и служили им,  — за это навел на них Господь все сие бедствие».', 'И скажут: «за то, что они оставили Господа Бога своего, Который вывел отцов их из земли Египетской, и приняли других богов, и поклонялись им и служили им, — за это навел на них Господь все сие бедствие».');
INSERT INTO fix_verses VALUES ('B011C009V010', '11', 9, 10, 'По окончании двадцати лет, в которые Соломон построил два дома,  — дом Господень и дом царский,  —', 'По окончании двадцати лет, в которые Соломон построил два дома, — дом Господень и дом царский, —');
INSERT INTO fix_verses VALUES ('B011C009V011', '11', 9, 11, 'На что Хирам, царь Тирский, доставлял Соломону дерева кедровые и дерева кипарисовые и золото, по его желанию,  — царь Соломон дал Хираму двадцать городов в земле Галилейской.', 'На что Хирам, царь Тирский, доставлял Соломону дерева кедровые и дерева кипарисовые и золото, по его желанию, — царь Соломон дал Хираму двадцать городов в земле Галилейской.');
INSERT INTO fix_verses VALUES ('B011C011V015', '11', 11, 15, 'Когда Давид был в Идумее, и военачальник Иоав пришел для погребения убитых и избил весь мужеский пол в Идумее,  —', 'Когда Давид был в Идумее, и военачальник Иоав пришел для погребения убитых и избил весь мужеский пол в Идумее, —');
INSERT INTO fix_verses VALUES ('B011C011V016', '11', 11, 16, 'Ибо шесть месяцев прожил там Иоав и все Израильтяне, доколе не истребили всего мужеского пола в Идумее,  —', 'Ибо шесть месяцев прожил там Иоав и все Израильтяне, доколе не истребили всего мужеского пола в Идумее, —');
INSERT INTO fix_verses VALUES ('B011C011V018', '11', 11, 18, 'Отправившись из Мадиама, они пришли в Фаран и взяли с собою людей из Фарана и пришли в Египет к фараону, царю Египетскому. он дал ему дом, и назначил ему содержание, и дал ему землю.', 'Отправившись из Мадиама, они пришли в Фаран и взяли с собою людей из Фарана и пришли в Египет к фараону, царю Египетскому. Он дал ему дом, и назначил ему содержание, и дал ему землю.');
INSERT INTO fix_verses VALUES ('B011C011V026', '11', 11, 26, 'И Иеровоам, сын Наватов, Ефремлянин из Цареды,  — имя матери его вдовы: Церуа,  — раб Соломонов, поднял руку на царя.', 'И Иеровоам, сын Наватов, Ефремлянин из Цареды, — имя матери его вдовы: Церуа, — раб Соломонов, поднял руку на царя.');
INSERT INTO fix_verses VALUES ('B011C013V018', '11', 13, 18, 'И сказал он ему: и я пророк такой же, как ты, и Ангел говорил мне словом Господним, и сказал: «вороти его к себе в дом; пусть поест он хлеба и напьется воды».  — Он солгал ему.', 'И сказал он ему: и я пророк такой же, как ты, и Ангел говорил мне словом Господним, и сказал: «вороти его к себе в дом; пусть поест он хлеба и напьется воды». — Он солгал ему.');
INSERT INTO fix_verses VALUES ('B011C014V026', '11', 14, 26, 'И взял сокровища дома Господня и сокровища дома царского,  — Все взял; взял и все золотые щиты, которые сделал Соломон.', 'И взял сокровища дома Господня и сокровища дома царского, — Все взял; взял и все золотые щиты, которые сделал Соломон.');
INSERT INTO fix_verses VALUES ('B011C020V040', '11', 20, 40, 'Когда раб твой занялся теми и другими делами, его не стало.  — И сказал ему царь Израильский: таков тебе и приговор, ты сам решил.', 'Когда раб твой занялся теми и другими делами, его не стало. — И сказал ему царь Израильский: таков тебе и приговор, ты сам решил.');
INSERT INTO fix_verses VALUES ('B011C022V008', '11', 22, 8, 'И сказал царь Израильский Иосафату: есть еще один человек, чрез которого можно вопросить Господа, но я не люблю его, ибо он не пророчествует о мне доброго, а только худое,  — это Михей, сын Иемвлая. И сказал Иосафат: не говори, царь, так.', 'И сказал царь Израильский Иосафату: есть еще один человек, чрез которого можно вопросить Господа, но я не люблю его, ибо он не пророчествует о мне доброго, а только худое, — это Михей, сын Иемвлая. И сказал Иосафат: не говори, царь, так.');
INSERT INTO fix_verses VALUES ('B012C001V016', '12', 1, 16, 'И сказал ему: так говорит Господь: за то, что ты посылал послов вопрошать Веельзевула, божество Аккаронское, как будто в Израиле нет Бога, чтобы вопрошать о слове Его,  — с постели, на которую ты лег, не сойдешь с нее, но умрешь.', 'И сказал ему: так говорит Господь: за то, что ты посылал послов вопрошать Веельзевула, божество Аккаронское, как будто в Израиле нет Бога, чтобы вопрошать о слове Его, — с постели, на которую ты лег, не сойдешь с нее, но умрешь.');
INSERT INTO fix_verses VALUES ('B012C002V014', '12', 2, 14, 'И взял милоть Илии, упавшую с него, и ударил ею по воде, и сказал: где Господь, Бог Илии,  — Он Самый? И ударил по воде, и она расступилась туда и сюда, и перешел Елисей.', 'И взял милоть Илии, упавшую с него, и ударил ею по воде, и сказал: где Господь, Бог Илии, — Он Самый? И ударил по воде, и она расступилась туда и сюда, и перешел Елисей.');
INSERT INTO fix_verses VALUES ('B012C004V026', '12', 4, 26, 'Побеги к ней навстречу и скажи ей: «здорова ли ты? здоров ли муж твой? здоров ли ребенок?»  — Она сказала: здоровы.', 'Побеги к ней навстречу и скажи ей: «здорова ли ты? здоров ли муж твой? здоров ли ребенок?» — Она сказала: здоровы.');
INSERT INTO fix_verses VALUES ('B012C005V020', '12', 5, 20, 'И сказал Гиезий, слуга Елисея, человека Божия: вот, господин мой отказался взять из руки Неемана, этого Сириянина, то, что он приносил. Жив Господь! Побегу я за ним, и возьму у него что — нибудь.', 'И сказал Гиезий, слуга Елисея, человека Божия: вот, господин мой отказался взять из руки Неемана, этого Сириянина, то, что он приносил. Жив Господь! Побегу я за ним, и возьму у него что-нибудь.');
INSERT INTO fix_verses VALUES ('B012C010V002', '12', 10, 2, 'Когда придет это письмо к вам, то, так как у вас и сыновья господина вашего, у вас же и колесницы, и кони, и укрепленный город, и оружие,  —', 'Когда придет это письмо к вам, то, так как у вас и сыновья господина вашего, у вас же и колесницы, и кони, и укрепленный город, и оружие, —');
INSERT INTO fix_verses VALUES ('B012C010V029', '12', 10, 29, 'Впрочем от грехов Иеровоама, сына Наватова, который ввел Израиля в грех, от них не отступал Ииуй,  — от золотых тельцов, которые в Вефиле и которые в Дане.', 'Впрочем от грехов Иеровоама, сына Наватова, который ввел Израиля в грех, от них не отступал Ииуй, — от золотых тельцов, которые в Вефиле и которые в Дане.');
INSERT INTO fix_verses VALUES ('B012C014V009', '12', 14, 9, 'И послал Иоас, царь Израильский, к Амасии, царю Иудейскому, сказать: терн, который на Ливане, послал к кедру, который на Ливане же, сказать: «отдай дочь свою в жену сыну моему». Но прошли дикие двери, что на Ливане, и истоптали этот терн.', 'И послал Иоас, царь Израильский, к Амасии, царю Иудейскому, сказать: терн, который на Ливане, послал к кедру, который на Ливане же, сказать: «отдай дочь свою в жену сыну моему». Но прошли дикие звери, что на Ливане, и истоптали этот терн.');
INSERT INTO fix_verses VALUES ('B012C016V013', '12', 16, 13, 'И сожег всесожжение свое и хлебное приношение, и совершил возлияние свое, и окропил кровью мирной жертвы свой жертвенник.', 'И сожег всесожжение свое и хлебное приношение, и совершил возлияние свое, и окропил кровью мирной жертвы своей жертвенник.');
INSERT INTO fix_verses VALUES ('B012C017V029', '12', 17, 29, 'Притом сделал каждый народ и своих богов и поставил в капищах высот, какие устроили Самаряне,  — каждый народ в своих городах, где живут они.', 'Притом сделал каждый народ и своих богов и поставил в капищах высот, какие устроили Самаряне, — каждый народ в своих городах, где живут они.');
INSERT INTO fix_verses VALUES ('B012C017V036', '12', 17, 36, 'Но Господа, Который вывел вас из земли Египетской силою великою и мышцею простертою,  — Его чтите и Ему поклоняйтесь, и Ему приносите жертвы,', 'Но Господа, Который вывел вас из земли Египетской силою великою и мышцею простертою, — Его чтите и Ему поклоняйтесь, и Ему приносите жертвы,');
INSERT INTO fix_verses VALUES ('B012C019V011', '12', 19, 11, 'Ведь ты слышал, что сделали цари Ассирийские со всеми землями, положив на них заклятие,  — и ты ли уцелеешь?', 'Ведь ты слышал, что сделали цари Ассирийские со всеми землями, положив на них заклятие, — и ты ли уцелеешь?');
INSERT INTO fix_verses VALUES ('B012C021V013', '12', 21, 13, 'И протяну на Иерусалим мерную вервь Самарии и отвес дома Ахавова, и вытру Иерусалим так, как вытирают чашу,  — вытрут и опрокинут ее;', 'И протяну на Иерусалим мерную вервь Самарии и отвес дома Ахавова, и вытру Иерусалим так, как вытирают чашу, — вытрут и опрокинут ее;');
INSERT INTO fix_verses VALUES ('B012C022V014', '12', 22, 14, 'И пошел Хелкия священник, и Ахикам, и Ахбор, и Шафан, и Асаия к Олдаме пророчице, жене Шаллума, сына Тиквы, сына Хархаса, хранителя одежд,  — жила же она в Иерусалиме, во второй части,  — и говорили с нею.', 'И пошел Хелкия священник, и Ахикам, и Ахбор, и Шафан, и Асаия к Олдаме пророчице, жене Шаллума, сына Тиквы, сына Хархаса, хранителя одежд, — жила же она в Иерусалиме, во второй части, — и говорили с нею.');
INSERT INTO fix_verses VALUES ('B012C022V016', '12', 22, 16, 'Так говорит Господь: наведу зло на место сие и на жителей его,  — все слова книги, которую читал царь Иудейский.', 'Так говорит Господь: наведу зло на место сие и на жителей его, — все слова книги, которую читал царь Иудейский.');
INSERT INTO fix_verses VALUES ('B012C023V005', '12', 23, 5, 'И отставил жрецов, которых поставили цари Иудейские, чтобы совершать курения на высотах в городах Иудейских и окрестностях Иерусалима,  — и которые кадили Ваалу, солнцу, и луне, и созвездиям, и всему воинству небесному;', 'И отставил жрецов, которых поставили цари Иудейские, чтобы совершать курения на высотах в городах Иудейских и окрестностях Иерусалима, — и которые кадили Ваалу, солнцу, и луне, и созвездиям, и всему воинству небесному;');
INSERT INTO fix_verses VALUES ('B012C023V008', '12', 23, 8, 'И вывел всех жрецов из городов Иудейских, и осквернил высоты, на которых совершали курения жрецы, от Гевы до Вирсавии, и разрушил высоты [пред] воротами,  — ту, которая у входа в ворота Иисуса градоначальника, и ту, которая на левой стороне у городских ворот.', 'И вывел всех жрецов из городов Иудейских, и осквернил высоты, на которых совершали курения жрецы, от Гевы до Вирсавии, и разрушил высоты [пред] воротами, — ту, которая у входа в ворота Иисуса градоначальника, и ту, которая на левой стороне у городских ворот.');
INSERT INTO fix_verses VALUES ('B012C023V015', '12', 23, 15, 'Также и жертвенник, который в Вефиле, высоту, устроенную Иеровоамом, сыном Наватовым, который ввел Израиля в грех,  — также и жертвенник тот и высоту он разрушил, и сжег сию высоту, стер в прах, и сжег дубраву.', 'Также и жертвенник, который в Вефиле, высоту, устроенную Иеровоамом, сыном Наватовым, который ввел Израиля в грех, — также и жертвенник тот и высоту он разрушил, и сжег сию высоту, стер в прах, и сжег дубраву.');
INSERT INTO fix_verses VALUES ('B012C023V020', '12', 23, 20, 'И заколол всех жрецов высот, которые там были, на жертвенниках, и сожег кости человеческие на них,  — и возвратился в Иерусалим.', 'И заколол всех жрецов высот, которые там были, на жертвенниках, и сожег кости человеческие на них, — и возвратился в Иерусалим.');
INSERT INTO fix_verses VALUES ('B012C023V021', '12', 23, 21, 'И повелел царь всему народу, сказав: «совершите пасху Господу Богу вашему, как написано в сей книге завета»,  —', 'И повелел царь всему народу, сказав: «совершите пасху Господу Богу вашему, как написано в сей книге завета», —');
INSERT INTO fix_verses VALUES ('B012C023V033', '12', 23, 33, 'И задержал его фараон Нехао в Ривле, в земле Емафской, чтобы он не царствовал в Иерусалиме,  — и наложил пени на землю сто талантов серебра и талантов золота.', 'И задержал его фараон Нехао в Ривле, в земле Емафской, чтобы он не царствовал в Иерусалиме, — и наложил пени на землю сто талантов серебра и талантов золота.');
INSERT INTO fix_verses VALUES ('B012C024V002', '12', 24, 2, 'И посылал на него Господь полчища Халдеев, и полчища Сириян, и полчища Моавитян, и полчища Аммонитян,  — посылал их на Иуду, чтобы погубить его по слову Господа, которое Он изрек чрез рабов Своих пророков.', 'И посылал на него Господь полчища Халдеев, и полчища Сириян, и полчища Моавитян, и полчища Аммонитян, — посылал их на Иуду, чтобы погубить его по слову Господа, которое Он изрек чрез рабов Своих пророков.');
INSERT INTO fix_verses VALUES ('B012C024V012', '12', 24, 12, 'И вышел Иехония, царь Иудейский, к царю Вавилонскому, он и мать его, и слуги его, и князья его, и евнухи его,  — и взял его царь Вавилонский в восьмой год своего царствования.', 'И вышел Иехония, царь Иудейский, к царю Вавилонскому, он и мать его, и слуги его, и князья его, и евнухи его, — и взял его царь Вавилонский в восьмой год своего царствования.');
INSERT INTO fix_verses VALUES ('B012C024V014', '12', 24, 14, 'И выселил весь Иерусалим, и всех князей, и все храброе войско,  — десять тысяч было переселенных,  — и всех плотников и кузнецов; никого не осталось, кроме бедного народа земли.', 'И выселил весь Иерусалим, и всех князей, и все храброе войско, — десять тысяч было переселенных, — и всех плотников и кузнецов; никого не осталось, кроме бедного народа земли.');
INSERT INTO fix_verses VALUES ('B012C025V016', '12', 25, 16, 'Столбы [числом] два, море одно, и подставы, которые сделал Соломон в дом Господень,  — меди во всех сих вещах не было весу.', 'Столбы [числом] два, море одно, и подставы, которые сделал Соломон в дом Господень, — меди во всех сих вещах не было весу.');
INSERT INTO fix_verses VALUES ('B012C025V022', '12', 25, 22, 'Над народом же, остававшимся в земле Иудейской, который оставил Навуходоносор, царь Вавилонский,  — над ними поставил начальником Годолию, сына Ахикама, сына Шафанова.', 'Над народом же, остававшимся в земле Иудейской, который оставил Навуходоносор, царь Вавилонский, — над ними поставил начальником Годолию, сына Ахикама, сына Шафанова.');
INSERT INTO fix_verses VALUES ('B013C002V003', '13', 2, 3, 'Сыновья Иуды: Ир, Онан и Силом,  — трое родились у него от дочери Шуевой, Хананеянки. И был Ир, первенец Иудин, не благоугоден в очах Господа, и Он умертвил его.', 'Сыновья Иуды: Ир, Онан и Силом, — трое родились у него от дочери Шуевой, Хананеянки. И был Ир, первенец Иудин, не благоугоден в очах Господа, и Он умертвил его.');
INSERT INTO fix_verses VALUES ('B013C002V023', '13', 2, 23, 'Но Гессуряне и Сирияне взяли у них селения Иаира, Кенаф и зависящие от него города,  — шестьдесят городов. Все эти города сыновей Махира, отца Галаадова.', 'Но Гессуряне и Сирияне взяли у них селения Иаира, Кенаф и зависящие от него города, — шестьдесят городов. Все эти города сыновей Махира, отца Галаадова.');
INSERT INTO fix_verses VALUES ('B013C002V042', '13', 2, 42, 'Сыновья Халева, брата Иерахмеилова: Меша, первенец его,  — он отец Зифа; и сыновья Мареши, отца Хеврона.', 'Сыновья Халева, брата Иерахмеилова: Меша, первенец его, — он отец Зифа; и сыновья Мареши, отца Хеврона.');
INSERT INTO fix_verses VALUES ('B013C003V003', '13', 3, 3, 'Пятый — Сафатия, от Авиталы; шестой — Ифреам, от Аглаи, жены его,  —', 'Пятый — Сафатия, от Авиталы; шестой — Ифреам, от Аглаи, жены его, —');
INSERT INTO fix_verses VALUES ('B013C004V032', '13', 4, 32, 'С селами их: Етам, Аин, Риммон, Фокен и Ашан,  — пять городов.', 'С селами их: Етам, Аин, Риммон, Фокен и Ашан, — пять городов.');
INSERT INTO fix_verses VALUES ('B013C005V001', '13', 5, 1, 'Сыновья Рувима, первенца Израилева,  — он первенец; но, когда осквернил он постель отца своего, первенство его отдано сыновьям Иосифа, сына Израилева, с тем однакож, чтобы не писаться им первородными;', 'Сыновья Рувима, первенца Израилева, — он первенец; но, когда осквернил он постель отца своего, первенство его отдано сыновьям Иосифа, сына Израилева, с тем однакож, чтобы не писаться им первородными;');
INSERT INTO fix_verses VALUES ('B013C005V026', '13', 5, 26, 'Тогда Бог Израилев возбудил дух Фула, царя Ассирийского, и дух Феглафелласара, царя Ассирийского, и он выселил Рувимлян и Гадитян и половину колена Манассиина, и отвел их в Халах, и Хавор, и Ару, и на реку Гозан,  — [где они] до сего дня.', 'Тогда Бог Израилев возбудил дух Фула, царя Ассирийского, и дух Феглафелласара, царя Ассирийского, и он выселил Рувимлян и Гадитян и половину колена Манассиина, и отвел их в Халах, и Хавор, и Ару, и на реку Гозан, — [где они] до сего дня.');
INSERT INTO fix_verses VALUES ('B013C006V010', '13', 6, 10, 'Иоанан родил Азарию,  — это тот, который был священником в храме, построенном Соломоном в Иерусалиме.', 'Иоанан родил Азарию, — это тот, который был священником в храме, построенном Соломоном в Иерусалиме.');
INSERT INTO fix_verses VALUES ('B013C006V039', '13', 6, 39, 'И брат его Асаф, стоявший на правой стороне его,  — Асаф, сын Берехии, сын Шимы,', 'И брат его Асаф, стоявший на правой стороне его, — Асаф, сын Берехии, сын Шимы,');
INSERT INTO fix_verses VALUES ('B013C006V044', '13', 6, 44, 'А из сыновей Мерари, братьев их,  — на левой стороне: Ефан, сын Кишия, сын Авдия, сын Маллуха,', 'А из сыновей Мерари, братьев их, — на левой стороне: Ефан, сын Кишия, сын Авдия, сын Маллуха,');
INSERT INTO fix_verses VALUES ('B013C007V015', '13', 7, 15, 'Махир взял в жену сестру Хупима и Шупима,  — имя сестры их Мааха; имя второму Салпаад. У Салпаада были [только] дочери.', 'Махир взял в жену сестру Хупима и Шупима, — имя сестры их Мааха; имя второму Салпаад. У Салпаада были [только] дочери.');
INSERT INTO fix_verses VALUES ('B013C008V012', '13', 8, 12, 'Сыновья Елпаала: Евер, Мишам и Шемер, который построил Оно и Лод и зависящие от него города,  —', 'Сыновья Елпаала: Евер, Мишам и Шемер, который построил Оно и Лод и зависящие от него города, —');
INSERT INTO fix_verses VALUES ('B013C008V029', '13', 8, 29, 'В Гаваоне жили: отец Гаваонитян,  — имя жены его Мааха,  —', 'В Гаваоне жили: отец Гаваонитян, — имя жены его Мааха, —');
INSERT INTO fix_verses VALUES ('B013C009V004', '13', 9, 4, 'Уфай, сын Аммиуда, сын Омри, сын Имрия, сын Вания,  — из сыновей Фареса, сына Иудина;', 'Уфай, сын Аммиуда, сын Омри, сын Имрия, сын Вания, — из сыновей Фареса, сына Иудина;');
INSERT INTO fix_verses VALUES ('B013C009V006', '13', 9, 6, 'Из сыновей Зары — Иеуил и братья их,  — шестьсот девяносто;', 'Из сыновей Зары — Иеуил и братья их, — шестьсот девяносто;');
INSERT INTO fix_verses VALUES ('B013C009V009', '13', 9, 9, 'И братья их, по родам их: девятьсот пятьдесят шесть,  — все сии мужи были главы родов в поколениях своих.', 'И братья их, по родам их: девятьсот пятьдесят шесть, — все сии мужи были главы родов в поколениях своих.');
INSERT INTO fix_verses VALUES ('B013C009V013', '13', 9, 13, 'И братья их, главы родов своих: тысяча семьсот шестьдесят,  — люди отличные в деле служения в доме Божием.', 'И братья их, главы родов своих: тысяча семьсот шестьдесят, — люди отличные в деле служения в доме Божием.');
INSERT INTO fix_verses VALUES ('B013C009V014', '13', 9, 14, 'А из левитов: Шемаия, сын Хашува, сын Азрикама, сын Хашавии,  — из сыновей Мерариных;', 'А из левитов: Шемаия, сын Хашува, сын Азрикама, сын Хашавии, — из сыновей Мерариных;');
INSERT INTO fix_verses VALUES ('B013C009V031', '13', 9, 31, 'Маттафии из левитов,  — он первенец Селлума Кореянина,  — вверено было приготовляемое на сковородах.', 'Маттафии из левитов, — он первенец Селлума Кореянина, — вверено было приготовляемое на сковородах.');
INSERT INTO fix_verses VALUES ('B013C009V035', '13', 9, 35, 'В Гаваоне жили: отец Гаваонитян Иеил,  — имя жены его Мааха,', 'В Гаваоне жили: отец Гаваонитян Иеил, — имя жены его Мааха,');
INSERT INTO fix_verses VALUES ('B013C012V002', '13', 12, 2, 'Вооруженные луком, правою и левою рукою [бросавшие] каменья и [стрелявшие] стрелами из лука,  — из братьев Саула, от Вениамина:', 'Вооруженные луком, правою и левою рукою [бросавшие] каменья и [стрелявшие] стрелами из лука, — из братьев Саула, от Вениамина:');
INSERT INTO fix_verses VALUES ('B013C012V029', '13', 12, 29, 'Из сыновей Вениаминовых, братьев Сауловых, три тысячи,  — но еще многие из них держались дома Саулова;', 'Из сыновей Вениаминовых, братьев Сауловых, три тысячи, — но еще многие из них держались дома Саулова;');
INSERT INTO fix_verses VALUES ('B013C012V032', '13', 12, 32, 'Из сынов Иссахаровых [пришли] люди разумные, которые знали, что когда надлежало делать Израилю,  — их было двести главных, и все братья их следовали слову их;', 'Из сынов Иссахаровых [пришли] люди разумные, которые знали, что когда надлежало делать Израилю, — их было двести главных, и все братья их следовали слову их;');
INSERT INTO fix_verses VALUES ('B013C015V024', '13', 15, 24, 'Шевания, Иосафат, Нафанаил, Амасай, Захария, Ванея и Елиезер, священники, трубили трубами пред ковчегом Божиим. Овед — Едом и Иехия [были] придверниками у ковчега.', 'Шевания, Иосафат, Нафанаил, Амасай, Захария, Ванея и Елиезер, священники, трубили трубами пред ковчегом Божиим. Овед-Едом и Иехия [были] придверниками у ковчега.');
INSERT INTO fix_verses VALUES ('B013C017V013', '13', 17, 13, 'Я буду ему отцом, и он будет Мне сыном,  — и милости Моей не отниму от него, как Я отнял от того, который был прежде тебя.', 'Я буду ему отцом, и он будет Мне сыном, — и милости Моей не отниму от него, как Я отнял от того, который был прежде тебя.');
INSERT INTO fix_verses VALUES ('B013C018V002', '13', 18, 2, 'Он поразил также Моавитян,  — и сделались Моавитяне рабами Давида, принося ему дань.', 'Он поразил также Моавитян, — и сделались Моавитяне рабами Давида, принося ему дань.');
INSERT INTO fix_verses VALUES ('B013C018V010', '13', 18, 10, 'И послал Иорама, сына своего, к царю Давиду, приветствовать его и благодарить за то, что он воевал с Адраазаром и поразил его, ибо Фой был в войне с Адраазаром,  — и [с ним] всякие сосуды золотые, серебряные и медные.', 'И послал Иорама, сына своего, к царю Давиду, приветствовать его и благодарить за то, что он воевал с Адраазаром и поразил его, ибо Фой был в войне с Адраазаром, — и [с ним] всякие сосуды золотые, серебряные и медные.');
INSERT INTO fix_verses VALUES ('B013C019V013', '13', 19, 13, 'Будь мужествен, и будем твердо стоять за народ наш и за города Бога нашего,  — и Господь пусть сделает, что ему угодно.', 'Будь мужествен, и будем твердо стоять за народ наш и за города Бога нашего, — и Господь пусть сделает, что ему угодно.');
INSERT INTO fix_verses VALUES ('B013C021V010', '13', 21, 10, 'Пойди и скажи Давиду: так говорит Господь: три [наказания] Я предлагаю тебе, избери себе одно из них,  — и Я пошлю его на тебя.', 'Пойди и скажи Давиду: так говорит Господь: три [наказания] Я предлагаю тебе, избери себе одно из них, — и Я пошлю его на тебя.');
INSERT INTO fix_verses VALUES ('B013C023V031', '13', 23, 31, 'И при всех всесожжениях, возносимых Господу в субботы, в новомесячия и в праздники по числу, как предписано о них,  — постоянно пред лицем Господа,', 'И при всех всесожжениях, возносимых Господу в субботы, в новомесячия и в праздники по числу, как предписано о них, — постоянно пред лицем Господа,');
INSERT INTO fix_verses VALUES ('B013C026V010', '13', 26, 10, 'У Хосы, из сыновей Мерариных, сыновья: Шимри главный,  — хотя он не был первенцем, но отец его поставил его главным;', 'У Хосы, из сыновей Мерариных, сыновья: Шимри главный, — хотя он не был первенцем, но отец его поставил его главным;');
INSERT INTO fix_verses VALUES ('B013C027V016', '13', 27, 16, 'А над коленами Израилевыми,  — у Рувимлян главным начальником [был] Елиезер, сын Зихри; у Симеона — Сафатия, сын Маахи;', 'А над коленами Израилевыми, — у Рувимлян главным начальником [был] Елиезер, сын Зихри; у Симеона — Сафатия, сын Маахи;');
INSERT INTO fix_verses VALUES ('B013C028V005', '13', 28, 5, 'Из всех же сыновей моих,  — ибо много сыновей дал мне Господь,  — Он избрал Соломона, сына моего, сидеть на престоле царства Господня над Израилем,', 'Из всех же сыновей моих, — ибо много сыновей дал мне Господь, — Он избрал Соломона, сына моего, сидеть на престоле царства Господня над Израилем,');
INSERT INTO fix_verses VALUES ('B013C028V021', '13', 28, 21, 'И вот отделы священников и левитов, для всякой службы при Доме Божием. И у тебя есть для всякого дела усердные люди, искусные для всякой работы, и начальники и весь народ [готовы] на все твои приказания.', 'И вот отделы священников и левитов, для всякой службы при доме Божием. И у тебя есть для всякого дела усердные люди, искусные для всякой работы, и начальники и весь народ [готовы] на все твои приказания.');
INSERT INTO fix_verses VALUES ('B013C029V020', '13', 29, 20, 'И сказал Давид всему собранию: благословите Господа Бога нашего.  — И благословило все собрание Господа Бога отцов своих, и пало, и поклонилось Господу и царю.', 'И сказал Давид всему собранию: благословите Господа Бога нашего. — И благословило все собрание Господа Бога отцов своих, и пало, и поклонилось Господу и царю.');
INSERT INTO fix_verses VALUES ('B014C002V014', '14', 2, 14, 'Сына [одной] женщины из дочерей Дановых,  — а отец его Тирянин,  — умеющего делать [изделия] из золота и из серебра, из меди, из железа, из камней и из дерев, из [пряжи] пурпурового, яхонтового [цвета], и из виссона, и из багряницы, и вырезывать всякую резьбу, и исполнять все, что будет поручено ему вместе с художниками твоими и с художниками господина моего Давида, отца твоего.', 'Сына [одной] женщины из дочерей Дановых, — а отец его Тирянин, — умеющего делать [изделия] из золота и из серебра, из меди, из железа, из камней и из дерев, из [пряжи] пурпурового, яхонтового [цвета], и из виссона, и из багряницы, и вырезывать всякую резьбу, и исполнять все, что будет поручено ему вместе с художниками твоими и с художниками господина моего Давида, отца твоего.');
INSERT INTO fix_verses VALUES ('B014C002V017', '14', 2, 17, 'И исчислил Соломон всех пришельцев, бывших [тогда] в земле Израилевой, после исчисления их, сделанного Давидом, отцом его,  — и нашлось их сто пятьдесят три тысячи шестьсот.', 'И исчислил Соломон всех пришельцев, бывших [тогда] в земле Израилевой, после исчисления их, сделанного Давидом, отцом его, — и нашлось их сто пятьдесят три тысячи шестьсот.');
INSERT INTO fix_verses VALUES ('B014C004V002', '14', 4, 2, 'И сделал море литое,  — от края его до края его десять локтей,  — все круглое, вышиною в пять локтей; и снурок в тридцать локтей обнимал его кругом;', 'И сделал море литое, — от края его до края его десять локтей, — все круглое, вышиною в пять локтей; и снурок в тридцать локтей обнимал его кругом;');
INSERT INTO fix_verses VALUES ('B014C004V004', '14', 4, 4, 'Стояло оно на двенадцати волах: три глядели к северу и три глядели к западу, и три глядели к югу, и три глядели к востоку,  — и море на них сверху; зады же их были обращены внутрь под него.', 'Стояло оно на двенадцати волах: три глядели к северу и три глядели к западу, и три глядели к югу, и три глядели к востоку, — и море на них сверху; зады же их были обращены внутрь под него.');
INSERT INTO fix_verses VALUES ('B014C004V006', '14', 4, 6, 'И сделал десять омывальниц, и поставил пять по правую сторону и пять по левую, чтоб омывать в них,  — приготовляемое ко всесожжению омывали в них; море же — для священников, чтоб они омывались в нем.', 'И сделал десять омывальниц, и поставил пять по правую сторону и пять по левую, чтоб омывать в них, — приготовляемое ко всесожжению омывали в них; море же — для священников, чтоб они омывались в нем.');
INSERT INTO fix_verses VALUES ('B014C004V022', '14', 4, 22, 'И ножи, и кропильницы, и чаши, и лотки из золота самого чистого, и двери храма,  — двери его внутренние во Святое Святых, и двери храма во святилище,  — из золота.', 'И ножи, и кропильницы, и чаши, и лотки из золота самого чистого, и двери храма, — двери его внутренние во Святое Святых, и двери храма во святилище, — из золота.');
INSERT INTO fix_verses VALUES ('B014C005V005', '14', 5, 5, 'И понесли ковчег и скинию собрания и все вещи священные, которые в скинии,  — понесли их священники и левиты.', 'И понесли ковчег и скинию собрания и все вещи священные, которые в скинии, — понесли их священники и левиты.');
INSERT INTO fix_verses VALUES ('B014C005V012', '14', 5, 12, 'И левиты певцы,  — все они, [то есть] Асаф, Еман, Идифун и сыновья их, и братья их,  — одетые в виссон, с кимвалами и с псалтирями и цитрами стояли на восточной стороне жертвенника, и с ними сто двадцать священников, трубивших трубами,', 'И левиты певцы, — все они, [то есть] Асаф, Еман, Идифун и сыновья их, и братья их, — одетые в виссон, с кимвалами и с псалтирями и цитрами стояли на восточной стороне жертвенника, и с ними сто двадцать священников, трубивших трубами,');
INSERT INTO fix_verses VALUES ('B014C006V003', '14', 6, 3, 'И обратился царь лицем своим и благословил все собрание Израильтян,  — все собрание Израильтян стояло,  —', 'И обратился царь лицем своим и благословил все собрание Израильтян, — все собрание Израильтян стояло, —');
INSERT INTO fix_verses VALUES ('B014C006V009', '14', 6, 9, 'Однако не ты построишь храм, а сын твой, который произойдет из чресл твоих,  — он построит храм имени Моему».', 'Однако не ты построишь храм, а сын твой, который произойдет из чресл твоих, — он построит храм имени Моему».');
INSERT INTO fix_verses VALUES ('B014C006V012', '14', 6, 12, 'И стал [Соломон] у жертвенника Господня впереди всего собрания Израильтян, и воздвиг руки свои,  —', 'И стал [Соломон] у жертвенника Господня впереди всего собрания Израильтян, и воздвиг руки свои, —');
INSERT INTO fix_verses VALUES ('B014C006V013', '14', 6, 13, 'Ибо Соломон сделал медный амвон длиною в пять локтей и шириною в пять локтей, а вышиною в три локтя, и поставил его среди двора; и стал на нем, и преклонил колени впереди всего собрания Израильтян, и воздвиг руки свои к небу,  —', 'Ибо Соломон сделал медный амвон длиною в пять локтей и шириною в пять локтей, а вышиною в три локтя, и поставил его среди двора; и стал на нем, и преклонил колени впереди всего собрания Израильтян, и воздвиг руки свои к небу, —');
INSERT INTO fix_verses VALUES ('B014C006V029', '14', 6, 29, 'Всякую молитву, всякое прошение, какое будет от какого — либо человека или от всего народа Твоего Израиля, когда они почувствуют каждый бедствие свое и горе свое и прострут руки свои к храму сему,', 'Всякую молитву, всякое прошение, какое будет от какого-либо человека или от всего народа Твоего Израиля, когда они почувствуют каждый бедствие свое и горе свое и прострут руки свои к храму сему,');
INSERT INTO fix_verses VALUES ('B014C006V030', '14', 6, 30, 'Ты услышь с неба — места обитания Твоего, и прости, и воздай каждому по всем путям его, как Ты знаешь сердце его,  — ибо Ты один знаешь сердце сынов человеческих,  —', 'Ты услышь с неба — места обитания Твоего, и прости, и воздай каждому по всем путям его, как Ты знаешь сердце его, — ибо Ты один знаешь сердце сынов человеческих, —');
INSERT INTO fix_verses VALUES ('B014C006V036', '14', 6, 36, 'Когда они согрешат пред Тобою,  — ибо нет человека, который не согрешил бы,  — и Ты прогневаешься на них, и предашь их врагу, и отведут их пленившие их в землю далекую или близкую,', 'Когда они согрешат пред Тобою, — ибо нет человека, который не согрешил бы, — и Ты прогневаешься на них, и предашь их врагу, и отведут их пленившие их в землю далекую или близкую,');
INSERT INTO fix_verses VALUES ('B014C006V038', '14', 6, 38, 'И обратятся к Тебе всем сердцем своим и всею душею своею в земле пленения своего, куда отведут их в плен, и будут молиться, обратившись к земле своей, которую Ты дал отцам их, и к городу, который избрал Ты, и к храму, который я построил имени Твоему,  —', 'И обратятся к Тебе всем сердцем своим и всею душею своею в земле пленения своего, куда отведут их в плен, и будут молиться, обратившись к земле своей, которую Ты дал отцам их, и к городу, который избрал Ты, и к храму, который я построил имени Твоему, —');
INSERT INTO fix_verses VALUES ('B014C007V022', '14', 7, 22, 'И скажут: за то, что они оставили Господа, Бога отцов своих, Который вывел их из земли Египетской, и прилепились к богам иным, и поклонялись им, и служили им,  — за то Он навел на них все это бедствие.', 'И скажут: за то, что они оставили Господа, Бога отцов своих, Который вывел их из земли Египетской, и прилепились к богам иным, и поклонялись им, и служили им, — за то Он навел на них все это бедствие.');
INSERT INTO fix_verses VALUES ('B014C008V007', '14', 8, 7, 'Весь народ, оставшийся от Хеттеев, и Аморреев, и Ферезеев, и Евеев и Иевусеев, которые были не из сынов Израилевых,  —', 'Весь народ, оставшийся от Хеттеев, и Аморреев, и Ферезеев, и Евеев и Иевусеев, которые были не из сынов Израилевых, —');
INSERT INTO fix_verses VALUES ('B014C008V008', '14', 8, 8, 'Детей их, оставшихся после них на земле, которых не истребили сыны Израилевы,  — сделал Соломон оброчными до сего дня.', 'Детей их, оставшихся после них на земле, которых не истребили сыны Израилевы, — сделал Соломон оброчными до сего дня.');
INSERT INTO fix_verses VALUES ('B014C008V011', '14', 8, 11, 'А дочь Фараонову перевел Соломон из города Давидова в дом, который построил для нее, потому что, говорил он, не должна жить женщина у меня в доме Давида, царя Израилева, ибо свят он, так как вошел в него ковчег Господень.', 'А дочь фараонову перевел Соломон из города Давидова в дом, который построил для нее, потому что, говорил он, не должна жить женщина у меня в доме Давида, царя Израилева, ибо свят он, так как вошел в него ковчег Господень.');
INSERT INTO fix_verses VALUES ('B014C009V004', '14', 9, 4, 'И пищу за столом его, и жилище рабов его, и чинность служащих ему и одежду их, и виночерпиев его и одежду их, и ход, которым он ходил в дом Господень,  — и была она вне себя.', 'И пищу за столом его, и жилище рабов его, и чинность служащих ему и одежду их, и виночерпиев его и одежду их, и ход, которым он ходил в дом Господень, — и была она вне себя.');
INSERT INTO fix_verses VALUES ('B014C009V015', '14', 9, 15, 'И сделал царь Соломон двести больших щитов из кованого золота,  — по шестисот [сиклей] кованого золота пошло на каждый щит,  —', 'И сделал царь Соломон двести больших щитов из кованого золота, — по шестисот [сиклей] кованого золота пошло на каждый щит, —');
INSERT INTO fix_verses VALUES ('B014C009V016', '14', 9, 16, 'И триста щитов меньших из кованого золота,  — по триста [сиклей] золота пошло на каждый щит; и поставил их царь в доме из Ливанского дерева.', 'И триста щитов меньших из кованого золота, — по триста [сиклей] золота пошло на каждый щит; и поставил их царь в доме из Ливанского дерева.');
INSERT INTO fix_verses VALUES ('B014C010V002', '14', 10, 2, 'Когда услышал [о сем] Иеровоам, сын Наватов,  — он находился в Египте, куда убежал от царя Соломона,  — то возвратился Иеровоам из Египта.', 'Когда услышал [о сем] Иеровоам, сын Наватов, — он находился в Египте, куда убежал от царя Соломона, — то возвратился Иеровоам из Египта.');
INSERT INTO fix_verses VALUES ('B014C010V010', '14', 10, 10, 'И говорили ему молодые люди, выросшие вместе с ним, и сказали: так скажи народу, говорившему тебе: отец твой наложил на нас тяжкое иго, а ты облегчи нас,  — так скажи им: мизинец мой толще чресл отца моего.', 'И говорили ему молодые люди, выросшие вместе с ним, и сказали: так скажи народу, говорившему тебе: отец твой наложил на нас тяжкое иго, а ты облегчи нас, — так скажи им: мизинец мой толще чресл отца моего.');
INSERT INTO fix_verses VALUES ('B014C011V014', '14', 11, 14, 'Ибо оставили левиты свои городские предместья и свои владения и пришли в Иудею и в Иерусалим, так как оставил их Иеровоам и сыновья его от священства Господня', 'Ибо оставили левиты свои городские предместья и свои владения и пришли в Иудею и в Иерусалим, так как отставил их Иеровоам и сыновья его от священства Господня');
INSERT INTO fix_verses VALUES ('B014C012V002', '14', 12, 2, 'На пятом году царствования Ровоама, Сусаким, царь Египетский, пошел на Иерусалим,  — потому что они отступили от Господа,  —', 'На пятом году царствования Ровоама, Сусаким, царь Египетский, пошел на Иерусалим, — потому что они отступили от Господа, —');
INSERT INTO fix_verses VALUES ('B014C014V007', '14', 14, 7, 'И сказал он Иудеям: построим города сии и обнесем их стенами с башнями, с воротами и запорами. Земля еще наша, потому что мы взыскали Господа Бога нашего: мы взыскали Его,  — и Он дал нам покой со всех сторон. И стали строить, и имели успех.', 'И сказал он Иудеям: построим города сии и обнесем их стенами с башнями, с воротами и запорами. Земля еще наша, потому что мы взыскали Господа Бога нашего: мы взыскали Его, — и Он дал нам покой со всех сторон. И стали строить, и имели успех.');
INSERT INTO fix_verses VALUES ('B014C016V006', '14', 16, 6, 'Аса же царь собрал всех Иудеев, и они вывезли [из] Рамы камни и дерева, которые употреблял Вааса для строения,  — и выстроил из них Геву и Мицфу.', 'Аса же царь собрал всех Иудеев, и они вывезли [из] Рамы камни и дерева, которые употреблял Вааса для строения, — и выстроил из них Геву и Мицфу.');
INSERT INTO fix_verses VALUES ('B014C018V013', '14', 18, 13, 'И сказал Михей: жив Господь,  — что скажет мне Бог мой, то изреку я.', 'И сказал Михей: жив Господь, — что скажет мне Бог мой, то изреку я.');
INSERT INTO fix_verses VALUES ('B014C018V016', '14', 18, 16, 'Тогда [Михей] сказал: я видел всех сынов Израиля, рассеянных по горам, как овец, у которых нет пастыря,  — и сказал Господь: нет у них начальника, пусть возвратятся каждый в дом свой с миром.', 'Тогда [Михей] сказал: я видел всех сынов Израиля, рассеянных по горам, как овец, у которых нет пастыря, — и сказал Господь: нет у них начальника, пусть возвратятся каждый в дом свой с миром.');
INSERT INTO fix_verses VALUES ('B014C018V031', '14', 18, 31, 'И когда увидели Иосафата начальники колесниц, то подумали: это царь Израильский,  — и окружили его, чтобы сразиться с ним. Но Иосафат закричал, и Господь помог ему, и отвел их Бог от него.', 'И когда увидели Иосафата начальники колесниц, то подумали: это царь Израильский, — и окружили его, чтобы сразиться с ним. Но Иосафат закричал, и Господь помог ему, и отвел их Бог от него.');
INSERT INTO fix_verses VALUES ('B014C019V010', '14', 19, 10, 'Во всяком деле спорном, какое поступит к вам от братьев ваших, живущих в городах своих, о кровопролитии ли, или о законе, заповеди, уставах и обрядах, наставляйте их, чтобы они не провинились пред Господом, и не было бы гнева [Его] на вас и на братьев ваших; так действуйте,  — и вы не погрешите.', 'Во всяком деле спорном, какое поступит к вам от братьев ваших, живущих в городах своих, о кровопролитии ли, или о законе, заповеди, уставах и обрядах, наставляйте их, чтобы они не провинились пред Господом, и не было бы гнева [Его] на вас и на братьев ваших; так действуйте, — и вы не погрешите.');
INSERT INTO fix_verses VALUES ('B014C020V010', '14', 20, 10, 'И ныне вот Аммонитяне и Моавитяне и [обитатели] горы Сеира, чрез земли которых Ты не позволил пройти Израильтянам, когда они шли из земли Египетской, а потому они миновали их и не истребили их,  —', 'И ныне вот Аммонитяне и Моавитяне и [обитатели] горы Сеира, чрез земли которых Ты не позволил пройти Израильтянам, когда они шли из земли Египетской, а потому они миновали их и не истребили их, —');
INSERT INTO fix_verses VALUES ('B014C020V037', '14', 20, 37, 'И изрек [тогда] Елиезер, сын Додавы из Мареши, пророчество на Иосафата, говоря: так как ты вступил в общение с Охозиею, то разрушил Господь дело твое.  — И разбились корабли, и не могли идти в Фарсис.', 'И изрек [тогда] Елиезер, сын Додавы из Мареши, пророчество на Иосафата, говоря: так как ты вступил в общение с Охозиею, то разрушил Господь дело твое. — И разбились корабли, и не могли идти в Фарсис.');
INSERT INTO fix_verses VALUES ('B014C021V006', '14', 21, 6, 'И ходил он путем царей Израильских, как поступал дом Ахавов, потому что дочь Ахава была женою его,  — и делал он неугодное в очах Господних.', 'И ходил он путем царей Израильских, как поступал дом Ахавов, потому что дочь Ахава была женою его, — и делал он неугодное в очах Господних.');
INSERT INTO fix_verses VALUES ('B014C021V015', '14', 21, 15, 'Тебя же [самого]  — болезнью сильною, болезнью внутренностей твоих до того, что будут выпадать внутренности твои от болезни со дня на день.', 'Тебя же [самого] — болезнью сильною, болезнью внутренностей твоих до того, что будут выпадать внутренности твои от болезни со дня на день.');
INSERT INTO fix_verses VALUES ('B014C022V001', '14', 22, 1, 'И поставили царем жители Иерусалима Охозию, меньшего сына его, вместо него, так как всех старших избило полчище, приходившее с Аравитянами к стану,  — и воцарился Охозия, сын Иорама, царя Иудейского.', 'И поставили царем жители Иерусалима Охозию, меньшего сына его, вместо него, так как всех старших избило полчище, приходившее с Аравитянами к стану, — и воцарился Охозия, сын Иорама, царя Иудейского.');
INSERT INTO fix_verses VALUES ('B014C022V008', '14', 22, 8, 'Когда совершал Ииуй суд над домом Ахава, тогда он нашел князей Иудийских и сыновей братьев Охозии, служивших Охозии, и умертвил их.', 'Когда совершал Ииуй суд над домом Ахава, тогда он нашел князей Иудейских и сыновей братьев Охозии, служивших Охозии, и умертвил их.');
INSERT INTO fix_verses VALUES ('B014C024V018', '14', 24, 18, 'И оставили дом Господа Бога отцов своих и стали служить деревам [посвященным] и идолам,  — и был гнев [Господень] на Иуду и Иерусалим за сию вину их.', 'И оставили дом Господа Бога отцов своих и стали служить деревам [посвященным] и идолам, — и был гнев [Господень] на Иуду и Иерусалим за сию вину их.');
INSERT INTO fix_verses VALUES ('B014C025V010', '14', 25, 10, 'И отделил их Амасия,  — войско, пришедшее к нему из [земли] Ефремовой,  — чтоб они шли в свое место. И возгорелся сильно гнев их на Иудею, и они пошли назад в свое место, в пылу гнева.', 'И отделил их Амасия, — войско, пришедшее к нему из [земли] Ефремовой, — чтоб они шли в свое место. И возгорелся сильно гнев их на Иудею, и они пошли назад в свое место, в пылу гнева.');
INSERT INTO fix_verses VALUES ('B014C025V019', '14', 25, 19, 'Ты говоришь: вот я побил Идумеян,  — и вознеслось сердце твое до тщеславия. Сиди лучше у себя дома. К чему тебе затевать опасное дело? Падешь ты и Иудея с тобою.', 'Ты говоришь: вот я побил Идумеян, — и вознеслось сердце твое до тщеславия. Сиди лучше у себя дома. К чему тебе затевать опасное дело? Падешь ты и Иудея с тобою.');
INSERT INTO fix_verses VALUES ('B014C026V019', '14', 26, 19, 'И разгневался Озия,  — а в руке у него кадильница для каждения; и когда разгневался он на священников, проказа явилась на челе его, пред лицем священников, в доме Господнем, у алтаря кадильного.', 'И разгневался Озия, — а в руке у него кадильница для каждения; и когда разгневался он на священников, проказа явилась на челе его, пред лицем священников, в доме Господнем, у алтаря кадильного.');
INSERT INTO fix_verses VALUES ('B014C028V015', '14', 28, 15, 'И встали мужи, упомянутые по именам, и взяли пленных, и всех нагих из них одели из добычи,  — и одели их, и обули их, и накормили их, и напоили их, и помазали их елеем, и посадили на ослов всех слабых из них, и отправили их в Иерихон, город пальм, к братьям их, и возвратились в Самарию.', 'И встали мужи, упомянутые по именам, и взяли пленных, и всех нагих из них одели из добычи, — и одели их, и обули их, и накормили их, и напоили их, и помазали их елеем, и посадили на ослов всех слабых из них, и отправили их в Иерихон, город пальм, к братьям их, и возвратились в Самарию.');
INSERT INTO fix_verses VALUES ('B014C029V031', '14', 29, 31, 'И продолжал Езекия и сказал: теперь вы посвятили себя Господу; приступайте и приносите жертвы и благодарственные приношения в дом Господень. И понесло [все] собрание жертвы и благодарственные приношения, и всякий, кто расположен был сердцем,  — всесожжения.', 'И продолжал Езекия и сказал: теперь вы посвятили себя Господу; приступайте и приносите жертвы и благодарственные приношения в дом Господень. И понесло [все] собрание жертвы и благодарственные приношения, и всякий, кто расположен был сердцем, — всесожжения.');
INSERT INTO fix_verses VALUES ('B014C030V013', '14', 30, 13, 'И собралось в Иерусалим множество народа для совершения праздника опресноков, во второй месяц,  — собрание весьма многочисленное.', 'И собралось в Иерусалим множество народа для совершения праздника опресноков, во второй месяц, — собрание весьма многочисленное.');
INSERT INTO fix_verses VALUES ('B014C031V018', '14', 31, 18, 'И внесенным в список, со всеми малолетними их, с женами их и с сыновьями их и с дочерями их,  — всему обществу, ибо они со [всею] верностью посвятили себя на священную службу.', 'И внесенным в список, со всеми малолетними их, с женами их и с сыновьями их и с дочерями их, — всему обществу, ибо они со [всею] верностью посвятили себя на священную службу.');
INSERT INTO fix_verses VALUES ('B014C031V020', '14', 31, 20, 'Вот что сделал Езекия во всей Иудее,  — и он делал доброе, и справедливое, и истинное пред лицем Господа Бога своего.', 'Вот что сделал Езекия во всей Иудее, — и он делал доброе, и справедливое, и истинное пред лицем Господа Бога своего.');
INSERT INTO fix_verses VALUES ('B014C032V009', '14', 32, 9, 'После сего послал Сеннахирим, царь Ассирийский, рабов своих в Иерусалим,  — сам он [стоял] против Лахиса, и вся сила его с ним,  — к Езекии, царю Иудейскому, и ко всем Иудеям, которые в Иерусалиме, сказать:', 'После сего послал Сеннахирим, царь Ассирийский, рабов своих в Иерусалим, — сам он [стоял] против Лахиса, и вся сила его с ним, — к Езекии, царю Иудейскому, и ко всем Иудеям, которые в Иерусалиме, сказать:');
INSERT INTO fix_verses VALUES ('B014C032V019', '14', 32, 19, 'И говорили о Боге Иерусалима, как о богах народов земли,  — изделии рук человеческих.', 'И говорили о Боге Иерусалима, как о богах народов земли, — изделии рук человеческих.');
INSERT INTO fix_verses VALUES ('B014C032V021', '14', 32, 21, 'И послал Господь Ангела, и он истребил всех храбрых и главноначальствующего и начальствующих в войске царя Ассирийского. И возвратился он со стыдом в землю свою; и когда пришел в дом бога своего,  — исшедшие из чресл его поразили его там мечом.', 'И послал Господь Ангела, и он истребил всех храбрых и главноначальствующего и начальствующих в войске царя Ассирийского. И возвратился он со стыдом в землю свою; и когда пришел в дом бога своего, — исшедшие из чресл его поразили его там мечом.');
INSERT INTO fix_verses VALUES ('B014C032V026', '14', 32, 26, 'Но как смирился Езекия в гордости сердца своего,  — сам и жители Иерусалима, то не пришел на них гнев Господень во дни Езекии.', 'Но как смирился Езекия в гордости сердца своего, — сам и жители Иерусалима, то не пришел на них гнев Господень во дни Езекии.');
INSERT INTO fix_verses VALUES ('B014C034V022', '14', 34, 22, 'И пошел Хелкия и те, которые от царя, к Олдане пророчице, жене Шаллума, сына Тавкегафа, сына Хасры, хранителя одежд,  — а жила она во второй части Иерусалима,  — и говорили с нею об этом.', 'И пошел Хелкия и те, которые от царя, к Олдане пророчице, жене Шаллума, сына Тавкегафа, сына Хасры, хранителя одежд, — а жила она во второй части Иерусалима, — и говорили с нею об этом.');
INSERT INTO fix_verses VALUES ('B014C034V027', '14', 34, 27, 'Так как смягчилось сердце твое, и ты смирился пред Богом, услышав слова Его о месте сем и о жителях его,  — и ты смирился предо Мною, и разодрал одежды свои, и плакал предо Мною, то и Я услышал [тебя], говорит Господь.', 'Так как смягчилось сердце твое, и ты смирился пред Богом, услышав слова Его о месте сем и о жителях его, — и ты смирился предо Мною, и разодрал одежды свои, и плакал предо Мною, то и Я услышал [тебя], говорит Господь.');
INSERT INTO fix_verses VALUES ('B014C036V013', '14', 36, 13, 'И отложился от царя Навуходоносора, взявшего клятву с него [именем] Бога,  — и сделал упругою шею свою и ожесточил сердце свое до того, что не обратился к Господу Богу Израилеву.', 'И отложился от царя Навуходоносора, взявшего клятву с него [именем] Бога, — и сделал упругою шею свою и ожесточил сердце свое до того, что не обратился к Господу Богу Израилеву.');
INSERT INTO fix_verses VALUES ('B014C036V017', '14', 36, 17, 'И Он навел на них царя Халдейского,  — и тот умертвил юношей их мечом в доме святыни их и не пощадил ни юноши, ни девицы, ни старца, ни седовласого: все предал [Бог] в руку его.', 'И Он навел на них царя Халдейского, — и тот умертвил юношей их мечом в доме святыни их и не пощадил ни юноши, ни девицы, ни старца, ни седовласого: все предал [Бог] в руку его.');
INSERT INTO fix_verses VALUES ('B015C001V003', '15', 1, 3, 'Кто есть из вас, из всего народа Его,  — да будет Бог его с ним,  — и пусть он идет в Иерусалим, что в Иудее, и строит дом Господа Бога Израилева, Того Бога, Который в Иерусалиме.', 'Кто есть из вас, из всего народа Его, — да будет Бог его с ним, — и пусть он идет в Иерусалим, что в Иудее, и строит дом Господа Бога Израилева, Того Бога, Который в Иерусалиме.');
INSERT INTO fix_verses VALUES ('B015C001V007', '15', 1, 7, 'И царь Кир вынес сосуды дома Господня, которые Навуходоносор взял из Иерусалима и положил в доме бога своего,  —', 'И царь Кир вынес сосуды дома Господня, которые Навуходоносор взял из Иерусалима и положил в доме бога своего, —');
INSERT INTO fix_verses VALUES ('B015C002V001', '15', 2, 1, 'Вот сыны страны из пленников переселения, которых Навуходоносор, царь Вавилонский, отвел в Вавилон, возвратившиеся в Иерусалим и Иудею, каждый в свой город,  —', 'Вот сыны страны из пленников переселения, которых Навуходоносор, царь Вавилонский, отвел в Вавилон, возвратившиеся в Иерусалим и Иудею, каждый в свой город, —');
INSERT INTO fix_verses VALUES ('B015C002V042', '15', 2, 42, 'Сыновей привратников: сыновья Шаллума, сыновья Атера, сыновья Талмона, сыновья Аккува, сыновья Хатиты, сыновья Шовая,  — всего сто тридцать девять.', 'Сыновей привратников: сыновья Шаллума, сыновья Атера, сыновья Талмона, сыновья Аккува, сыновья Хатиты, сыновья Шовая, — всего сто тридцать девять.');
INSERT INTO fix_verses VALUES ('B015C002V057', '15', 2, 57, 'Сыновья Сефатии, сыновья Хаттила, сыновья Похереф-Гаццебайима, сыновья Амия,  —', 'Сыновья Сефатии, сыновья Хаттила, сыновья Похереф-Гаццебайима, сыновья Амия, —');
INSERT INTO fix_verses VALUES ('B015C004V009', '15', 4, 9, 'Тогда-то. Рехум советник и Шимшай писец и прочие товарищи их,  — Динеи и Афарсафхеи, Тарпелеи, Апарсы, Арехьяне, Вавилоняне, Сусанцы, Даги, Еламитяне,', 'Тогда-то. Рехум советник и Шимшай писец и прочие товарищи их, — Динеи и Афарсафхеи, Тарпелеи, Апарсы, Арехьяне, Вавилоняне, Сусанцы, Даги, Еламитяне,');
INSERT INTO fix_verses VALUES ('B015C004V015', '15', 4, 15, 'Пусть поищут в памятной книге отцов твоих,  — и найдешь в книге памятной, и узнаешь, что город сей — город мятежный и вредный для царей и областей, и [что] отпадения бывали в нем издавна, за что город сей и опустошен.', 'Пусть поищут в памятной книге отцов твоих, — и найдешь в книге памятной, и узнаешь, что город сей — город мятежный и вредный для царей и областей, и [что] отпадения бывали в нем издавна, за что город сей и опустошен.');
INSERT INTO fix_verses VALUES ('B015C004V019', '15', 4, 19, 'И от меня дано повеление,  — и разыскивали, и нашли, что город этот издавна восставал против царей, и производились в нем мятежи и волнения,', 'И от меня дано повеление, — и разыскивали, и нашли, что город этот издавна восставал против царей, и производились в нем мятежи и волнения,');
INSERT INTO fix_verses VALUES ('B015C005V011', '15', 5, 11, 'И они ответили нам такими словами: мы рабы Бога неба и земли и строим дом, который был построен за много лет прежде сего,  — и великий царь у Израиля строил его и довершил его.', 'И они ответили нам такими словами: мы рабы Бога неба и земли и строим дом, который был построен за много лет прежде сего, — и великий царь у Израиля строил его и довершил его.');
INSERT INTO fix_verses VALUES ('B015C005V014', '15', 5, 14, 'Да и сосуды дома Божия, золотые и серебряные, которые Навуходоносор вынес из храма Иерусалимского и отнес в храм Вавилонский,  — вынес Кир царь из храма Вавилонского; и отдали [их] по имени Шешбацару, которого он назначил областеначальником,', 'Да и сосуды дома Божия, золотые и серебряные, которые Навуходоносор вынес из храма Иерусалимского и отнес в храм Вавилонский, — вынес Кир царь из храма Вавилонского; и отдали [их] по имени Шешбацару, которого он назначил областеначальником,');
INSERT INTO fix_verses VALUES ('B015C006V006', '15', 6, 6, 'Итак, Фафнай, заречный областеначальник, и Шефар-Бознай, с товарищами вашими Афарсахеями, которые за рекою,  — удалитесь оттуда.', 'Итак, Фафнай, заречный областеначальник, и Шефар-Бознай, с товарищами вашими Афарсахеями, которые за рекою, — удалитесь оттуда.');
INSERT INTO fix_verses VALUES ('B015C006V013', '15', 6, 13, 'Тогда Фафнай, заречный областеначальник, Шефар-Бознай и товарищи их,  — как повелел царь Дарий, так в точности и делали.', 'Тогда Фафнай, заречный областеначальник, Шефар-Бознай и товарищи их, — как повелел царь Дарий, так в точности и делали.');
INSERT INTO fix_verses VALUES ('B015C006V020', '15', 6, 20, 'Потому что очистились священники и левиты,  — все они, как один, [были] чисты; и закололи агнцев пасхальных для всех, возвратившихся из плена, для братьев своих священников и для себя.', 'Потому что очистились священники и левиты, — все они, как один, [были] чисты; и закололи агнцев пасхальных для всех, возвратившихся из плена, для братьев своих священников и для себя.');
INSERT INTO fix_verses VALUES ('B015C007V005', '15', 7, 5, 'Сын Авишуя, сын Финееса, сын Елеазара, сын Аарона первосвященника,  —', 'Сын Авишуя, сын Финееса, сын Елеазара, сын Аарона первосвященника, —');
INSERT INTO fix_verses VALUES ('B015C007V008', '15', 7, 8, 'И пришел он в Иерусалим в пятый месяц,  — в седьмой же год царя.', 'И пришел он в Иерусалим в пятый месяц, — в седьмой же год царя.');
INSERT INTO fix_verses VALUES ('B015C007V025', '15', 7, 25, 'Ты же, Ездра, по премудрости Бога твоего, которая в руке твоей, поставь правителей и судей, чтоб они судили весь народ за рекою,  — всех знающих законы Бога твоего, а кто не знает, тех учите.', 'Ты же, Ездра, по премудрости Бога твоего, которая в руке твоей, поставь правителей и судей, чтоб они судили весь народ за рекою, — всех знающих законы Бога твоего, а кто не знает, тех учите.');
INSERT INTO fix_verses VALUES ('B015C008V025', '15', 8, 25, 'И отдал им весом серебро, и золото, и сосуды,  — все, пожертвованное [для] дома Бога нашего, что пожертвовали царь, и советники его, и князья его, и все Израильтяне, [там] находившиеся.', 'И отдал им весом серебро, и золото, и сосуды, — все, пожертвованное [для] дома Бога нашего, что пожертвовали царь, и советники его, и князья его, и все Израильтяне, [там] находившиеся.');
INSERT INTO fix_verses VALUES ('B015C008V035', '15', 8, 35, 'Пришедшие из плена переселенцы принесли во всесожжение Богу Израилеву двенадцать тельцов из всего Израиля, девяносто шесть овнов, семьдесят семь агнцев и двенадцать козлов в жертву за грех: все это во всесожжение Господу.', 'Пришедшие из плена переселенцы принесли во всесожжение Богу Израилеву двенадцать тельцов за всего Израиля, девяносто шесть овнов, семьдесят семь агнцев и двенадцать козлов в жертву за грех: все это во всесожжение Господу.');
INSERT INTO fix_verses VALUES ('B015C009V013', '15', 9, 13, 'И после всего, постигшего нас за худые дела наши и за великую вину нашу,  — ибо Ты, Боже наш, пощадил нас не по мере беззакония нашего и дал нам такое избавление,  —', 'И после всего, постигшего нас за худые дела наши и за великую вину нашу, — ибо Ты, Боже наш, пощадил нас не по мере беззакония нашего и дал нам такое избавление, —');
INSERT INTO fix_verses VALUES ('B015C010V003', '15', 10, 3, 'Заключим теперь завет с Богом нашим, что, по совету господина моего и благоговеющих пред заповедями Бога нашего, мы отпустим [от себя] всех жен и [детей], рожденных ими,  — и да будет по закону!', 'Заключим теперь завет с Богом нашим, что, по совету господина моего и благоговеющих пред заповедями Бога нашего, мы отпустим [от себя] всех жен и [детей], рожденных ими, — и да будет по закону!');
INSERT INTO fix_verses VALUES ('B015C010V018', '15', 10, 18, 'И нашлись из сыновей священнических, которые взяли жен иноплеменных,  — из сыновей Иисуса, сына Иоседекова, и братьев его: Маасея, Елиезер, Иарив и Гедалия;', 'И нашлись из сыновей священнических, которые взяли жен иноплеменных, — из сыновей Иисуса, сына Иоседекова, и братьев его: Маасея, Елиезер, Иарив и Гедалия;');
INSERT INTO fix_verses VALUES ('B015C010V025', '15', 10, 25, 'А из Израильтян,  — из сыновей Пароша: Рамаия, Иззия, Малхия, Миямин, Елеазар, Малхия и Венаия;', 'А из Израильтян, — из сыновей Пароша: Рамаия, Иззия, Малхия, Миямин, Елеазар, Малхия и Венаия;');
INSERT INTO fix_verses VALUES ('B016C002V014', '16', 2, 14, 'И подъехал я к воротам Источника и к царскому водоему, но [там] не было места пройти животному, которое было подо мною,  —', 'И подъехал я к воротам Источника и к царскому водоему, но [там] не было места пройти животному, которое было подо мною, —');
INSERT INTO fix_verses VALUES ('B016C002V018', '16', 2, 18, 'И я рассказал им о благодеявшей мне руке Бога моего, а также и слова царя, которые он говорил мне. И сказали они: будем строить,  — и укрепили руки свои на благое [дело].', 'И я рассказал им о благодеявшей мне руке Бога моего, а также и слова царя, которые он говорил мне. И сказали они: будем строить, — и укрепили руки свои на благое [дело].');
INSERT INTO fix_verses VALUES ('B016C003V015', '16', 3, 15, 'Ворота Источника чинил Шаллум, сын Колхозея, начальник округа Мицфы: он построил их, и покрыл их, и вставил двери их, замки их и засовы их,  — [он же чинил] стену у водоема Селах против царского сада и до ступеней, спускающихся из города Давидова.', 'Ворота Источника чинил Шаллум, сын Колхозея, начальник округа Мицфы: он построил их, и покрыл их, и вставил двери их, замки их и засовы их, — [он же чинил] стену у водоема Селах против царского сада и до ступеней, спускающихся из города Давидова.');
INSERT INTO fix_verses VALUES ('B016C004V022', '16', 4, 22, 'Сверх сего, в то же время я сказал народу, чтобы в Иерусалиме ночевали все с рабами своими,  — и будут они у нас ночью на страже, а днем на работе.', 'Сверх сего, в то же время я сказал народу, чтобы в Иерусалиме ночевали все с рабами своими, — и будут они у нас ночью на страже, а днем на работе.');
INSERT INTO fix_verses VALUES ('B016C006V001', '16', 6, 1, 'Когда дошло до слуха Санаваллата и Товии и Гешема Аравитянина и прочих неприятелей наших, что я отстроил стену, и не оставалось в ней повреждений — впрочем до того времени я еще не ставил дверей в ворота,  —', 'Когда дошло до слуха Санаваллата и Товии и Гешема Аравитянина и прочих неприятелей наших, что я отстроил стену, и не оставалось в ней повреждений — впрочем до того времени я еще не ставил дверей в ворота, —');
INSERT INTO fix_verses VALUES ('B016C006V018', '16', 6, 18, 'Ибо многие в Иудее были в клятвенном союзе с ним, потому что он был зять Шехании, сын Арахова, а сын его Иоханан взял [за себя] дочь Мешуллама, сына Верехии.', 'Ибо многие в Иудее были в клятвенном союзе с ним, потому что он был зять Шехании, сына Арахова, а сын его Иоханан взял [за себя] дочь Мешуллама, сына Верехии.');
INSERT INTO fix_verses VALUES ('B016C007V006', '16', 7, 6, 'Вот жители страны, которые отправились из пленников, переселенных Навуходоносором, царем Вавилонским, и возвратились в Иерусалим и Иудею, каждый в свой город,  —', 'Вот жители страны, которые отправились из пленников, переселенных Навуходоносором, царем Вавилонским, и возвратились в Иерусалим и Иудею, каждый в свой город, —');
INSERT INTO fix_verses VALUES ('B016C007V059', '16', 7, 59, 'Сыновья Сафатии, сыновья Хаттила, сыновья Похереф — Гаццевайима, сыновья Амона.', 'Сыновья Сафатии, сыновья Хаттила, сыновья Похереф-Гаццевайима, сыновья Амона.');
INSERT INTO fix_verses VALUES ('B016C008V006', '16', 8, 6, 'И благословил Ездра Господа Бога великого. И весь народ отвечал: аминь, аминь, поднимая вверх руки свои,  — и поклонялись и повергались пред Господом лицем до земли.', 'И благословил Ездра Господа Бога великого. И весь народ отвечал: аминь, аминь, поднимая вверх руки свои, — и поклонялись и повергались пред Господом лицем до земли.');
INSERT INTO fix_verses VALUES ('B016C011V003', '16', 11, 3, 'Вот главы страны, которые жили в Иерусалиме,  — а в городах Иудеи жили, всякий в своем владении, по городам своим: Израильтяне, священники, левиты и нефинеи и сыновья рабов Соломоновых;  —', 'Вот главы страны, которые жили в Иерусалиме, — а в городах Иудеи жили, всякий в своем владении, по городам своим: Израильтяне, священники, левиты и нефинеи и сыновья рабов Соломоновых; —');
INSERT INTO fix_verses VALUES ('B016C011V012', '16', 11, 12, 'И братья их, отправлявшие службу в доме [Божием]  — восемьсот двадцать два; и Адаия, сын Иерохама, сын Фелалии, сын Амция, сын Захарии, сын Пашхура, сын Малхии,', 'И братья их, отправлявшие службу в доме [Божием] — восемьсот двадцать два; и Адаия, сын Иерохама, сын Фелалии, сын Амция, сын Захарии, сын Пашхура, сын Малхии,');
INSERT INTO fix_verses VALUES ('B016C012V013', '16', 12, 13, 'Из [дома] Ездра Мешуллам, из [дома] Амарии Иоханан,', 'Из [дома] Ездры Мешуллам, из [дома] Амарии Иоханан,');
INSERT INTO fix_verses VALUES ('B016C012V026', '16', 12, 26, 'Они были во дни Иоакима, сына Иисусова, сына Иоседекова, и во дни областеначальника Неемии и книжника Ездра, священника.', 'Они были во дни Иоакима, сына Иисусова, сына Иоседекова, и во дни областеначальника Неемии и книжника Ездры, священника.');
INSERT INTO fix_verses VALUES ('B017C001V001', '17', 1, 1, 'И было во дни Артаксеркса,  — этот Артаксеркс царствовал над ста двадцатью семью областями от Индии и до Ефиопии,  —', 'И было во дни Артаксеркса, — этот Артаксеркс царствовал над ста двадцатью семью областями от Индии и до Ефиопии, —');
INSERT INTO fix_verses VALUES ('B017C001V013', '17', 1, 13, 'И сказал царь мудрецам, знающим [прежние] времена — ибо дела царя [делались] пред всеми знающими закон и права,  —', 'И сказал царь мудрецам, знающим [прежние] времена — ибо дела царя [делались] пред всеми знающими закон и права, —');
INSERT INTO fix_verses VALUES ('B017C002V007', '17', 2, 7, 'И был он воспитателем Гадассы,  — она же Есфирь,  — дочери дяди его, так как не было у нее ни отца, ни матери. Девица эта была красива станом и пригожа лицем. И по смерти отца ее и матери ее, Мардохей взял ее к себе вместо дочери.', 'И был он воспитателем Гадассы, — она же Есфирь, — дочери дяди его, так как не было у нее ни отца, ни матери. Девица эта была красива станом и пригожа лицем. И по смерти отца ее и матери ее, Мардохей взял ее к себе вместо дочери.');
INSERT INTO fix_verses VALUES ('B017C002V012', '17', 2, 12, 'Когда наступало время каждой девице входить к царю Артаксерксу, после того, как в течение двенадцати месяцев выполнено было над нею все, определенное женщинам,  — ибо столько времени продолжались дни притиранья их: шесть месяцев мирровым маслом и шесть месяцев ароматами и другими притираньями женскими,  —', 'Когда наступало время каждой девице входить к царю Артаксерксу, после того, как в течение двенадцати месяцев выполнено было над нею все, определенное женщинам, — ибо столько времени продолжались дни притиранья их: шесть месяцев мирровым маслом и шесть месяцев ароматами и другими притираньями женскими, —');
INSERT INTO fix_verses VALUES ('B017C002V015', '17', 2, 15, 'Когда настало время Есфири, дочери Аминадава, дяди Мардохея, который взял ее к себе вместо дочери,  — идти к царю, тогда она не просила ничего, кроме того, о чем сказал ей Гегай, евнух царский, страж жен. И приобрела Есфирь расположение [к себе] в глазах всех, видевших ее.', 'Когда настало время Есфири, дочери Аминадава, дяди Мардохея, который взял ее к себе вместо дочери, — идти к царю, тогда она не просила ничего, кроме того, о чем сказал ей Гегай, евнух царский, страж жен. И приобрела Есфирь расположение [к себе] в глазах всех, видевших ее.');
INSERT INTO fix_verses VALUES ('B017C002V018', '17', 2, 18, 'И сделал царь большой пир для всех князей своих и для служащих при нем,  — пир ради Есфири, и сделал льготу областям и роздал дары с царственною щедростью.', 'И сделал царь большой пир для всех князей своих и для служащих при нем, — пир ради Есфири, и сделал льготу областям и роздал дары с царственною щедростью.');
INSERT INTO fix_verses VALUES ('B017C006V002', '17', 6, 2, 'И найдено записанным [там], как донес Мардохей на Гавафу Ифарру, двух евнухов царских, оберегавших порог, которые замышлялиналожить руку на царя Артаксеркса.', 'И найдено записанным [там], как донес Мардохей на Гавафу и Фарру, двух евнухов царских, оберегавших порог, которые замышляли наложить руку на царя Артаксеркса.');
INSERT INTO fix_verses VALUES ('B017C006V004', '17', 6, 4, 'И сказал царь: кто на дворе? Аман же пришел [тогда] навнешний двор царского дома поговорить с царем, чтобы Повесилимардохея на дереве, которое он приготовил для него.', 'И сказал царь: кто на дворе? Аман же пришел [тогда] на внешний двор царского дома поговорить с царем, чтобы повесили Мардохея на дереве, которое он приготовил для него.');
INSERT INTO fix_verses VALUES ('B017C006V005', '17', 6, 5, 'И сказали отроки царю: вот, Аман стоит на дворе. И сказалцарь: пусть войдет.', 'И сказали отроки царю: вот, Аман стоит на дворе. И сказал царь: пусть войдет.');
INSERT INTO fix_verses VALUES ('B017C006V006', '17', 6, 6, 'И вошел Аман. И сказал ему царь: что сделать бы томучеловеку, которого царь хочет отличить почестью? Аман подумал всердце своем: кому [другому] захочет царь оказать почесть, кромеменя?', 'И вошел Аман. И сказал ему царь: что сделать бы тому человеку, которого царь хочет отличить почестью? Аман подумал в сердце своем: кому [другому] захочет царь оказать почесть, кроме меня?');
INSERT INTO fix_verses VALUES ('B017C006V007', '17', 6, 7, 'И сказал Аман царю: тому человеку, которого царь хочетотличить почестью,', 'И сказал Аман царю: тому человеку, которого царь хочет отличить почестью,');
INSERT INTO fix_verses VALUES ('B017C006V008', '17', 6, 8, 'Пусть принесут одеяние царское, в которое одевается царь, и [приведут] коня, на котором ездит царь, возложат царский венец наголову его,', 'Пусть принесут одеяние царское, в которое одевается царь, и [приведут] коня, на котором ездит царь, возложат царский венец на голову его,');
INSERT INTO fix_verses VALUES ('B017C006V009', '17', 6, 9, 'И пусть подадут одеяние и коня в руки одному из первыхкнязей царских, г и облекут того человека, которого царь хочетотличить почестью, и выведут его на коне на городскую площадь, ипровозгласят пред ним: так делается тому человеку, которого царьхочет отличить почестью!', 'И пусть подадут одеяние и коня в руки одному из первых князей царских, — и облекут того человека, которого царь хочет отличить почестью, и выведут его на коне на городскую площадь, и провозгласят пред ним: так делается тому человеку, которого царь хочет отличить почестью!');
INSERT INTO fix_verses VALUES ('B017C006V010', '17', 6, 10, 'И сказал царь Аману: тотчас же возьмиодеяние и коня, как ты сказал, и сделай это Мардохею Иудеянину, сидящему у царских ворот; ничего не опусти из всего, что тыговорил.', 'И сказал царь Аману: тотчас же возьми одеяние и коня, как ты сказал, и сделай это Мардохею Иудеянину, сидящему у царских ворот; ничего не опусти из всего, что ты говорил.');
INSERT INTO fix_verses VALUES ('B017C006V011', '17', 6, 11, 'И взял Аман одеяние и коня и облек Мардохея, и вывел его наконе на городскую площадь и провозгласил пред ним: так делаетсятому человеку, которого царь хочет отличить почестью!', 'И взял Аман одеяние и коня и облек Мардохея, и вывел его на коне на городскую площадь и провозгласил пред ним: так делается тому человеку, которого царь хочет отличить почестью!');
INSERT INTO fix_verses VALUES ('B017C006V012', '17', 6, 12, 'И возвратился Мардохей к царским воротам. Аман же поспешилв дом свой, печальный и закрыв голову.', 'И возвратился Мардохей к царским воротам. Аман же поспешил в дом свой, печальный и закрыв голову.');
INSERT INTO fix_verses VALUES ('B017C006V013', '17', 6, 13, 'И пересказал Аман Зереши, жене своей, и всем друзьям своимвсе, что случилось с ним. И сказали ему мудрецы его и Зерешь, жена его: если из племени Иудеев Мардохей, изгза которого тыначал падать, то не пересилишь его, а наверно падешь пред ним.', 'И пересказал Аман Зереши, жене своей, и всем друзьям своим все, что случилось с ним. И сказали ему мудрецы его и Зерешь, жена его: если из племени Иудеев Мардохей, из-за которого ты начал падать, то не пересилишь его, а наверно падешь пред ним.');
INSERT INTO fix_verses VALUES ('B017C006V014', '17', 6, 14, 'Они еще разговаривали с ним, [как] пришли евнухи царя и сталиторопить Амана идти на пир, который приготовила Есфирь.', 'Они еще разговаривали с ним, [как] пришли евнухи царя и стали торопить Амана идти на пир, который приготовила Есфирь.');
INSERT INTO fix_verses VALUES ('B017C007V008', '17', 7, 8, 'Когда царь возвратился из сада при дворце в дом пира, Аман был припавшим к ложу, на котором находилась Есфирь. И сказал царь: даже и насиловать царицу [хочет] в доме у меня! Слово вышло из уст царя,  — и накрыли лице Аману.', 'Когда царь возвратился из сада при дворце в дом пира, Аман был припавшим к ложу, на котором находилась Есфирь. И сказал царь: даже и насиловать царицу [хочет] в доме у меня! Слово вышло из уст царя, — и накрыли лице Аману.');
INSERT INTO fix_verses VALUES ('B017C009V001', '17', 9, 1, 'В двенадцатый месяц, то есть в месяц Адар, в тринадцатый день его, в который пришло время исполниться повелению царя и указу его, в тот день, когда надеялись неприятели Иудеев взять власть над ними, а вышло наоборот, что сами Иудеи взяли власть над врагами своими,  —', 'В двенадцатый месяц, то есть в месяц Адар, в тринадцатый день его, в который пришло время исполниться повелению царя и указу его, в тот день, когда надеялись неприятели Иудеев взять власть над ними, а вышло наоборот, что сами Иудеи взяли власть над врагами своими, —');
INSERT INTO fix_verses VALUES ('B017C009V009', '17', 9, 9, 'И Пармашфу и Арисая и Аридая и Ваиезафу,  —', 'И Пармашфу и Арисая и Аридая и Ваиезафу, —');
INSERT INTO fix_verses VALUES ('B017C009V022', '17', 9, 22, 'Как таких дней, в которые Иудеи сделались покойны от врагов своих, и [как] такого месяца, в который превратилась у них печаль в радость, и сетование — в день праздничный,  — чтобы сделали их днями пиршества и веселья, посылая подарки друг другу и подаяния бедным.', 'Как таких дней, в которые Иудеи сделались покойны от врагов своих, и [как] такого месяца, в который превратилась у них печаль в радость, и сетование — в день праздничный, — чтобы сделали их днями пиршества и веселья, посылая подарки друг другу и подаяния бедным.');
INSERT INTO fix_verses VALUES ('B018C001V011', '18', 1, 11, 'Но простри руку Твою и коснись всего, что у него,  — благословит ли он Тебя?', 'Но простри руку Твою и коснись всего, что у него, — благословит ли он Тебя?');
INSERT INTO fix_verses VALUES ('B018C002V005', '18', 2, 5, 'Но простри руку Твою и коснись кости его и плоти его,  — благословит ли он Тебя?', 'Но простри руку Твою и коснись кости его и плоти его, — благословит ли он Тебя?');
INSERT INTO fix_verses VALUES ('B018C003V006', '18', 3, 6, 'Ночь та,  — да обладает ею мрак, да не сочтется она в днях года, да не войдет в число месяцев!', 'Ночь та, — да обладает ею мрак, да не сочтется она в днях года, да не войдет в число месяцев!');
INSERT INTO fix_verses VALUES ('B018C004V002', '18', 4, 2, '[если] попытаемся мы [сказать] к тебе слово,  — не тяжело ли будет тебе? Впрочем кто может возбранить слову!', '[если] попытаемся мы [сказать] к тебе слово, — не тяжело ли будет тебе? Впрочем кто может возбранить слову!');
INSERT INTO fix_verses VALUES ('B018C004V016', '18', 4, 16, 'Он стал,  — но я не распознал вида его,  — только облик был пред глазами моими; тихое веяние,  — и я слышу голос:', 'Он стал, — но я не распознал вида его, — только облик был пред глазами моими; тихое веяние, — и я слышу голос:');
INSERT INTO fix_verses VALUES ('B018C006V029', '18', 6, 29, 'Пересмотрите, есть ли неправда? пересмотрите,  — правда моя.', 'Пересмотрите, есть ли неправда? пересмотрите, — правда моя.');
INSERT INTO fix_verses VALUES ('B018C007V008', '18', 7, 8, 'Не увидит меня око видевшего меня; очи Твои на меня,  — и нет меня.', 'Не увидит меня око видевшего меня; очи Твои на меня, — и нет меня.');
INSERT INTO fix_verses VALUES ('B018C008V002', '18', 8, 2, 'Долго ли ты будешь говорить так?  — слова уст твоих бурный ветер!', 'Долго ли ты будешь говорить так? — слова уст твоих бурный ветер!');
INSERT INTO fix_verses VALUES ('B018C009V007', '18', 9, 7, 'Скажет солнцу,  — и не взойдет, и на звезды налагает печать.', 'Скажет солнцу, — и не взойдет, и на звезды налагает печать.');
INSERT INTO fix_verses VALUES ('B018C009V009', '18', 9, 9, 'Сотворил Ас, Кесиль и Хима (1) и тайники юга;', 'Сотворил Ас, Кесиль и Хима и тайники юга;');
INSERT INTO fix_verses VALUES ('B018C009V016', '18', 9, 16, 'Если бы я воззвал, и Он ответил мне,  — я не поверил бы, что голос мой услышал Тот,', 'Если бы я воззвал, и Он ответил мне, — я не поверил бы, что голос мой услышал Тот,');
INSERT INTO fix_verses VALUES ('B018C009V025', '18', 9, 25, 'Дни мои быстрее гонца,  — бегут, не видят добра,', 'Дни мои быстрее гонца, — бегут, не видят добра,');
INSERT INTO fix_verses VALUES ('B018C009V034', '18', 9, 34, 'Да отстранит Он от меня жезл Свой, и страх Его да не ужасает меня,  —', 'Да отстранит Он от меня жезл Свой, и страх Его да не ужасает меня, —');
INSERT INTO fix_verses VALUES ('B018C010V008', '18', 10, 8, 'Твои руки трудились надо мною и образовали всего меня кругом,  — и Ты губишь меня?', 'Твои руки трудились надо мною и образовали всего меня кругом, — и Ты губишь меня?');
INSERT INTO fix_verses VALUES ('B018C010V013', '18', 10, 13, 'Но и то скрывал Ты в сердце Своем,  — знаю, что это было у Тебя,  —', 'Но и то скрывал Ты в сердце Своем, — знаю, что это было у Тебя, —');
INSERT INTO fix_verses VALUES ('B018C010V021', '18', 10, 21, 'Прежде нежели отойду,  — и уже не возвращусь,  — в страну тьмы и сени смертной,', 'Прежде нежели отойду, — и уже не возвращусь, — в страну тьмы и сени смертной,');
INSERT INTO fix_verses VALUES ('B018C011V008', '18', 11, 8, 'Он превыше небес,  — что можешь сделать? глубже преисподней,  — что можешь узнать?', 'Он превыше небес, — что можешь сделать? глубже преисподней, — что можешь узнать?');
INSERT INTO fix_verses VALUES ('B018C013V027', '18', 13, 27, 'И ставишь в колоду ноги мои и подстерегаешь все стези мои,  — гонишься по следам ног моих.', 'И ставишь в колоду ноги мои и подстерегаешь все стези мои, — гонишься по следам ног моих.');
INSERT INTO fix_verses VALUES ('B018C019V024', '18', 19, 24, 'Резцом железным с оловом,  — на вечное время на камне вырезаны были!', 'Резцом железным с оловом, — на вечное время на камне вырезаны были!');
INSERT INTO fix_verses VALUES ('B018C020V004', '18', 20, 4, 'Разве не знаешь ты, что от века,  — с того времени, как поставлен человек на земле,  —', 'Разве не знаешь ты, что от века, — с того времени, как поставлен человек на земле, —');
INSERT INTO fix_verses VALUES ('B018C020V006', '18', 20, 6, 'Хотя бы возросло до небес величие его, и голова его касалась облаков,  —', 'Хотя бы возросло до небес величие его, и голова его касалась облаков, —');
INSERT INTO fix_verses VALUES ('B018C020V024', '18', 20, 24, 'Убежит ли он от оружия железного,  — пронзит его лук медный;', 'Убежит ли он от оружия железного, — пронзит его лук медный;');
INSERT INTO fix_verses VALUES ('B018C020V025', '18', 20, 25, 'Станет вынимать [стрелу],  — и она выйдет из тела, выйдет, сверкая сквозь желчь его; ужасы смерти найдут на него!', 'Станет вынимать [стрелу], — и она выйдет из тела, выйдет, сверкая сквозь желчь его; ужасы смерти найдут на него!');
INSERT INTO fix_verses VALUES ('B018C021V006', '18', 21, 6, 'Лишь только я вспомню,  — содрогаюсь, и трепет объемлет тело мое.', 'Лишь только я вспомню, — содрогаюсь, и трепет объемлет тело мое.');
INSERT INTO fix_verses VALUES ('B018C021V016', '18', 21, 16, 'Видишь, счастье их не от их рук.  — Совет нечестивых будь далек от меня!', 'Видишь, счастье их не от их рук. — Совет нечестивых будь далек от меня!');
INSERT INTO fix_verses VALUES ('B018C021V019', '18', 21, 19, '[Скажешь]: Бог бережет для детей его несчастье его.  — Пусть воздаст Он ему самому, чтобы он это знал.', '[Скажешь]: Бог бережет для детей его несчастье его. — Пусть воздаст Он ему самому, чтобы он это знал.');
INSERT INTO fix_verses VALUES ('B018C023V007', '18', 23, 7, 'Тогда праведник мог бы состязаться с Ним,  — и я навсегда получил бы свободу от Судии моего.', 'Тогда праведник мог бы состязаться с Ним, — и я навсегда получил бы свободу от Судии моего.');
INSERT INTO fix_verses VALUES ('B018C023V010', '18', 23, 10, 'Но Он знает путь мой; пусть испытает меня,  — выйду, как золото.', 'Но Он знает путь мой; пусть испытает меня, — выйду, как золото.');
INSERT INTO fix_verses VALUES ('B018C024V015', '18', 24, 15, 'И око прелюбодея ждет сумерков, говоря: ничей глаз не увидит меня,  — и закрывает лице.', 'И око прелюбодея ждет сумерков, говоря: ничей глаз не увидит меня, — и закрывает лице.');
INSERT INTO fix_verses VALUES ('B018C024V024', '18', 24, 24, 'Поднялись высоко,  — и вот, нет их; падают и умирают, как и все, и, как верхушки колосьев, срезываются.', 'Поднялись высоко, — и вот, нет их; падают и умирают, как и все, и, как верхушки колосьев, срезываются.');
INSERT INTO fix_verses VALUES ('B018C024V025', '18', 24, 25, 'Если это не так,  — кто обличит меня во лжи и в ничто обратит речь мою?', 'Если это не так, — кто обличит меня во лжи и в ничто обратит речь мою?');
INSERT INTO fix_verses VALUES ('B018C029V007', '18', 29, 7, 'Когда я выходил к воротам города и на площади ставил седалище свое,  —', 'Когда я выходил к воротам города и на площади ставил седалище свое, —');
INSERT INTO fix_verses VALUES ('B018C030V020', '18', 30, 20, 'Я взываю к Тебе, и Ты не внимаешь мне,  — стою, а Ты [только] смотришь на меня.', 'Я взываю к Тебе, и Ты не внимаешь мне, — стою, а Ты [только] смотришь на меня.');
INSERT INTO fix_verses VALUES ('B018C031V005', '18', 31, 5, 'Если я ходил в суете, и если нога моя спешила на лукавство,  —', 'Если я ходил в суете, и если нога моя спешила на лукавство, —');
INSERT INTO fix_verses VALUES ('B018C031V009', '18', 31, 9, 'Если сердце мое прельщалось женщиною и я строил ковы у дверей моего ближнего,  —', 'Если сердце мое прельщалось женщиною и я строил ковы у дверей моего ближнего, —');
INSERT INTO fix_verses VALUES ('B018C031V019', '18', 31, 19, 'Если я видел кого погибавшим без одежды и бедного без покрова,  —', 'Если я видел кого погибавшим без одежды и бедного без покрова, —');
INSERT INTO fix_verses VALUES ('B018C032V011', '18', 32, 11, 'Вот, я ожидал слов ваших,  — вслушивался в суждения ваши, доколе вы придумывали, что сказать.', 'Вот, я ожидал слов ваших, — вслушивался в суждения ваши, доколе вы придумывали, что сказать.');
INSERT INTO fix_verses VALUES ('B018C033V019', '18', 33, 19, 'Или он вразумляется болезнью на ложе своем и жестокою болью во всех костях своих,  —', 'Или он вразумляется болезнью на ложе своем и жестокою болью во всех костях своих, —');
INSERT INTO fix_verses VALUES ('B018C033V023', '18', 33, 23, 'Если есть у него Ангел-наставник, один из тысячи, чтобы показать человеку прямой [путь] его,  —', 'Если есть у него Ангел-наставник, один из тысячи, чтобы показать человеку прямой [путь] его, —');
INSERT INTO fix_verses VALUES ('B018C034V014', '18', 34, 14, 'Если бы Он обратил сердце Свое к Себе и взял к Себе дух ее и дыхание ее,  —', 'Если бы Он обратил сердце Свое к Себе и взял к Себе дух ее и дыхание ее, —');
INSERT INTO fix_verses VALUES ('B018C036V019', '18', 36, 19, 'Даст ли Он какую цену твоему богатству? Нет,  — ни золоту и никакому сокровищу.', 'Даст ли Он какую цену твоему богатству? Нет, — ни золоту и никакому сокровищу.');
INSERT INTO fix_verses VALUES ('B018C038V029', '18', 38, 29, 'Из чьего чрева выходит лед, и иней небесный,  — кто рождает его?', 'Из чьего чрева выходит лед, и иней небесный, — кто рождает его?');
INSERT INTO fix_verses VALUES ('B018C040V005', '18', 39, 35, 'Однажды я говорил,  — теперь отвечать не буду, даже дважды, но более не буду.', 'Однажды я говорил, — теперь отвечать не буду, даже дважды, но более не буду.');
INSERT INTO fix_verses VALUES ('B018C042V003', '18', 42, 3, 'Кто сей, омрачающий Провидение, ничего не разумея?  — Так, я говорил о том, чего не разумел, о делах чудных для меня, которых я не знал.', 'Кто сей, омрачающий Провидение, ничего не разумея? — Так, я говорил о том, чего не разумел, о делах чудных для меня, которых я не знал.');
INSERT INTO fix_verses VALUES ('B018C042V009', '18', 42, 9, 'И пошли Елифаз Феманитянин и Вилдад Савхеянин и Софар Наамитянин, и сделали так, как Господь повелел им,  — и Господь принял лице Иова.', 'И пошли Елифаз Феманитянин и Вилдад Савхеянин и Софар Наамитянин, и сделали так, как Господь повелел им, — и Господь принял лице Иова.');
INSERT INTO fix_verses VALUES ('B019C001V004', '19', 1, 4, 'Не так - нечестивые; но они — как прах, возметаемый ветром.', 'Не так — нечестивые; но они — как прах, возметаемый ветром.');
INSERT INTO fix_verses VALUES ('B019C001V005', '19', 1, 5, 'Потому не устоят нечестивые на суде, и грешники в собрании праведных.', 'Потому не устоят нечестивые на суде, и грешники — в собрании праведных.');
INSERT INTO fix_verses VALUES ('B019C005V003', '19', 5, 4, 'Господи! рано услышь голос мой,  — рано предстану пред Тобою, и буду ожидать,', 'Господи! рано услышь голос мой, — рано предстану пред Тобою, и буду ожидать,');
INSERT INTO fix_verses VALUES ('B019C010V007', '19', 9, 28, 'Уста его полны проклятия, коварства и лжи; под языком — его мучение и пагуба;', 'Уста его полны проклятия, коварства и лжи; под языком его — мучение и пагуба;');
INSERT INTO fix_verses VALUES ('B019C018V000', '19', 17, 1, '«Начальнику хора. Раба Господня Давида, который произнес слова песни сей к Господу, когда Господь избавил его от рук всех врагов его и от руки Саула. И он сказал:«', '«Начальнику хора. Раба Господня Давида, который произнес слова песни сей к Господу, когда Господь избавил его от рук всех врагов его и от руки Саула. И он сказал:»');
INSERT INTO fix_verses VALUES ('B019C035V003', '19', 34, 3, 'Обнажи мечь и прегради [путь] преследующим меня; скажи душе моей: «Я — спасение твое!»', 'Обнажи меч и прегради [путь] преследующим меня; скажи душе моей: «Я — спасение твое!»');
INSERT INTO fix_verses VALUES ('B019C050V001', '19', 49, 1, '«Псалом Асафа.» Бог Богов, Господь возглаголал и призывает землю, от восхода солнца до запада.', '«Псалом Асафа.» Бог богов, Господь возглаголал и призывает землю, от восхода солнца до запада.');
INSERT INTO fix_verses VALUES ('B019C051V000b', '19', 50, 2, 'Когда приходил к нему пророк Нафан, после того, как Давид вошел к Вирсавии.', 'Когда приходил к нему пророк Нафан, после того, как Давид вошел к Вирсавии.»');
INSERT INTO fix_verses VALUES ('B019C051V001', '19', 50, 3, 'Помилуй меня, Боже, по великой милости Твоей, и по множеству щедрот Твоих изгладь беззакония мои.»', 'Помилуй меня, Боже, по великой милости Твоей, и по множеству щедрот Твоих изгладь беззакония мои.');
INSERT INTO fix_verses VALUES ('B019C052V000b', '19', 51, 2, 'После того, как приходил Доик Идумеянин и донес Саулу и сказал ему, что Давид пришел в дом Ахимелеха.', 'После того, как приходил Доик Идумеянин и донес Саулу и сказал ему, что Давид пришел в дом Ахимелеха.»');
INSERT INTO fix_verses VALUES ('B019C052V001', '19', 51, 3, 'Что хвалишься злодейством, сильный? милость Божия всегда [со мною;]«', 'Что хвалишься злодейством, сильный? милость Божия всегда [со мною];');
INSERT INTO fix_verses VALUES ('B019C054V000b', '19', 53, 2, 'Когда пришли Зифеи и сказали Саулу: «не у нас ли скрывается Давид?»', 'Когда пришли Зифеи и сказали Саулу: «не у нас ли скрывается Давид?»»');
INSERT INTO fix_verses VALUES ('B019C054V001', '19', 53, 3, 'Боже! именем Твоим спаси меня, и силою Твоею суди меня.»', 'Боже! именем Твоим спаси меня, и силою Твоею суди меня.');
INSERT INTO fix_verses VALUES ('B019C071V024', '19', 70, 24, 'И язык мой всякий день будет возвещать правду Твою, ибо постыжены и посрамлены ищущие мне зла. О Соломоне.', 'И язык мой всякий день будет возвещать правду Твою, ибо постыжены и посрамлены ищущие мне зла.');
INSERT INTO fix_verses VALUES ('B019C072V001', '19', 71, 1, '«Псалом Давида.» Боже! даруй царю Твой суд и сыну царя Твою правду,', '«О Соломоне.» Боже! даруй царю Твой суд и сыну царя Твою правду,');
INSERT INTO fix_verses VALUES ('B019C072V020', '19', 71, 20, 'Кончились молитвы Давида, сына Иесеева.', 'Кончились молитвы Давида, сына Иессеева.');
INSERT INTO fix_verses VALUES ('B019C074V002', '19', 73, 2, 'Вспомни сонм Твой, [который] Ты стяжал издревле, искупил в жезл достояния Твоего, — эту гору Сион, на которой Ты веселился.', 'Вспомни сонм Твой, [который] Ты стяжал издревле, искупил в жезл достояния Твоего, — эту гору Сион, на которой Ты вселился.');
INSERT INTO fix_verses VALUES ('B019C086V015', '19', 85, 15, 'Но Ты, Господи, Боже щедрый и благосердный, долготерпеливый и многомилостивый и истинный,', 'Но Ты, Господи, Боже щедрый и благосердый, долготерпеливый и многомилостивый и истинный,');
INSERT INTO fix_verses VALUES ('B019C098V001', '19', 97, 1, '«Псалом« Воспойте Господу новую песнь, ибо Он сотворил чудеса. Его десница и святая мышца Его доставили Ему победу.', '«Псалом.» Воспойте Господу новую песнь, ибо Он сотворил чудеса. Его десница и святая мышца Его доставили Ему победу.');
INSERT INTO fix_verses VALUES ('B019C105V045', '19', 104, 45, 'Чтобы соблюдали уставы Его и хранили законы Его. Аллилуия! Аллилуия.', 'Чтобы соблюдали уставы Его и хранили законы Его. Аллилуия!');
INSERT INTO fix_verses VALUES ('B019C106V001', '19', 105, 1, 'Славьте Господа, ибо Он благ, ибо вовек милость Его.', '«Аллилуия.» Славьте Господа, ибо Он благ, ибо вовек милость Его.');
INSERT INTO fix_verses VALUES ('B019C119V067', '19', 118, 67, 'Прежде страдания моего я заблуждал; а ныне слово Твое храню.', 'Прежде страдания моего я заблуждался; а ныне слово Твое храню.');
INSERT INTO fix_verses VALUES ('B019C141V001', '19', 140, 1, '«Псалом Давида.» Господи! к тебе взываю: поспеши ко мне, внемли голосу моления моего, когда взываю к Тебе.', '«Псалом Давида.» Господи! к Тебе взываю: поспеши ко мне, внемли голосу моления моего, когда взываю к Тебе.');
INSERT INTO fix_verses VALUES ('B019C147V006', '19', 146, 6, 'Смиренных возвышает Господь, а нечестивых унижает до земли', 'Смиренных возвышает Господь, а нечестивых унижает до земли.');
INSERT INTO fix_verses VALUES ('B020C001V001', '20', 1, 1, 'Притчи, сына Давидова, царя Израильского,', 'Притчи Соломона, сына Давидова, царя Израильского,');
INSERT INTO fix_verses VALUES ('B020C010V001', '20', 10, 1, 'Притчи. Сын мудрый радует отца, а сын глупый — огорчение для его матери.', 'Притчи Соломона. Сын мудрый радует отца, а сын глупый — огорчение для его матери.');
INSERT INTO fix_verses VALUES ('B020C012V005', '20', 12, 5, 'Промышления праведных — правда, а замыслы нечестивых — коварство.', 'Помышления праведных — правда, а замыслы нечестивых — коварство.');
INSERT INTO fix_verses VALUES ('B020C025V001', '20', 25, 1, 'И это Притчи, которые собрали мужи Езекии, царя Иудейского.', 'И это притчи Соломона, которые собрали мужи Езекии, царя Иудейского.');
INSERT INTO fix_verses VALUES ('B020C028V018', '20', 28, 18, 'Кто ходит непорочно, то будет невредим; а ходящий кривыми путями упадет на одном из них.', 'Кто ходит непорочно, тот будет невредим; а ходящий кривыми путями упадет на одном из них.');
INSERT INTO fix_verses VALUES ('B023C007V001', '23', 7, 1, 'И было во дни Ахаза, сына Иоафамова, сына Озии, царя Иудейского, Рецин, царь Сирийский, и факей, сын Ремалиин, царь Израильский, пошли против Иерусалима, чтобы завоевать его, но не могли завоевать.', 'И было во дни Ахаза, сына Иоафамова, сына Озии, царя Иудейского, Рецин, царь Сирийский, и Факей, сын Ремалиин, царь Израильский, пошли против Иерусалима, чтобы завоевать его, но не могли завоевать.');
INSERT INTO fix_verses VALUES ('B023C019V013', '23', 19, 13, 'Обезумели князья Цоанские; обманулись князья Мемфисские, и совратил Египет с пути главы племен его.', 'Обезумели князья Цоанские; обманулись князья Мемфисские, и совратили Египет с пути главы племен его.');
INSERT INTO fix_verses VALUES ('B023C028V004', '23', 28, 4, 'И с увядшим цветком красивого убранства его, который навершине тучной долины, делается то же, что бывает с созревшею прежде времени смоквою, которую, как скоро кто увидит, тотчас берет в руку и проглатывает ее.', 'И с увядшим цветком красивого убранства его, который на вершине тучной долины, делается то же, что бывает с созревшею прежде времени смоквою, которую, как скоро кто увидит, тотчас берет в руку и проглатывает ее.');
INSERT INTO fix_verses VALUES ('B023C028V008', '23', 28, 8, 'Ибо все столы наполнены отвратительною блевотиною, нет [чистого] места.', 'Ибо все столы наполнены отвратительною блевотиною, нет [чистого] места. —');
INSERT INTO fix_verses VALUES ('B023C028V012', '23', 28, 12, 'Им говорили: «вот покой, дайте покой утружденному, и вот успокоение». Но они не хотели слушать.', 'Им говорили: «вот — покой, дайте покой утружденному, и вот — успокоение». Но они не хотели слушать.');
INSERT INTO fix_verses VALUES ('B023C028V013', '23', 28, 13, 'И стало у них словом Господа: заповедь на заповедь, заповедь на заповедь, правило на правило, правило на правило, тут немного, там немного, так что они пойдут, и упадут навзничь, и разобьются, и попадут в сеть и будут уловлены.', 'И стало у них словом Господа: заповедь на заповедь, заповедь на заповедь, правило на правило, правило на правило, тут немного, там немного, — так что они пойдут, и упадут навзничь, и разобьются, и попадут в сеть и будут уловлены.');
INSERT INTO fix_verses VALUES ('B023C028V015', '23', 28, 15, 'Так как вы говорите: «мы заключили союз со смертью и с преисподнею сделали договор: когда всепоражающий бич будет проходить, он не дойдет до нас, потому что ложь сделали мы убежищем для себя, и обманом прикроем себя».', 'Так как вы говорите: «мы заключили союз со смертью и с преисподнею сделали договор: когда всепоражающий бич будет проходить, он не дойдет до нас, — потому что ложь сделали мы убежищем для себя, и обманом прикроем себя».');
INSERT INTO fix_verses VALUES ('B023C028V016', '23', 28, 16, 'Посему так говорит Господь Бог: вот, Я полагаю в основание на Сионе камень, камень испытанный, краеугольный, драгоценный, крепко утвержденный: верующий в него не постыдится.', 'Посему так говорит Господь Бог: вот, Я полагаю в основание на Сионе камень, — камень испытанный, краеугольный, драгоценный, крепко утвержденный: верующий в него не постыдится.');
INSERT INTO fix_verses VALUES ('B023C028V017', '23', 28, 17, 'И поставлю суд мерилом и правду весами; и градом истребитсяубежище лжи, и воды потопят место укрывательства.', 'И поставлю суд мерилом и правду весами; и градом истребится убежище лжи, и воды потопят место укрывательства.');
INSERT INTO fix_verses VALUES ('B023C028V027', '23', 28, 27, 'Ибо не молотят чернухи катком зубчатым, и колес молотильныхне катают по тмину; но палкою выколачивают чернуху, и тмин палкою.', 'Ибо не молотят чернухи катком зубчатым, и колес молотильных не катают по тмину; но палкою выколачивают чернуху, и тмин — палкою.');
INSERT INTO fix_verses VALUES ('B023C036V011', '23', 36, 11, 'И сказал Елиаким и Севна и Иоах Рабсаку: говори рабам твоим по-арамейски, потому что мы понимаем, а не говори с нами по — иудейски, вслух народа, который на стене.', 'И сказал Елиаким и Севна и Иоах Рабсаку: говори рабам твоим по-арамейски, потому что мы понимаем, а не говори с нами по-иудейски, вслух народа, который на стене.');
INSERT INTO fix_verses VALUES ('B023C051V001', '23', 51, 1, 'Послушайте Меня, стремящиеся к правде, ищущие Господа! Взгляните на скалу, из которой вы иссечены, в глубину рва, изкоторого вы извлечены.', 'Послушайте Меня, стремящиеся к правде, ищущие Господа! Взгляните на скалу, из которой вы иссечены, в глубину рва, из которого вы извлечены.');
INSERT INTO fix_verses VALUES ('B023C051V002', '23', 51, 2, 'Посмотрите на Авраама, отца вашего, и на Сарру, родившуювас: ибо Я призвал его одного и благословил его, и размножил его.', 'Посмотрите на Авраама, отца вашего, и на Сарру, родившую вас: ибо Я призвал его одного и благословил его, и размножил его.');
INSERT INTO fix_verses VALUES ('B023C051V003', '23', 51, 3, 'Так, Господь утешит Сион, утешит все развалины его и сделаетпустыни его, как рай, и степь его, как сад Господа; радость ивеселие будет в нем, славословие и песнопение.', 'Так, Господь утешит Сион, утешит все развалины его и сделает пустыни его, как рай, и степь его, как сад Господа; радость и веселие будет в нем, славословие и песнопение.');
INSERT INTO fix_verses VALUES ('B023C051V004', '23', 51, 4, 'Послушайте Меня, народ Мой, и племя Мое, приклоните ухо Комне! ибо от Меня произойдет закон, и суд Мой поставлю во свет длянародов.', 'Послушайте Меня, народ Мой, и племя Мое, приклоните ухо ко Мне! ибо от Меня произойдет закон, и суд Мой поставлю во свет для народов.');
INSERT INTO fix_verses VALUES ('B023C051V005', '23', 51, 5, 'Правда Моя близка; спасение Мое восходит, и мышца Моя будетсудить народы; острова будут уповать на Меня и надеяться на Мышцумою.', 'Правда Моя близка; спасение Мое восходит, и мышца Моя будет судить народы; острова будут уповать на Меня и надеяться на мышцу Мою.');
INSERT INTO fix_verses VALUES ('B023C051V006', '23', 51, 6, 'Поднимите глаза ваши к небесам, и посмотрите на землю вниз: ибо небеса исчезнут, как дым, и земля обветшает, как одежда, ижители ее также вымрут; а Мое спасение пребудет вечным, и Правдамоя не престанет.', 'Поднимите глаза ваши к небесам, и посмотрите на землю вниз: ибо небеса исчезнут, как дым, и земля обветшает, как одежда, и жители ее также вымрут; а Мое спасение пребудет вечным, и правда Моя не престанет.');
INSERT INTO fix_verses VALUES ('B023C051V007', '23', 51, 7, 'Послушайте Меня, знающие правду, народ, у которого в сердцезакон Мой! Не бойтесь поношения от людей, и злословия их нестрашитесь.', 'Послушайте Меня, знающие правду, народ, у которого в сердце закон Мой! Не бойтесь поношения от людей, и злословия их не страшитесь.');
INSERT INTO fix_verses VALUES ('B023C051V008', '23', 51, 8, 'Ибо, как одежду, съест их моль и, как волну, съест их червь; а правда Моя пребудет вовек, и спасение Мое г в роды родов.', 'Ибо, как одежду, съест их моль и, как волну, съест их червь; а правда Моя пребудет вовек, и спасение Мое — в роды родов.');
INSERT INTO fix_verses VALUES ('B023C051V009', '23', 51, 9, 'Восстань, восстань, облекись крепостью, мышца Господня! Восстань, как в дни древние, в роды давние! Не ты ли Сразилараава, поразила крокодила?', 'Восстань, восстань, облекись крепостью, мышца Господня! Восстань, как в дни древние, в роды давние! Не ты ли сразила Раава, поразила крокодила?');
INSERT INTO fix_verses VALUES ('B023C051V010', '23', 51, 10, 'Не ты ли иссушила море, воды великой бездны, превратилаглубины моря в дорогу, чтобы прошли искупленные?', 'Не ты ли иссушила море, воды великой бездны, превратила глубины моря в дорогу, чтобы прошли искупленные?');
INSERT INTO fix_verses VALUES ('B023C051V011', '23', 51, 11, 'И возвратятся избавленные Господом и придут на Сион спением, и радость вечная над головою их; они найдут радость ивеселье: печаль и вздохи удалятся.', 'И возвратятся избавленные Господом и придут на Сион с пением, и радость вечная над головою их; они найдут радость и веселье: печаль и вздохи удалятся.');
INSERT INTO fix_verses VALUES ('B023C051V012', '23', 51, 12, 'Я, Я Сам г Утешитель ваш. Кто ты, что боишься человека, который умирает, и сына человеческого, который то же, что трава,', 'Я, Я Сам — Утешитель ваш. Кто ты, что боишься человека, который умирает, и сына человеческого, который то же, что трава,');
INSERT INTO fix_verses VALUES ('B023C051V013', '23', 51, 13, 'И забываешь Господа, Творца своего, распростершего небеса иосновавшего землю; и непрестанно, всякий день страшишься яростипритеснителя, как бы он готов был истребить? Но где яростьпритеснителя?', 'И забываешь Господа, Творца своего, распростершего небеса и основавшего землю; и непрестанно, всякий день страшишься ярости притеснителя, как бы он готов был истребить? Но где ярость притеснителя?');
INSERT INTO fix_verses VALUES ('B023C051V014', '23', 51, 14, 'Скоро освобожден будет пленный, и не умрет в яме и не будетнуждаться в хлебе.', 'Скоро освобожден будет пленный, и не умрет в яме и не будет нуждаться в хлебе.');
INSERT INTO fix_verses VALUES ('B023C051V015', '23', 51, 15, 'Я Господь, Бог твой, возмущающий море, так что волны егоревут: Господь Саваоф г имя Его.', 'Я Господь, Бог твой, возмущающий море, так что волны его ревут: Господь Саваоф — имя Его.');
INSERT INTO fix_verses VALUES ('B023C051V016', '23', 51, 16, 'И Я вложу слова Мои в уста твои, и тенью руки Моей покроютебя, чтобы устроить небеса и утвердить землю и сказать Сиону: «ты Мой народ».', 'И Я вложу слова Мои в уста твои, и тенью руки Моей покрою тебя, чтобы устроить небеса и утвердить землю и сказать Сиону: «ты Мой народ».');
INSERT INTO fix_verses VALUES ('B023C051V017', '23', 51, 17, 'Воспряни, воспряни, восстань, Иерусалим, ты, который изруки Господа выпил чашу ярости Его, выпил до дна чашу опьянения, осушил.', 'Воспряни, воспряни, восстань, Иерусалим, ты, который из руки Господа выпил чашу ярости Его, выпил до дна чашу опьянения, осушил.');
INSERT INTO fix_verses VALUES ('B023C051V018', '23', 51, 18, 'Некому было вести его из всех сыновей, рожденных им, инекому было поддержать его за руку из всех сыновей, [которых] онвозрастил.', 'Некому было вести его из всех сыновей, рожденных им, и некому было поддержать его за руку из всех сыновей, [которых] он возрастил.');
INSERT INTO fix_verses VALUES ('B023C051V019', '23', 51, 19, 'Тебя постигли два [бедствия], кто пожалеет о тебе? гопустошение и истребление, голод и меч: кем я утешу тебя?', 'Тебя постигли два [бедствия], кто пожалеет о тебе? — опустошение и истребление, голод и меч: кем я утешу тебя?');
INSERT INTO fix_verses VALUES ('B023C051V020', '23', 51, 20, 'Сыновья твои изнемогли, лежат по углам всех улиц, как сернав тенетах, исполненные гнева Господа, прещения Бога твоего.', 'Сыновья твои изнемогли, лежат по углам всех улиц, как серна в тенетах, исполненные гнева Господа, прещения Бога твоего.');
INSERT INTO fix_verses VALUES ('B023C051V022', '23', 51, 22, 'Так говорит Господь твой, Господь и Бог твой, отмщающий за Свой народ: вот, Я беру из руки твоей чашу опьянения, дрожжи изчаши ярости Моей: ты не будешь уже пить их,', 'Так говорит Господь твой, Господь и Бог твой, отмщающий за Свой народ: вот, Я беру из руки твоей чашу опьянения, дрожжи из чаши ярости Моей: ты не будешь уже пить их,');
INSERT INTO fix_verses VALUES ('B023C051V023', '23', 51, 23, 'И подам ее в руки мучителям твоим, которые говорили тебе: «пади ниц, чтобы нам пройти по тебе»; и ты хребет твой делал какбы землею и улицею для проходящих.', 'И подам ее в руки мучителям твоим, которые говорили тебе: «пади ниц, чтобы нам пройти по тебе»; и ты хребет твой делал как бы землею и улицею для проходящих.');
INSERT INTO fix_verses VALUES ('B023C065V021', '23', 65, 21, 'И буду строить домы и жить в них, и насаждать виноградники и есть плоды их.', 'И будут строить домы и жить в них, и насаждать виноградники и есть плоды их.');
INSERT INTO fix_verses VALUES ('B024C002V010', '24', 2, 10, 'Ибо пойдите на острова Хиттимские и посмотрите, и пошлите в Кидар и разведайте прилежно, и рассмотрите: было ли [там] что — нибудь подобное сему?', 'Ибо пойдите на острова Хиттимские и посмотрите, и пошлите в Кидар и разведайте прилежно, и рассмотрите: было ли [там] что-нибудь подобное сему?');
INSERT INTO fix_verses VALUES ('B024C003V015', '24', 3, 15, 'И дам вам пастырей по сердцу Моему, которые будут пасти вас с знанием и благоразумием', 'И дам вам пастырей по сердцу Моему, которые будут пасти вас с знанием и благоразумием.');
INSERT INTO fix_verses VALUES ('B024C032V025', '24', 32, 25, 'А Ты, Господи Боже, сказал мне: «купи себе поле за серебро и пригласи свидетелей, тогда как город отдается в руки Халдеев».', 'А Ты, Господи Боже, сказал мне: «купи себе поле за серебро и пригласи свидетелей», тогда как город отдается в руки Халдеев».');
INSERT INTO fix_verses VALUES ('B024C048V011', '24', 48, 11, 'Моав от юности своей был в покое, сидел на дрожжах своих и не был переливаем из сосуда с сосуд, и в плен не ходил; оттого оставался в нем вкус его, и запах его не изменялся.', 'Моав от юности своей был в покое, сидел на дрожжах своих и не был переливаем из сосуда в сосуд, и в плен не ходил; оттого оставался в нем вкус его, и запах его не изменялся.');
INSERT INTO fix_verses VALUES ('B026C032V024', '26', 32, 24, 'Так Елам со всем множеством своим вокруг гробницы его, все они пораженные, павшие от меча, которые необрезанными сошли в преисподнюю, которые распространили собою ужас на земле живых и несут позор свой с отшедшими в могилу.', 'Там Елам со всем множеством своим вокруг гробницы его, все они пораженные, павшие от меча, которые необрезанными сошли в преисподнюю, которые распространили собою ужас на земле живых и несут позор свой с отшедшими в могилу.');
INSERT INTO fix_verses VALUES ('B026C039V009', '26', 39, 9, 'Тогда жители городов Израилевых выйдут, и разведут огонь, и будут сожигать оружие, щиты и латы, луки и стрелы, и булавы и копья; семь лет буду жечь их.', 'Тогда жители городов Израилевых выйдут, и разведут огонь, и будут сожигать оружие, щиты и латы, луки и стрелы, и булавы и копья; семь лет будут жечь их.');
INSERT INTO fix_verses VALUES ('B027C003V028', '27', 3, 28, 'Тогда Навуходоносор сказал: благословен Бог Седраха, Мисаха и Авденаго,  Который послал Ангела Своего  и избавил рабов Своих,  которые надеялись на Него и не послушались царского повеления, и предали тела свои [огню], чтобы не служить и не поклоняться иному богу, кроме Бога своего!', 'Тогда Навуходоносор сказал: благословен Бог Седраха, Мисаха и Авденаго, Который послал Ангела Своего и избавил рабов Своих, которые надеялись на Него и не послушались царского повеления, и предали тела свои [огню], чтобы не служить и не поклоняться иному богу, кроме Бога своего!');
INSERT INTO fix_verses VALUES ('B027C004V001', '27', 3, 31, 'Навуходоносор царь всем народам, племенам и языкам, живущим', 'Навуходоносор царь всем народам, племенам и языкам, живущим по всей земле: мир вам да умножится!');
INSERT INTO fix_verses VALUES ('B028C005V008', '28', 5, 8, 'Вострубите рогом в Гиве, трубою в Раме; возглашайте в Беф — Авене: «за тобою, Вениамин!»', 'Вострубите рогом в Гиве, трубою в Раме; возглашайте в Беф-Авене: «за тобою, Вениамин!»');
INSERT INTO fix_verses VALUES ('B037C002V013', '37', 2, 13, 'Потом сказал Аггей: а если прикоснется ко всему этому кто — либо, осквернившийся от прикосновения к мертвецу: сделается ли это нечистым? И отвечали священники и сказали: будет нечистым.', 'Потом сказал Аггей: а если прикоснется ко всему этому кто-либо, осквернившийся от прикосновения к мертвецу: сделается ли это нечистым? И отвечали священники и сказали: будет нечистым.');
INSERT INTO fix_verses VALUES ('B038C010V007', '38', 10, 7, 'Как герой будет Ефрем; возвеселится сердце их, как от вина; и увидят это сыны их в возрадуются; в восторге будет сердце их о Господе.', 'Как герой будет Ефрем; возвеселится сердце их, как от вина; и увидят это сыны их и возрадуются; в восторге будет сердце их о Господе.');
INSERT INTO fix_verses VALUES ('B039C002V013', '39', 2, 13, 'И вот еще что вы делаете: вы заставляете обливать слезами жертвенник Господа с рыданием и воплем, так что Он уже не призирает более на приношение и не принимает умилоствительной жертвы из рук ваших.', 'И вот еще что вы делаете: вы заставляете обливать слезами жертвенник Господа с рыданием и воплем, так что Он уже не призирает более на приношение и не принимает умилостивительной жертвы из рук ваших.');
INSERT INTO fix_verses VALUES ('B040C013V028', '40', 13, 28, 'Он же сказал им: враг человека сделал это. А рабы сказали ему: хочешь ли, мы пойдем, выберем их?', 'Он же сказал им: враг человек сделал это. А рабы сказали ему: хочешь ли, мы пойдем, выберем их?');
INSERT INTO fix_verses VALUES ('B040C018V022', '40', 18, 22, 'Иисус говорит ему: не говорю тебе: до семи раз, но до седмижды семидесяти раз.', 'Иисус говорит ему: не говорю тебе: до семи, но до седмижды семидесяти раз.');
INSERT INTO fix_verses VALUES ('B040C027V035', '40', 27, 35, 'Распявшие же Его делили одежды его, бросая жребий;', 'Распявшие же Его делили одежды Его, бросая жребий;');
INSERT INTO fix_verses VALUES ('B041C008V020', '41', 8, 20, 'А когда семь для четырех тысяч, сколько корзин набрали вы оставшихся кусков. Сказали: семь.', 'А когда семь для четырех тысяч, сколько корзин набрали вы оставшихся кусков? Сказали: семь.');
INSERT INTO fix_verses VALUES ('B041C010V028', '41', 10, 28, 'И начал Петр говорить Ему: вот, мы оставили все ипоследовали за Тобою.', 'И начал Петр говорить Ему: вот, мы оставили все и последовали за Тобою.');
INSERT INTO fix_verses VALUES ('B041C010V043', '41', 10, 43, 'Но между вами да не будет так: а кто хочет быть большим между вами, да будем вам слугою;', 'Но между вами да не будет так: а кто хочет быть большим между вами, да будет вам слугою;');
INSERT INTO fix_verses VALUES ('B041C013V001', '41', 13, 1, 'И когда выходил Он из храма, говорит Ему один из учеников его: Учитель! посмотри, какие камни и какие здания!', 'И когда выходил Он из храма, говорит Ему один из учеников Его: Учитель! посмотри, какие камни и какие здания!');
INSERT INTO fix_verses VALUES ('B041C013V015', '41', 13, 15, 'А кто на кровле, тот не сходи в дом и не входи взять что — нибудь из дома своего;', 'А кто на кровле, тот не сходи в дом и не входи взять что-нибудь из дома своего;');
INSERT INTO fix_verses VALUES ('B043C006V015', '43', 6, 15, 'Иисус же, узнав, что хотят придти, нечаянно взять его и сделать царем, опять удалился на гору один.', 'Иисус же, узнав, что хотят придти, нечаянно взять Его и сделать царем, опять удалился на гору один.');
INSERT INTO fix_verses VALUES ('B043C006V042', '43', 6, 42, 'И говорили: не Иисус ли это, сын Иосифов, Которого отца и Мать мы знаем? Как же говорит Он: я сшел с небес?', 'И говорили: не Иисус ли это, сын Иосифов, Которого отца и Мать мы знаем? Как же говорит Он: Я сшел с небес?');
INSERT INTO fix_verses VALUES ('B043C013V029', '43', 13, 29, 'А как у Иуды был ящик, то некоторые думали, что Иисус говорит ему: купи, что нам нужно к празднику, или чтобы дал что — нибудь нищим.', 'А как у Иуды был ящик, то некоторые думали, что Иисус говорит ему: купи, что нам нужно к празднику, или чтобы дал что-нибудь нищим.');
INSERT INTO fix_verses VALUES ('B043C015V023', '43', 15, 23, 'Ненавидящий Меня ненавидит и Отца моего.', 'Ненавидящий Меня ненавидит и Отца Моего.');
INSERT INTO fix_verses VALUES ('B043C019V020', '43', 19, 20, 'Эту надпись читали многие из Иудеев, потому что место, где был распят Иисус, было недалеко от города, и написано было по — еврейски, по-гречески, по-римски.', 'Эту надпись читали многие из Иудеев, потому что место, где был распят Иисус, было недалеко от города, и написано было по-еврейски, по-гречески, по-римски.');
INSERT INTO fix_verses VALUES ('B044C003V005', '44', 3, 5, 'И он пристально смотрел на них, надеясь получить от них что — нибудь.', 'И он пристально смотрел на них, надеясь получить от них что-нибудь.');
INSERT INTO fix_verses VALUES ('B044C008V022', '44', 8, 22, 'Итак покайся в сем грехе твоем, и молись Богу: может быть, опустится тебе помысел сердца твоего;', 'Итак покайся в сем грехе твоем, и молись Богу: может быть, отпустится тебе помысел сердца твоего;');
INSERT INTO fix_verses VALUES ('B044C017V021', '44', 17, 21, 'Афиняне же все и живущие [у них] иностранцы ни в чем охотнее не проводили время, как в том, чтобы говорить или слушать что — нибудь новое.', 'Афиняне же все и живущие [у них] иностранцы ни в чем охотнее не проводили время, как в том, чтобы говорить или слушать что-нибудь новое.');
INSERT INTO fix_verses VALUES ('B044C024V005', '44', 24, 5, 'Найдя сего человека язвою [общества], возбудителем мятежа между иудеями, живущими по вселенной, и представителем Назорейской ереси,', 'Найдя сего человека язвою [общества], возбудителем мятежа между Иудеями, живущими по вселенной, и представителем Назорейской ереси,');
INSERT INTO fix_verses VALUES ('B044C025V016', '44', 25, 16, 'Я отвечал им, что у Римлян нет обыкновения выдавать какого — нибудь человека на смерть, прежде нежели обвиняемый будет иметь обвинителей налицо и получит свободу защищаться против обвинения.', 'Я отвечал им, что у Римлян нет обыкновения выдавать какого-нибудь человека на смерть, прежде нежели обвиняемый будет иметь обвинителей налицо и получит свободу защищаться против обвинения.');
INSERT INTO fix_verses VALUES ('B044C027V042', '44', 27, 42, 'Воины согласились было умертвить узников, чтобы кто — нибудь, выплыв, не убежал.', 'Воины согласились было умертвить узников, чтобы кто-нибудь, выплыв, не убежал.');
INSERT INTO fix_verses VALUES ('B045C001V007', '45', 1, 7, 'Всем находящимся в Риме возлюбленным Божиим, призванным святым: благодать вам и мир от Бога отца нашего и Господа Иисуса Христа.', 'Всем находящимся в Риме возлюбленным Божиим, призванным святым: благодать вам и мир от Бога Отца нашего и Господа Иисуса Христа.');
INSERT INTO fix_verses VALUES ('B045C002V010', '45', 2, 10, 'Напротив, слава и честь и мир всякому, делающему доброе, во — первых, Иудею, [потом] и Еллину!', 'Напротив, слава и честь и мир всякому, делающему доброе, во-первых, Иудею, [потом] и Еллину!');
INSERT INTO fix_verses VALUES ('B046C012V028', '46', 12, 28, 'И иных Бог поставил в Церкви, во-первых, Апостолами, во — вторых, пророками, в-третьих, учителями; далее, [иным дал] силы [чудодейственные], также дары исцелений, вспоможения, управления, разные языки.', 'И иных Бог поставил в Церкви, во-первых, Апостолами, во-вторых, пророками, в-третьих, учителями; далее, [иным дал] силы [чудодейственные], также дары исцелений, вспоможения, управления, разные языки.');
INSERT INTO fix_verses VALUES ('B046C013V011', '46', 13, 11, 'Когда я был младенцем, то по-младенчески говорил, по — младенчески мыслил, по-младенчески рассуждал; а как стал мужем, то оставил младенческое.', 'Когда я был младенцем, то по-младенчески говорил, по-младенчески мыслил, по-младенчески рассуждал; а как стал мужем, то оставил младенческое.');
INSERT INTO fix_verses VALUES ('B047C011V016', '47', 11, 16, 'Еще скажу: не почти кто-нибудь меня неразумным; а если не так, то примите меня, хотя как неразумного, чтобы и мне сколько — нибудь похвалиться.', 'Еще скажу: не почти кто-нибудь меня неразумным; а если не так, то примите меня, хотя как неразумного, чтобы и мне сколько-нибудь похвалиться.');
INSERT INTO fix_verses VALUES ('B049C006V012', '49', 6, 12, 'Потому что наша брань не против крови и плоти, но против начальств, против властей, против мироправителей тьмы века сего, против духов злобы поднебесной.', 'Потому что наша брань не против крови и плоти, но против начальств, против властей, против мироправителей тьмы века сего, против духов злобы поднебесных.');
INSERT INTO fix_verses VALUES ('B059C004V011', '59', 4, 11, 'Не злословьте друг друга, братия: кто злословит брата или судит брата своего, того злословит закон и судит закон; а если ты судишь закон, то ты не исполнитель закона, но судья.', 'Не злословьте друг друга, братия: кто злословит брата или судит брата своего, тот злословит закон и судит закон; а если ты судишь закон, то ты не исполнитель закона, но судья.');
INSERT INTO fix_verses VALUES ('B066C005V008', '66', 5, 8, 'И когда он взял книгу, тогда четыре животных и двадцать четыре старца пали пред Агнцем, имея каждый гусли и золотые чаши, полные фимиама, которые суть молитвы святых.', 'И когда Он взял книгу, тогда четыре животных и двадцать четыре старца пали пред Агнцем, имея каждый гусли и золотые чаши, полные фимиама, которые суть молитвы святых.');
INSERT INTO fix_verses VALUES ('B066C006V003', '66', 6, 3, 'И когда он снял вторую печать, я слышал второе животное, говорящее: иди и смотри.', 'И когда Он снял вторую печать, я слышал второе животное, говорящее: иди и смотри.');
INSERT INTO fix_verses VALUES ('B066C009V011', '66', 9, 11, 'Царем над собою она имела ангела бездны; имя ему по — еврейски Аваддон, а по-гречески Аполлион.', 'Царем над собою она имела ангела бездны; имя ему по-еврейски Аваддон, а по-гречески Аполлион.');
INSERT INTO fix_verses VALUES ('B066C011V017', '66', 11, 17, 'Говоря: благодарим Тебя, Господи Боже Вседержитель, Который еси и был и грядешь, что ты приял силу Твою великую и воцарился.', 'Говоря: благодарим Тебя, Господи Боже Вседержитель, Который еси и был и грядешь, что Ты приял силу Твою великую и воцарился.');
INSERT INTO fix_verses VALUES ('B066C014V004', '66', 14, 4, 'Это те, которые не осквернились с женами, ибо они девственники; это те, которые следуют за Агнцем, куда бы Он ни пошел. Они искуплены из людей, как первенцу Богу и Агнцу,', 'Это те, которые не осквернились с женами, ибо они девственники; это те, которые следуют за Агнцем, куда бы Он ни пошел. Они искуплены из людей, как первенцы Богу и Агнцу,');
